-- =============================================================================
-- Official JPJ KPP01 Textbook Question Bank Migration (EN / BM)
--
-- 1. Preserves all legacy question sets ('mock-1', 'mock-2', 'mock-3', 'quiz-pool')
--    so learners' historical mock_test_results and quiz_results review cleanly.
-- 2. Inserts 18 new textbook-grounded question sets (510 rows):
--    - Bahagian A Practice Sets: quiz-a-1 .. quiz-a-3 (3 x 15 = 45 questions)
--    - Bahagian B Practice Sets: quiz-b-1 .. quiz-b-3 (3 x 25 = 75 questions)
--    - Bahagian C Practice Sets (Class DA Auto): quiz-c-da-1 .. quiz-c-da-3 (3 x 15 = 45 questions)
--    - Bahagian C Practice Sets (Class D Manual): quiz-c-d-1 .. quiz-c-d-3 (3 x 15 = 45 questions)
--    - Class DA Automatic Mock Sets: mock-da-1 .. mock-da-3 (3 x 50 = 150 questions)
--    - Class D Manual Mock Sets: mock-d-1 .. mock-d-3 (3 x 50 = 150 questions)
-- 3. Updates public.kpp_practice_questions view to expose all practice sets (set_id LIKE 'quiz-%').
-- 4. Updates public.recompute_exam_score() trigger to accept both legacy and new textbook sets.
-- =============================================================================

INSERT INTO public.kpp_questions (
  id, category, set_id, order_index,
  question_en, question_ms, options_en, options_ms,
  correct_index, explanation_en, explanation_ms,
  image_url, source_url
) VALUES
  ('ee618bef-ff90-55c9-b380-fb17b9e98690'::uuid, 'road-signs', 'quiz-a-1', 3, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Side road to the left","T-junction ahead","Four-way intersection","Y-junction ahead"]'::jsonb, '["Simpang jalan di sebelah kiri","Persimpangan T di hadapan","Persimpangan empat hala","Persimpangan Y di hadapan"]'::jsonb, 2, 'This sign means four-way intersection. Look for vehicles approaching from both sides before proceeding.', 'Papan tanda ini bermaksud persimpangan empat hala. Perhatikan kenderaan yang datang dari kedua-dua sisi sebelum meneruskan perjalanan.', '/signs/4a3491aff2749365.svg', 'KPP General PDF page 40'),
  ('e95b8085-31e9-57c4-b725-860b5b44eb29'::uuid, 'road-signs', 'quiz-a-1', 9, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Side road to the left","Side road to the right","Staggered junction ahead","Angled branch to the left"]'::jsonb, '["Simpang jalan di sebelah kiri","Simpang jalan di sebelah kanan","Simpang yang diatur di hadapan","Simpang serong di sebelah kiri"]'::jsonb, 0, 'This sign means side road to the left.', 'Papan tanda ini bermaksud simpang jalan di sebelah kiri.', '/signs/e22292f492beec26.svg', 'KPP General PDF page 42'),
  ('15c5fc28-0956-5e95-8415-75796a5452fd'::uuid, 'road-signs', 'quiz-a-1', 10, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Side road to the left","Side road to the right","Staggered junction ahead","Angled branch to the left"]'::jsonb, '["Simpang jalan di sebelah kiri","Simpang jalan di sebelah kanan","Simpang yang diatur di hadapan","Simpang serong di sebelah kiri"]'::jsonb, 1, 'This sign means side road to the right.', 'Papan tanda ini bermaksud simpang jalan di sebelah kanan.', '/signs/12e8b0d727c5bdf1.svg', 'KPP General PDF page 42'),
  ('6de9f48d-76e8-57e6-9da5-f5c31344fdb5'::uuid, 'road-signs', 'quiz-a-1', 11, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Y-junction ahead","Four-way intersection","T-junction ahead","Roundabout ahead"]'::jsonb, '["Persimpangan Y di hadapan","Persimpangan empat hala","Persimpangan T di hadapan","Bulatan di hadapan"]'::jsonb, 2, 'This sign means t-junction ahead. Slow down, signal your turn and stop at the junction before proceeding safely.', 'Papan tanda ini bermaksud persimpangan T di hadapan. Perlahankan kenderaan, beri isyarat membelok dan berhenti di persimpangan sebelum meneruskan perjalanan dengan selamat.', '/signs/e3ccd470b3c6bc8e.svg', 'KPP General PDF page 42'),
  ('11a7d793-f8d2-5188-acd6-e158ecdb8de1'::uuid, 'road-signs', 'quiz-a-1', 13, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Pass either side of the island","Limited clearance ahead","Obstacle at the divider","Risk of falling rocks"]'::jsonb, '["Lalui pulau dari mana-mana sisi","Kelegaan laluan terhad di hadapan","Halangan di pembahagi jalan","Risiko runtuhan batu"]'::jsonb, 0, 'This sign means pass either side of the island. Choose a lane that leads where you intend to go and keep within it.', 'Papan tanda ini bermaksud lalui pulau dari mana-mana sisi. Pilih lorong yang menuju ke arah destinasi dan kekal dalam lorong itu.', '/signs/322e269754adeff6.svg', 'KPP General PDF page 44'),
  ('0144363e-2ef2-5472-a74b-783bc33f4774'::uuid, 'road-signs', 'quiz-a-2', 2, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Sharp left bend","Sharp right bend","Double bend, left first","Direction of a sharp bend"]'::jsonb, '["Selekoh tajam ke kiri","Selekoh tajam ke kanan","Dua selekoh, mula ke kiri","Arah selekoh yang tajam"]'::jsonb, 0, 'This sign means sharp left bend.', 'Papan tanda ini bermaksud selekoh tajam ke kiri.', '/signs/194637442da016e5.svg', 'KPP General PDF page 47'),
  ('a579b6a5-f867-53cf-a189-85d923173482'::uuid, 'road-signs', 'quiz-a-2', 3, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Sharp left bend","Sharp right bend","Double bend, left first","Direction of a sharp bend"]'::jsonb, '["Selekoh tajam ke kiri","Selekoh tajam ke kanan","Dua selekoh, mula ke kiri","Arah selekoh yang tajam"]'::jsonb, 1, 'This sign means sharp right bend.', 'Papan tanda ini bermaksud selekoh tajam ke kanan.', '/signs/8c4124b32afd3704.svg', 'KPP General PDF page 47'),
  ('9e23479a-a545-555e-901a-c7912696a0b2'::uuid, 'road-signs', 'quiz-a-2', 4, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Double bend, left first","Double bend, right first","Direction of a sharp bend","Sharp right bend"]'::jsonb, '["Dua selekoh, mula ke kiri","Dua selekoh, mula ke kanan","Arah selekoh yang tajam","Selekoh tajam ke kanan"]'::jsonb, 2, 'This sign means direction of a sharp bend.', 'Papan tanda ini bermaksud arah selekoh yang tajam.', '/signs/b716cb9e685088a5.svg', 'KPP General PDF page 47'),
  ('de032fdf-b2ff-5583-ac25-d16ea2e3e58c'::uuid, 'road-signs', 'quiz-a-2', 7, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Divided road begins","Divided road ends","Extra uphill lane","Steep uphill stretch"]'::jsonb, '["Jalan terbahagi dua bermula","Jalan terbahagi dua tamat","Lorong tambahan untuk mendaki","Jalan mendaki dengan curam"]'::jsonb, 1, 'This sign means divided road ends. Watch for vehicles coming the other way once the divider ends.', 'Papan tanda ini bermaksud jalan terbahagi dua tamat. Awasi kenderaan dari arah bertentangan selepas pembahagi jalan tamat.', '/signs/b12139221efc15b6.svg', 'KPP General PDF page 48'),
  ('6b6055c3-9599-5d1d-b5db-f5cdd94973b8'::uuid, 'road-signs', 'quiz-a-2', 8, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Extra downhill lane","Steep uphill stretch","Divided road begins","Divided road ends"]'::jsonb, '["Lorong tambahan untuk menurun","Jalan mendaki dengan curam","Jalan terbahagi dua bermula","Jalan terbahagi dua tamat"]'::jsonb, 2, 'This sign means divided road begins. Stay on the correct side as the divider separates the two streams of traffic.', 'Papan tanda ini bermaksud jalan terbahagi dua bermula. Kekal di sebelah yang betul apabila pembahagi jalan memisahkan dua aliran trafik.', '/signs/788d475c2d05336c.svg', 'KPP General PDF page 48'),
  ('1ed2bbf8-e87f-5705-80d8-05b12400cc34'::uuid, 'road-signs', 'quiz-a-2', 9, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["T-junction ahead","Y-junction ahead","Four-way intersection","Roundabout ahead"]'::jsonb, '["Persimpangan T di hadapan","Persimpangan Y di hadapan","Persimpangan empat hala","Bulatan di hadapan"]'::jsonb, 3, 'This sign means roundabout ahead. Pick the appropriate approach lane and yield to traffic already in the roundabout.', 'Papan tanda ini bermaksud bulatan di hadapan. Pilih lorong masuk yang sesuai dan beri laluan kepada kenderaan yang sudah berada dalam bulatan.', '/signs/d26a8ccc75c5a905.svg', 'KPP General PDF page 48'),
  ('0ed3f342-a506-5b15-b1de-ba8c951f2b6a'::uuid, 'road-signs', 'quiz-a-2', 10, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Two-way traffic ahead","Road narrows on the left","Extra downhill lane","Road narrows on the right"]'::jsonb, '["Lalu lintas dua hala di hadapan","Jalan menyempit di sebelah kiri","Lorong tambahan untuk menurun","Jalan menyempit di sebelah kanan"]'::jsonb, 0, 'This sign means two-way traffic ahead. Expect oncoming vehicles on the same road and check carefully before overtaking.', 'Papan tanda ini bermaksud lalu lintas dua hala di hadapan. Jangkakan kenderaan dari arah bertentangan di jalan yang sama dan periksa keadaan sebelum memotong.', '/signs/ea082fc0b4c65733.svg', 'KPP General PDF page 49'),
  ('0dfad1d5-7682-5219-9732-8ba1bd5e64ec'::uuid, 'road-signs', 'quiz-a-2', 13, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Road narrows on the right","Road narrows on the left","Two-way traffic ahead","Road narrows on both sides"]'::jsonb, '["Jalan menyempit di sebelah kanan","Jalan menyempit di sebelah kiri","Lalu lintas dua hala di hadapan","Jalan menyempit di kedua-dua sisi"]'::jsonb, 3, 'This sign means road narrows on both sides.', 'Papan tanda ini bermaksud jalan menyempit di kedua-dua sisi.', '/signs/ce68f8896451a2c9.svg', 'KPP General PDF page 50'),
  ('039bc376-de68-554e-8e23-9bfaf8c23138'::uuid, 'road-signs', 'quiz-a-2', 14, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Road narrows on the left","Road narrows on the right","Two-way traffic ahead","Road narrows on both sides"]'::jsonb, '["Jalan menyempit di sebelah kiri","Jalan menyempit di sebelah kanan","Lalu lintas dua hala di hadapan","Jalan menyempit di kedua-dua sisi"]'::jsonb, 0, 'This sign means road narrows on the left.', 'Papan tanda ini bermaksud jalan menyempit di sebelah kiri.', '/signs/2be93e13645351ef.svg', 'KPP General PDF page 50'),
  ('801072d7-872d-5134-9e43-a650da387398'::uuid, 'road-signs', 'quiz-a-2', 15, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Road narrows on both sides","Road narrows on the right","Road narrows on the left","Two-way traffic ahead"]'::jsonb, '["Jalan menyempit di kedua-dua sisi","Jalan menyempit di sebelah kanan","Jalan menyempit di sebelah kiri","Lalu lintas dua hala di hadapan"]'::jsonb, 1, 'This sign means road narrows on the right.', 'Papan tanda ini bermaksud jalan menyempit di sebelah kanan.', '/signs/e08ca85fb4d9816f.svg', 'KPP General PDF page 50'),
  ('086c2471-8b72-5702-b170-8cdcb30b6d2c'::uuid, 'road-signs', 'quiz-a-3', 1, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Divided road begins","Steep downhill stretch","Steep uphill stretch","Divided road ends"]'::jsonb, '["Jalan terbahagi dua bermula","Jalan menurun dengan curam","Jalan mendaki dengan curam","Jalan terbahagi dua tamat"]'::jsonb, 2, 'This sign means steep uphill stretch. Select a lower gear to get the power needed to climb.', 'Papan tanda ini bermaksud jalan mendaki dengan curam. Gunakan gear rendah untuk mendapatkan kuasa yang diperlukan semasa mendaki.', '/signs/fa01479a3e275ae3.svg', 'KPP General PDF page 50'),
  ('0bfcb0c3-b39a-57bc-9bf0-f0047509c9c5'::uuid, 'road-signs', 'quiz-a-3', 2, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Steep uphill stretch","Divided road begins","Divided road ends","Steep downhill stretch"]'::jsonb, '["Jalan mendaki dengan curam","Jalan terbahagi dua bermula","Jalan terbahagi dua tamat","Jalan menurun dengan curam"]'::jsonb, 3, 'This sign means steep downhill stretch. Select a lower gear to help control your speed on the descent.', 'Papan tanda ini bermaksud jalan menurun dengan curam. Gunakan gear rendah untuk membantu mengawal kelajuan semasa menurun.', '/signs/eb9c555ec03577f6.svg', 'KPP General PDF page 50'),
  ('e635661c-ba6a-5315-9691-ab6905c3e516'::uuid, 'road-signs', 'quiz-a-3', 3, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Narrow bridge ahead","Uneven road surface","Road hump ahead","Slippery road surface"]'::jsonb, '["Jambatan sempit di hadapan","Permukaan jalan tidak rata","Bonggol jalan di hadapan","Permukaan jalan licin"]'::jsonb, 0, 'This sign means narrow bridge ahead. Slow down and give way if a vehicle coming the other way is closer to the bridge.', 'Papan tanda ini bermaksud jambatan sempit di hadapan. Perlahankan kenderaan dan beri laluan jika kenderaan dari arah bertentangan lebih hampir dengan jambatan.', '/signs/d1e9a6d6aab128b3.svg', 'KPP General PDF page 51'),
  ('b871c12d-17a8-5be3-aa85-59b3a74e7ff9'::uuid, 'road-signs', 'quiz-a-3', 4, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Uneven road surface","Slippery road surface","Soft road shoulder","Narrow bridge ahead"]'::jsonb, '["Permukaan jalan tidak rata","Permukaan jalan licin","Bahu jalan lembut","Jambatan sempit di hadapan"]'::jsonb, 1, 'This sign means slippery road surface. Slow smoothly, avoid hard braking and leave a safe gap.', 'Papan tanda ini bermaksud permukaan jalan licin. Perlahankan kenderaan dengan lancar, elakkan brek mengejut dan kekalkan jarak selamat.', '/signs/9702f462c37241a4.svg', 'KPP General PDF page 51'),
  ('5b0ce5f6-6dae-5e84-ad18-b9244a674278'::uuid, 'road-signs', 'quiz-a-3', 7, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Stop sign ahead","Traffic lights ahead","Give-way sign ahead","Speed limit zone ahead"]'::jsonb, '["Tanda berhenti di hadapan","Lampu isyarat di hadapan","Tanda beri laluan di hadapan","Zon had laju di hadapan"]'::jsonb, 0, 'This sign means stop sign ahead. Slow down early and be ready to come to a complete stop at the actual stop sign.', 'Papan tanda ini bermaksud tanda berhenti di hadapan. Perlahankan kenderaan awal dan bersedia untuk berhenti sepenuhnya di tanda berhenti sebenar.', '/signs/add368369889404d.svg', 'KPP General PDF page 52'),
  ('0b5d54c2-1a23-5262-bc01-bf0523ebb6ce'::uuid, 'road-signs', 'quiz-a-3', 8, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Risk of falling rocks","Other hazard ahead","Obstacle at the divider","Limited clearance ahead"]'::jsonb, '["Risiko runtuhan batu","Bahaya lain di hadapan","Halangan di pembahagi jalan","Kelegaan laluan terhad di hadapan"]'::jsonb, 1, 'This sign means other hazard ahead.', 'Papan tanda ini bermaksud bahaya lain di hadapan.', '/signs/3f13bbd2ffe5c466.svg', 'KPP General PDF page 52'),
  ('bbec7bfb-a098-56dd-ad8f-f5138bc008e9'::uuid, 'road-signs', 'quiz-a-3', 10, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Other hazard ahead","Obstacle at the divider","Limited clearance ahead","Risk of falling rocks"]'::jsonb, '["Bahaya lain di hadapan","Halangan di pembahagi jalan","Kelegaan laluan terhad di hadapan","Risiko runtuhan batu"]'::jsonb, 3, 'This sign means risk of falling rocks. Watch the road for fallen material before continuing.', 'Papan tanda ini bermaksud risiko runtuhan batu. Perhatikan bahan runtuhan di jalan sebelum meneruskan perjalanan.', '/signs/adc5145404e740b4.svg', 'KPP General PDF page 53'),
  ('55eb8233-72e9-5c46-a063-d9ff5be486fa'::uuid, 'road-signs', 'quiz-a-3', 14, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Pedestrian crossing ahead","Schoolchildren may cross","Playground nearby","Blind pedestrians may cross"]'::jsonb, '["Lintasan pejalan kaki di hadapan","Murid sekolah mungkin melintas","Taman permainan berhampiran","Orang buta mungkin melintas"]'::jsonb, 3, 'This sign means blind pedestrians may cross. Slow down, give people time to cross and avoid sounding the horn.', 'Papan tanda ini bermaksud orang buta mungkin melintas. Perlahankan kenderaan, beri masa untuk orang melintas dan elakkan membunyikan hon.', '/signs/f986766e1fca4c02.svg', 'KPP General PDF page 54'),
  ('3c07c163-fe3e-5098-9651-951a404e55e4'::uuid, 'traffic-rules', 'quiz-b-1', 1, 'How do you calculate the full distance a moving car needs to stop?', 'Bagaimanakah anda mengira jumlah jarak yang diperlukan untuk memberhentikan kereta yang bergerak?', '["Add reaction and braking distances","Subtract reaction from braking distance","Double the braking distance","Average reaction and braking distances"]'::jsonb, '["Tambah jarak reaksi dan jarak membrek","Tolak jarak reaksi daripada jarak membrek","Gandakan jarak membrek","Kira purata jarak reaksi dan jarak membrek"]'::jsonb, 0, 'The car travels while you react and continues moving after you press the brake. Add both distances.', 'Kereta bergerak semasa anda bertindak balas dan terus bergerak selepas anda menekan brek. Tambahkan kedua-dua jarak itu.', NULL, 'KPP Kelas D Automatik, PDF page 264'),
  ('c892bc41-44fe-54e5-9ade-bf2718126cda'::uuid, 'traffic-rules', 'quiz-b-1', 2, 'A driver spots an obstacle and moves a foot towards the brake. What is this stage called?', 'Pemandu nampak halangan dan menggerakkan kaki ke arah pedal brek. Apakah nama fasa ini?', '["Braking","Reaction","Acceleration","Coasting"]'::jsonb, '["Membrek","Reaksi","Pecutan","Meluncur"]'::jsonb, 1, 'Reaction distance begins when you notice the hazard and ends when you apply the brakes.', 'Jarak reaksi bermula apabila anda menyedari bahaya dan berakhir apabila anda menekan brek.', NULL, 'KPP Kelas D Automatik, PDF page 264'),
  ('749ee520-b9cd-5948-b8a9-59897d445f3a'::uuid, 'traffic-rules', 'quiz-b-1', 3, 'At 60 km/h, a driver covers 17 metres before pressing the pedal and 44 metres before stopping. How far does the car travel after the pedal is pressed?', 'Pada kelajuan 60 km/j, pemandu bergerak sejauh 17 meter sebelum menekan pedal dan 44 meter sebelum berhenti. Berapakah jarak yang dilalui selepas pedal ditekan?', '["17 metres","22 metres","27 metres","32 metres"]'::jsonb, '["17 meter","22 meter","27 meter","32 meter"]'::jsonb, 2, 'In the example, you travel 17 metres before pressing the brake and a further 27 metres before stopping. Actual distances depend on conditions.', 'Dalam contoh ini, anda bergerak 17 meter sebelum menekan brek dan 27 meter lagi sebelum berhenti. Jarak sebenar bergantung pada keadaan.', NULL, 'KPP Kelas D Automatik, PDF page 264'),
  ('7200f656-55e8-581d-8955-ffa003b718ac'::uuid, 'traffic-rules', 'quiz-b-1', 4, 'You are close to a junction and realise you are in the wrong lane for your turn. What should you avoid?', 'Anda hampir tiba di persimpangan dan baru sedar anda berada di lorong yang salah untuk membelok. Apakah yang perlu dielakkan?', '["Continuing in your lane","Making a last-second turn","Checking traffic around you","Changing your planned route"]'::jsonb, '["Meneruskan perjalanan di lorong anda","Membelok secara tiba-tiba","Memeriksa trafik di sekeliling","Mengubah laluan yang dirancang"]'::jsonb, 1, 'Choose your lane before arriving. A sudden change of direction at the junction can endanger others.', 'Pilih lorong sebelum tiba. Perubahan arah secara tiba-tiba di persimpangan boleh membahayakan orang lain.', NULL, 'Kurikulum Pendidikan Pemandu, PDF page 126'),
  ('2f25f892-1b8c-583e-8932-00294335fbf9'::uuid, 'traffic-rules', 'quiz-b-1', 5, 'You have priority at a junction. How should you approach it?', 'Anda mempunyai keutamaan di persimpangan. Bagaimanakah anda perlu menghampirinya?', '["Keep your current speed","Speed up before crossing","Slow down before crossing","Slow down after crossing"]'::jsonb, '["Kekalkan kelajuan semasa","Tambah kelajuan sebelum melintas","Perlahankan kenderaan sebelum melintas","Perlahankan kenderaan selepas melintas"]'::jsonb, 2, 'Reduce speed at a junction even when you have priority.', 'Perlahankan kenderaan di persimpangan walaupun anda mempunyai keutamaan.', NULL, 'Kurikulum Pendidikan Pemandu, PDF page 126'),
  ('a3caf613-80e6-51ec-86c5-24c6ef20f1ee'::uuid, 'traffic-rules', 'quiz-b-1', 6, 'What helps other drivers understand that you plan to turn at a junction?', 'Apakah yang membantu pemandu lain memahami bahawa anda hendak membelok di persimpangan?', '["Correct lane and early signal","Correct lane and late signal","Any lane and early signal","Any lane and late signal"]'::jsonb, '["Lorong betul dan isyarat awal","Lorong betul dan isyarat lewat","Mana-mana lorong dan isyarat awal","Mana-mana lorong dan isyarat lewat"]'::jsonb, 0, 'Position the car in the correct lane and signal before you manoeuvre.', 'Letakkan kereta di lorong yang betul dan beri isyarat sebelum melakukan olah gerak.', NULL, 'Kurikulum Pendidikan Pemandu, PDF page 127'),
  ('48540c8d-c1ae-5b7a-9ab9-e7a5c72a1dd1'::uuid, 'traffic-rules', 'quiz-b-1', 7, 'Which areas should you check immediately before moving out to pass a car?', 'Kawasan manakah yang perlu diperiksa sejurus sebelum keluar dari lorong untuk memotong kereta?', '["Behind and beside your car","Ahead and along the shoulder","Ahead and beside your car","Behind and along the shoulder"]'::jsonb, '["Belakang dan sisi kereta anda","Hadapan dan sepanjang bahu jalan","Hadapan dan sisi kereta anda","Belakang dan sepanjang bahu jalan"]'::jsonb, 0, 'Check behind and to the side before moving right. A vehicle could already be overtaking you.', 'Periksa keadaan di belakang dan di sisi sebelum bergerak ke kanan. Kenderaan lain mungkin sedang memotong anda.', NULL, 'Kurikulum Pendidikan Pemandu, PDF page 123'),
  ('827f3a44-961f-585a-aa78-90c8fb2067d8'::uuid, 'traffic-rules', 'quiz-b-1', 8, 'What should you see in the side mirror before returning to your lane after passing a car?', 'Apakah yang perlu kelihatan dalam cermin sisi sebelum anda kembali ke lorong asal selepas memotong kereta?', '["The front of the car you passed","The side of the car you passed","The rear of the car ahead","The front of the next car ahead"]'::jsonb, '["Bahagian depan kereta yang dipotong","Bahagian sisi kereta yang dipotong","Bahagian belakang kereta di hadapan","Bahagian depan kereta seterusnya"]'::jsonb, 0, 'Check the left mirror for the front of the car you passed. Return only when the lane is clear.', 'Lihat bahagian depan kereta yang dipotong melalui cermin kiri. Masuk semula hanya apabila lorong selamat.', NULL, 'Kurikulum Pendidikan Pemandu, PDF page 123'),
  ('5df63d85-8e4a-5252-b8dd-3ed431cf8d16'::uuid, 'traffic-rules', 'quiz-b-1', 9, 'You reach your roadside marker before finishing the count. How should you check your next following gap?', 'Anda tiba di penanda tepi jalan sebelum selesai mengira. Bagaimanakah anda perlu menyemak jarak mengekori selepas itu?', '["Ease off, then pick another marker","Hold speed, then pick another marker","Ease off, then reuse the same marker","Hold speed, then use the moving car"]'::jsonb, '["Perlahankan kenderaan, kemudian pilih penanda lain","Kekalkan kelajuan, kemudian pilih penanda lain","Perlahankan kenderaan, kemudian guna semula penanda yang sama","Kekalkan kelajuan, kemudian guna kereta yang bergerak"]'::jsonb, 0, 'You are following too closely. Slow down, choose another fixed marker and repeat the count.', 'Anda mengekori terlalu rapat. Perlahankan kenderaan, pilih penanda tetap yang lain dan ulang kiraan.', NULL, 'Kurikulum Pendidikan Pemandu, PDF page 119'),
  ('a7cfc02a-479e-5453-b1da-1fabc9f55e4d'::uuid, 'traffic-rules', 'quiz-b-1', 10, 'You have enough room to overtake. When should you signal right?', 'Anda mempunyai ruang yang cukup untuk memotong. Bilakah anda perlu memberi isyarat kanan?', '["After entering the other lane","While entering the other lane","Just as you cross the lane line","Before leaving your lane"]'::jsonb, '["Selepas memasuki lorong sebelah","Semasa memasuki lorong sebelah","Sebaik sahaja melintasi garisan lorong","Sebelum meninggalkan lorong anda"]'::jsonb, 3, 'Signal right at least three seconds before moving right to overtake.', 'Beri isyarat kanan sekurang-kurangnya tiga saat sebelum bergerak ke kanan untuk memotong.', NULL, 'Kurikulum Pendidikan Pemandu, PDF page 123'),
  ('6896c4b7-0563-5124-87ca-e7d1c65302d6'::uuid, 'traffic-rules', 'quiz-b-1', 11, 'On a dry road with good visibility, what is the usual minimum following time?', 'Di jalan kering dengan jarak penglihatan yang baik, berapakah tempoh minimum yang lazim untuk mengekori?', '["1 second","2 seconds","3 seconds","4 seconds"]'::jsonb, '["1 saat","2 saat","3 saat","4 saat"]'::jsonb, 1, 'Allow at least two seconds behind the vehicle ahead in normal conditions.', 'Kekalkan jarak sekurang-kurangnya dua saat di belakang kenderaan di hadapan dalam keadaan biasa.', NULL, 'Kurikulum Pendidikan Pemandu, PDF pages 118–119'),
  ('7f464b9c-a62a-57e4-bef7-4cb087f3598c'::uuid, 'traffic-rules', 'quiz-b-1', 12, 'What following gap should you leave when the road becomes slippery?', 'Berapakah jarak masa mengekori yang patut dikekalkan apabila jalan menjadi licin?', '["One second","Two seconds","Three seconds","Four seconds"]'::jsonb, '["Satu saat","Dua saat","Tiga saat","Empat saat"]'::jsonb, 3, 'Use a longer gap on slippery roads. The four-second rule also applies in poor weather and when towing or being tailgated.', 'Jarakkan kenderaan apabila jalan licin. Peraturan empat saat juga digunakan semasa cuaca buruk, ketika menarik beban atau apabila diekori terlalu rapat.', NULL, 'Kurikulum Pendidikan Pemandu, PDF page 120'),
  ('8d7c0d3f-3036-57da-9f3f-edecc0eb2d41'::uuid, 'traffic-rules', 'quiz-b-1', 13, 'When do you start counting to check your following gap?', 'Bilakah anda mula mengira untuk menyemak jarak mengekori?', '["When you first see a marker","When your car reaches the marker","When the car ahead passes the marker","When the car ahead passes another car"]'::jsonb, '["Apabila anda mula nampak penanda","Apabila kereta anda sampai di penanda","Apabila kereta di hadapan melepasi penanda","Apabila kereta di hadapan memotong kereta lain"]'::jsonb, 2, 'Pick a fixed marker such as a tree. Count from the moment the leading car passes it.', 'Pilih penanda tetap seperti pokok. Mula mengira apabila kereta di hadapan melepasi penanda itu.', NULL, 'Kurikulum Pendidikan Pemandu, PDF page 118'),
  ('456eb987-e1f2-59f2-be1a-2fa6c978eca9'::uuid, 'traffic-rules', 'quiz-b-1', 14, 'What is the 12-second check used for before overtaking?', 'Apakah tujuan pemeriksaan 12 saat sebelum memotong?', '["To scan the road ahead","To time the signal flashes","To measure your following gap","To time the whole manoeuvre"]'::jsonb, '["Untuk mengimbas jalan di hadapan","Untuk mengira tempoh kelipan isyarat","Untuk mengukur jarak mengekori","Untuk mengira tempoh seluruh olah gerak"]'::jsonb, 0, 'Look ahead for potential hazards over the distance you will cover in about 12 seconds.', 'Imbas ke hadapan untuk mengesan bahaya yang mungkin timbul dalam jarak yang akan dilalui dalam kira-kira 12 saat.', NULL, 'Kurikulum Pendidikan Pemandu, PDF pages 122–123'),
  ('3603e7b5-a719-5c00-8458-8c48356208ae'::uuid, 'traffic-rules', 'quiz-b-1', 15, 'In a stopped queue, what should still be visible in front of you?', 'Dalam barisan kenderaan yang berhenti, apakah yang patut masih kelihatan di hadapan anda?', '["The car’s rear window","The car’s rear wheels","The car’s registration plate","The car’s brake lights"]'::jsonb, '["Cermin belakang kereta hadapan","Roda belakang kereta hadapan","Nombor pendaftaran kereta hadapan","Lampu brek kereta hadapan"]'::jsonb, 1, 'Leave enough room to see the rear wheels of the car ahead and move out if it breaks down.', 'Tinggalkan ruang yang cukup untuk melihat roda belakang kereta di hadapan dan keluar dari barisan jika kereta itu rosak.', NULL, 'KPP Kelas D Automatik, PDF page 263'),
  ('5eeb0ccd-c996-56e2-8736-a31522cc6510'::uuid, 'traffic-rules', 'quiz-b-1', 16, 'After checking the mirrors and signalling, what is the next CITO step before changing lanes?', 'Selepas memeriksa cermin dan memberi isyarat, apakah langkah CITO seterusnya sebelum menukar lorong?', '["Check your speed","Change to a lower gear","Check the blind spot","Start moving across"]'::jsonb, '["Semak kelajuan anda","Tukar ke gear lebih rendah","Periksa titik buta","Mula masuk ke lorong sebelah"]'::jsonb, 2, 'The T in CITO means titik buta. Look over your shoulder to check what the mirrors miss.', 'T dalam CITO bermaksud titik buta. Toleh ke paras bahu untuk melihat kawasan yang tidak kelihatan dalam cermin.', NULL, 'Kurikulum Pendidikan Pemandu, PDF page 115'),
  ('3d7c8444-cfe5-583c-8712-852f96d09047'::uuid, 'traffic-rules', 'quiz-b-1', 17, 'After choosing your position at a junction, what should you adjust before selecting a gear?', 'Selepas menentukan posisi di persimpangan, apakah yang perlu dilaraskan sebelum memilih gear?', '["Your speed","Your seat position","Your headlight beam","Your interior mirror"]'::jsonb, '["Kelajuan","Kedudukan tempat duduk","Pancaran lampu hadapan","Cermin pandang belakang"]'::jsonb, 0, 'Choose a safe speed for the junction, then select a gear that suits it.', 'Pilih kelajuan yang selamat untuk persimpangan, kemudian gunakan gear yang sepadan.', NULL, 'KPP Automatic Driving Curriculum, PDF page 109'),
  ('aef65697-00e5-5b3e-bcff-607307da4596'::uuid, 'traffic-rules', 'quiz-b-1', 18, 'What should you do to check a blind spot before moving sideways?', 'Apakah tindakan anda untuk memeriksa titik buta sebelum bergerak ke sisi?', '["Look over your shoulder","Look in the rear-view mirror","Watch the car ahead","Watch the lane marking"]'::jsonb, '["Toleh ke arah bahu","Lihat cermin pandang belakang","Perhatikan kereta di hadapan","Perhatikan garisan lorong"]'::jsonb, 0, 'A shoulder check covers the area that the mirrors cannot show.', 'Tolehan ke arah bahu membantu memeriksa kawasan yang tidak kelihatan dalam cermin.', NULL, 'KPP Automatic Driving Curriculum, PDF page 98'),
  ('fbfa0b80-12eb-5083-b9d6-5db969e6e036'::uuid, 'traffic-rules', 'quiz-b-1', 19, 'When should you decide which way to go at a junction?', 'Bilakah anda patut menentukan arah di persimpangan?', '["Before reaching the junction","As you cross the junction","After entering the junction","When the vehicle behind signals"]'::jsonb, '["Sebelum tiba di persimpangan","Semasa melintasi persimpangan","Selepas memasuki persimpangan","Apabila kenderaan di belakang memberi isyarat"]'::jsonb, 0, 'Plan your route early so you can position the vehicle without a last-minute change.', 'Rancang arah lebih awal supaya anda boleh memilih posisi tanpa menukar haluan pada saat akhir.', NULL, 'KPP Automatic Driving Curriculum, PDF page 108'),
  ('6b874ff2-51c2-5b46-b811-be0fefb5171b'::uuid, 'traffic-rules', 'quiz-b-1', 20, 'What changes when you drop back from a tall vehicle you are following?', 'Apakah yang berubah apabila anda menambah jarak di belakang kenderaan tinggi?', '["More of the road ahead comes into view","The vehicle ahead fills more of the view","The view ahead stays the same","Less of the road ahead can be seen"]'::jsonb, '["Lebih banyak jalan di hadapan dapat dilihat","Kenderaan di hadapan memenuhi lebih banyak pandangan","Pandangan di hadapan kekal sama","Kurang jalan di hadapan dapat dilihat"]'::jsonb, 0, 'With more space, the vehicle ahead blocks less of your view.', 'Dengan ruang tambahan, kenderaan di hadapan kurang menghalang pandangan anda.', NULL, 'KPP Automatic Driving Curriculum, PDF page 104'),
  ('b56eedce-474f-5a4d-a8a1-52b6ea5ae9f5'::uuid, 'traffic-rules', 'quiz-b-1', 21, 'Why scan well ahead before overtaking?', 'Mengapa perlu mengimbas jauh ke hadapan sebelum memotong?', '["To check whether the road ahead is clear","To check whether the next car is slowing","To judge the gap behind your own car","To estimate how closely you can follow"]'::jsonb, '["Untuk memastikan jalan di hadapan lapang","Untuk melihat sama ada kereta hadapan memperlahankan kenderaan","Untuk menganggar jarak di belakang kereta sendiri","Untuk menganggar jarak mengekori terdekat"]'::jsonb, 0, 'A forward scan helps you judge if the road is clear for the manoeuvre.', 'Imbasan ke hadapan membantu anda menilai sama ada laluan lapang untuk memotong.', NULL, 'KPP General, PDF page 122'),
  ('380261ba-245e-5fc2-97fe-3e30bbb95d04'::uuid, 'traffic-rules', 'quiz-b-1', 22, 'Which mirror should show the front of a vehicle you have just passed before you move left?', 'Cermin manakah yang patut menunjukkan bahagian hadapan kenderaan yang baru dipotong sebelum anda bergerak ke kiri?', '["Left side mirror","Right side mirror","Interior mirror","Any of the mirrors"]'::jsonb, '["Cermin sisi kiri","Cermin sisi kanan","Cermin pandang belakang","Mana-mana cermin"]'::jsonb, 0, 'Check the left side mirror and make sure it is safe before moving back.', 'Periksa cermin sisi kiri dan pastikan selamat sebelum kembali ke kiri.', NULL, 'KPP Automatic Driving Curriculum, PDF page 105'),
  ('f2aa68f5-5795-5641-aa93-61f8dba55ecd'::uuid, 'traffic-rules', 'quiz-b-1', 23, 'You are already alongside a vehicle you are passing. Which gap still matters?', 'Anda sudah berada di sebelah kenderaan yang dipotong. Jarak manakah masih perlu dijaga?', '["The gap between the sides of both vehicles","The gap behind the vehicle being passed","The gap to the centre line only","The gap to the vehicle behind you"]'::jsonb, '["Jarak antara sisi kedua-dua kenderaan","Jarak di belakang kenderaan yang dipotong","Jarak ke garisan tengah sahaja","Jarak ke kenderaan di belakang anda"]'::jsonb, 0, 'Keep a safe lateral gap throughout the pass.', 'Kekalkan jarak sisi yang selamat sepanjang tindakan memotong.', NULL, 'KPP Automatic Driving Curriculum, PDF page 105'),
  ('a8aa56e7-4aea-5513-beb7-e1eb1c89fe14'::uuid, 'traffic-rules', 'quiz-b-1', 24, 'When passing a vehicle on a clear two-way road, which side should you normally move to?', 'Ketika memotong di jalan dua hala yang lapang, ke arah manakah anda biasanya perlu bergerak?', '["To the right","To the left","Onto the shoulder","Toward the centre of your lane"]'::jsonb, '["Ke kanan","Ke kiri","Ke bahu jalan","Ke tengah lorong sendiri"]'::jsonb, 0, 'Check the road and surrounding traffic before moving right to pass.', 'Periksa jalan dan trafik sekeliling sebelum bergerak ke kanan untuk memotong.', NULL, 'KPP Automatic Driving Curriculum, PDF page 105'),
  ('0d97dca7-2614-5fcb-b113-146a76b77964'::uuid, 'traffic-rules', 'quiz-b-1', 25, 'You catch a slow car near the crest of a hill. When should you consider passing?', 'Anda menghampiri kereta perlahan berhampiran puncak bukit. Bilakah anda patut mempertimbangkan untuk memotong?', '["After the road ahead is clear","Just before the crest","As you reach the crest","As soon as the car slows"]'::jsonb, '["Selepas laluan di hadapan jelas","Sebelum tiba di puncak","Sebaik tiba di puncak","Sebaik kereta itu memperlahankan kenderaan"]'::jsonb, 0, 'Wait until past the crest and check that there is clear road ahead.', 'Tunggu sehingga melepasi puncak dan pastikan laluan di hadapan jelas.', NULL, 'KPP Automatic Driving Curriculum, PDF page 106'),
  ('022d01dc-f60b-5df8-b24f-91df789664e6'::uuid, 'traffic-rules', 'quiz-b-2', 1, 'A vehicle slows near a pedestrian crossing. What should you do?', 'Sebuah kenderaan memperlahankan kelajuan berhampiran lintasan pejalan kaki. Apakah tindakan anda?', '["Slow down and stay behind","Pass before the crossing","Pass while on the crossing","Go around it using the shoulder"]'::jsonb, '["Perlahankan dan kekal di belakang","Potong sebelum lintasan","Potong di atas lintasan","Lalui kenderaan itu di bahu jalan"]'::jsonb, 0, 'Avoid overtaking near pedestrian crossings. The vehicle ahead may be yielding to someone.', 'Elakkan memotong berhampiran lintasan pejalan kaki. Kenderaan di hadapan mungkin sedang memberi laluan.', NULL, 'KPP Automatic Driving Curriculum, PDF page 106'),
  ('e2e211bc-64c3-51d9-8f51-630523e34eed'::uuid, 'traffic-rules', 'quiz-b-2', 2, 'The car behind needs to see you slowing. Which lights should you check before leaving?', 'Pemandu di belakang perlu melihat apabila anda memperlahankan kenderaan. Lampu manakah yang patut diperiksa sebelum bertolak?', '["Brake lights","Reversing lights","Direction indicators","Rear fog lights"]'::jsonb, '["Lampu brek","Lampu undur","Lampu isyarat","Lampu kabus belakang"]'::jsonb, 0, 'Brake lights must work so following drivers can see you slowing.', 'Lampu brek mesti berfungsi supaya pemandu di belakang boleh melihat anda memperlahankan kenderaan.', NULL, 'KPP Automatic Driving Curriculum, PDF page 120'),
  ('96f0c708-1daa-519b-aad4-f748b93ebcc7'::uuid, 'traffic-rules', 'quiz-b-2', 3, 'A driver follows you too closely. What following gap should you leave ahead?', 'Pemandu di belakang mengekori terlalu rapat. Berapakah jarak masa yang patut anda tinggalkan di hadapan?', '["Four seconds","Two seconds","One second","Half a second"]'::jsonb, '["Empat saat","Dua saat","Satu saat","Setengah saat"]'::jsonb, 0, 'Leave more space in front so you have time to slow down gradually.', 'Tinggalkan lebih ruang di hadapan supaya anda boleh memperlahankan kenderaan secara beransur-ansur.', NULL, 'KPP Automatic Driving Curriculum, PDF page 102'),
  ('27b2f825-a77a-54ec-8017-bfbc51ab0e9c'::uuid, 'traffic-rules', 'quiz-b-2', 4, 'An oncoming vehicle drifts into your lane. Which direction should you move if there is room?', 'Kenderaan dari arah bertentangan memasuki lorong anda. Ke arah manakah patut anda bergerak jika ada ruang?', '["Move to the left","Move to the right","Hold the same line","Follow the other vehicle’s path"]'::jsonb, '["Bergerak ke kiri","Bergerak ke kanan","Kekalkan laluan yang sama","Ikut laluan kenderaan itu"]'::jsonb, 0, 'Move left if safe and warn the oncoming driver with your horn or a flash of the headlights.', 'Bergerak ke kiri jika selamat dan beri amaran dengan hon atau kelipan lampu hadapan.', NULL, 'KPP Automatic Driving Curriculum, PDF page 107'),
  ('98e3b156-f5a3-5858-9044-0b1ef99119c8'::uuid, 'traffic-rules', 'quiz-b-2', 5, 'You want to take the first exit at a two-lane roundabout. How do you enter?', 'Anda hendak mengambil susur keluar pertama di bulatan dua lorong. Bagaimanakah anda perlu masuk?', '["Left lane, right signal","Right lane, left signal","Left lane, left signal","Right lane, right signal"]'::jsonb, '["Lorong kiri, isyarat kanan","Lorong kanan, isyarat kiri","Lorong kiri, isyarat kiri","Lorong kanan, isyarat kanan"]'::jsonb, 2, 'Signal left as you approach, enter the left lane and keep signalling left through the exit.', 'Beri isyarat kiri ketika menghampiri bulatan, masuk ke lorong kiri dan kekalkan isyarat sehingga keluar.', NULL, 'KPP Kelas D Automatik, PDF page 258'),
  ('6dcd330d-4a32-5383-817f-3a76e538698e'::uuid, 'traffic-rules', 'quiz-b-2', 6, 'You are taking the second exit at a two-lane roundabout. When should you signal left?', 'Anda akan mengambil susur keluar kedua di bulatan dua lorong. Bilakah anda patut memberi isyarat kiri?', '["Just after passing the first exit","Before entering the roundabout","Just before reaching the first exit","After leaving the roundabout"]'::jsonb, '["Sejurus selepas melepasi susur pertama","Sebelum memasuki bulatan","Sejurus sebelum tiba di susur pertama","Selepas meninggalkan bulatan"]'::jsonb, 0, 'Use the left lane unless it is blocked. Stay in your lane and signal left after passing the first exit.', 'Gunakan lorong kiri kecuali jika terhalang. Kekal di lorong anda dan beri isyarat kiri selepas melepasi susur keluar pertama.', NULL, 'KPP Kelas D Automatik, PDF pages 258–259'),
  ('6d74794c-f502-5d4e-b7b1-2f7bb235e391'::uuid, 'traffic-rules', 'quiz-b-2', 7, 'You enter a roundabout to make a U-turn. How do you signal?', 'Anda memasuki bulatan untuk membuat pusingan U. Bagaimanakah anda perlu memberi isyarat?', '["Left on entry, right to exit","Right on entry, left to exit","Right on entry, right to exit","Left on entry, left to exit"]'::jsonb, '["Kiri ketika masuk, kanan untuk keluar","Kanan ketika masuk, kiri untuk keluar","Kanan ketika masuk, kanan untuk keluar","Kiri ketika masuk, kiri untuk keluar"]'::jsonb, 1, 'Enter in the right lane with the right signal. Change to the left signal after passing the exit before yours.', 'Masuk di lorong kanan dengan isyarat kanan. Tukar kepada isyarat kiri selepas melepasi susur keluar sebelum susur anda.', NULL, 'KPP Kelas D Automatik, PDF page 259'),
  ('b42f2d44-12be-5c7f-9d6f-bc67680c7960'::uuid, 'traffic-rules', 'quiz-b-2', 8, 'Which lane should you approach in to go straight through a three-lane roundabout?', 'Lorong manakah yang patut digunakan ketika menghampiri bulatan tiga lorong untuk meneruskan perjalanan lurus?', '["The left lane","The right lane","The middle lane","Any open lane"]'::jsonb, '["Lorong kiri","Lorong kanan","Lorong tengah","Mana-mana lorong kosong"]'::jsonb, 2, 'In a three-lane roundabout, the middle lane is for straight ahead. The left lane is for a left turn, and the right lane is for a right turn or U-turn.', 'Di bulatan tiga lorong, lorong tengah untuk terus. Lorong kiri untuk membelok ke kiri, dan lorong kanan untuk membelok ke kanan atau membuat pusingan U.', NULL, 'KPP Kelas D Automatik, PDF page 257'),
  ('757ed720-ec57-51c1-86cf-a86528350167'::uuid, 'traffic-rules', 'quiz-b-2', 9, 'You are ready to enter a roundabout. Which traffic has priority over you?', 'Anda bersedia untuk memasuki bulatan. Trafik manakah mempunyai keutamaan berbanding anda?', '["Vehicles approaching from your left","Vehicles approaching from your right","Vehicles waiting opposite you","Vehicles waiting beside you"]'::jsonb, '["Kenderaan yang menghampiri dari kiri","Kenderaan yang menghampiri dari kanan","Kenderaan yang menunggu di hadapan bertentangan","Kenderaan yang menunggu di sebelah anda"]'::jsonb, 1, 'Slow down and let traffic approaching from the right pass before you enter.', 'Perlahankan kenderaan dan beri laluan kepada trafik dari sebelah kanan sebelum masuk.', NULL, 'KPP Kelas D Automatik, PDF page 257'),
  ('5569182b-2965-5279-83a8-eecb167573f4'::uuid, 'traffic-rules', 'quiz-b-2', 10, 'The light turns amber before you reach the stop line. What should you do?', 'Lampu bertukar jingga sebelum anda tiba di garisan berhenti. Apakah tindakan anda?', '["Stop behind the line","Proceed if the lane is clear","Slow down and pass the line","Wait beyond the line"]'::jsonb, '["Berhenti di belakang garisan","Teruskan jika lorong lapang","Perlahankan dan lepasi garisan","Tunggu selepas garisan"]'::jsonb, 0, 'Amber means stop unless you have already passed the line.', 'Lampu jingga bermaksud berhenti kecuali jika anda sudah melepasi garisan.', NULL, 'KPP General, PDF page 34'),
  ('4b887bbc-5f1a-5fc7-a46d-95c8932b65be'::uuid, 'traffic-rules', 'quiz-b-2', 11, 'Traffic lights fail at a four-way junction. Who automatically has priority?', 'Lampu isyarat di simpang empat gagal berfungsi. Siapakah yang mendapat keutamaan secara automatik?', '["No approach","Traffic from the right","Traffic going straight","Traffic on the wider road"]'::jsonb, '["Tiada mana-mana arah","Trafik dari kanan","Trafik yang bergerak lurus","Trafik di jalan lebih lebar"]'::jsonb, 0, 'No approach has automatic priority at a four-way junction with failed signals. Proceed cautiously and cooperate with other drivers.', 'Tiada mana-mana arah mendapat keutamaan secara automatik. Berhati-hati dan bertimbang rasa dengan pemandu lain.', NULL, 'KPP General, PDF page 34'),
  ('69a0ee40-65e8-5cca-a85a-998c473bc428'::uuid, 'traffic-rules', 'quiz-b-2', 12, 'A traffic officer faces your lane with an upright palm. What does the signal mean?', 'Pegawai trafik menghadap lorong anda dengan tapak tangan tegak. Apakah maksud isyarat itu?', '["Stop and wait","Slow and proceed","Move to the right","Move to the left"]'::jsonb, '["Berhenti dan tunggu","Perlahankan dan teruskan","Bergerak ke kanan","Bergerak ke kiri"]'::jsonb, 0, 'The raised-hand signal tells drivers to stop.', 'Isyarat tangan yang diangkat mengarahkan pemandu supaya berhenti.', NULL, 'KPP Automatic Driving Curriculum, PDF page 74'),
  ('34f0e205-e44a-5174-b1e1-4ad34b29f6e9'::uuid, 'traffic-rules', 'quiz-b-2', 13, 'The lights fail at a T-junction. Which traffic goes first?', 'Lampu isyarat di simpang tiga gagal berfungsi. Trafik manakah bergerak dahulu?', '["Traffic on the main road","Traffic entering from the side road","Traffic turning across the main road","Traffic arriving at the signals first"]'::jsonb, '["Trafik di jalan utama","Trafik yang keluar dari jalan sisi","Trafik yang membelok merentasi jalan utama","Trafik yang tiba dahulu di lampu isyarat"]'::jsonb, 0, 'Give priority to vehicles on the main road when the lights fail at a T-junction.', 'Apabila lampu isyarat gagal berfungsi di simpang tiga, beri keutamaan kepada kenderaan di jalan utama.', NULL, 'KPP General, PDF page 34'),
  ('956cfc41-6ea4-56cd-ad6b-9030913a9928'::uuid, 'traffic-rules', 'quiz-b-2', 14, 'Before a right turn at a junction, when should you reduce speed?', 'Sebelum membelok ke kanan di persimpangan, bilakah anda patut mengurangkan kelajuan?', '["On the approach","Halfway through the turn","After straightening the wheel","Once you leave the junction"]'::jsonb, '["Semasa menghampiri persimpangan","Di pertengahan belokan","Selepas meluruskan stereng","Sebaik keluar dari persimpangan"]'::jsonb, 0, 'Reduce speed before turning so you can control the vehicle through the junction.', 'Kurangkan kelajuan sebelum membelok supaya kenderaan dapat dikawal semasa melalui persimpangan.', NULL, 'KPP Automatic Driving Curriculum, PDF page 112'),
  ('cea9df00-6ec6-5a76-9f67-929633fd5290'::uuid, 'traffic-rules', 'quiz-b-2', 15, 'An ambulance sounds its siren behind you while you have right of way. What should you do?', 'Ambulans membunyikan siren di belakang ketika anda mempunyai hak laluan. Apakah tindakan anda?', '["Give it room to pass","Keep your right of way","Speed up to clear the lane","Wait for the siren to stop"]'::jsonb, '["Beri ruang untuk ia lalu","Kekalkan hak laluan anda","Pecut untuk mengosongkan lorong","Tunggu sehingga siren berhenti"]'::jsonb, 0, 'Give priority to emergency vehicles sounding a siren even when you have the right of way.', 'Beri keutamaan kepada kenderaan kecemasan yang membunyikan siren walaupun anda mempunyai hak laluan.', NULL, 'KPP Automatic Driving Curriculum, PDF page 89'),
  ('5ecad7e2-9fb8-5927-9da7-bd0e39c6452a'::uuid, 'traffic-rules', 'quiz-b-2', 16, 'How should you begin a turn using the pull-and-push steering technique?', 'Bagaimanakah anda memulakan belokan menggunakan teknik stereng tarik dan tolak?', '["Draw the steering wheel down","Press the steering wheel upward","Hold the wheel with one hand","Cross your hands over first"]'::jsonb, '["Tarik stereng ke bawah","Tolak stereng ke atas","Pegang stereng dengan sebelah tangan","Silangkan tangan terlebih dahulu"]'::jsonb, 0, 'Start by drawing the rim down with one hand while the other slides along it.', 'Mulakan dengan menarik rim stereng ke bawah dengan sebelah tangan sementara tangan lain melurut pada rim.', NULL, 'KPP Automatic Driving Curriculum, PDF page 216'),
  ('462b4c26-bc26-55a5-9185-3f9d37fda78b'::uuid, 'traffic-rules', 'quiz-b-2', 17, 'Your car follows a wider arc than you intended through a bend. Which term describes it?', 'Kereta mengambil laluan lebih lebar daripada yang dimaksudkan ketika membelok. Apakah istilahnya?', '["Understeer","Oversteer","Late steering","Early steering"]'::jsonb, '["Kurang putaran stereng","Putaran stereng berlebihan","Putaran stereng lewat","Putaran stereng awal"]'::jsonb, 0, 'In the handbook example, too little steering opens the turn and can carry the car toward the edge of the road.', 'Dalam contoh buku, putaran stereng yang kurang melebarkan belokan dan boleh membawa kereta ke tepi jalan.', NULL, 'KPP Automatic Driving Curriculum, PDF page 260'),
  ('ac1f097c-c1d5-5c6c-bee7-a45d13b4d3df'::uuid, 'traffic-rules', 'quiz-b-2', 18, 'What can happen if you turn the wheel too far in a bend?', 'Apakah yang boleh berlaku jika anda memusing stereng terlalu jauh ketika membelok?', '["The car may cut into the next lane","The car may run wide at the outside","The car may keep the same arc","The car may straighten before the exit"]'::jsonb, '["Kereta mungkin masuk ke lorong sebelah","Kereta mungkin terbabas ke bahagian luar","Kereta mungkin kekal pada lengkok sama","Kereta mungkin bergerak lurus sebelum keluar"]'::jsonb, 0, 'Too much steering tightens the arc, potentially taking the vehicle into another lane.', 'Putaran berlebihan mengecilkan lengkok dan boleh membawa kenderaan ke lorong lain.', NULL, 'KPP Automatic Driving Curriculum, PDF page 260'),
  ('7724ad74-32bd-5cd8-a1a5-ffd49af7ebcf'::uuid, 'traffic-rules', 'quiz-b-2', 19, 'You approach a bend on a wet road. How should you adjust your speed?', 'Anda menghampiri selekoh di jalan basah. Bagaimanakah anda patut melaraskan kelajuan?', '["Reduce speed before the bend","Keep the same speed through the bend","Increase speed into the bend","Wait until the exit to slow down"]'::jsonb, '["Kurangkan kelajuan sebelum selekoh","Kekalkan kelajuan sepanjang selekoh","Tambah kelajuan ketika memasuki selekoh","Tunggu sehingga keluar untuk memperlahankan kenderaan"]'::jsonb, 0, 'Wet roads reduce tyre grip. Lower speed helps you maintain control in a bend.', 'Jalan basah mengurangkan cengkaman tayar. Kelajuan lebih rendah membantu mengekalkan kawalan di selekoh.', NULL, 'KPP Automatic Driving Curriculum, PDF page 146'),
  ('a411dc48-a160-5122-9337-acd79a74c97e'::uuid, 'traffic-rules', 'quiz-b-2', 20, 'When entering moving traffic from a slip road, what should your move accomplish?', 'Apabila masuk ke dalam aliran trafik dari jalan susur, apakah tujuan olah gerak anda?', '["Join the flow smoothly","Make traffic behind you slow","Stay beside a car in the next lane","Enter at the same point as the car ahead"]'::jsonb, '["Masuk ke dalam aliran dengan lancar","Paksa trafik di belakang memperlahankan kenderaan","Kekal di sebelah kereta di lorong bersebelahan","Masuk pada tempat yang sama dengan kereta di hadapan"]'::jsonb, 0, 'Merge into a safe gap at a speed and position that suit the traffic.', 'Masuk ke ruang selamat pada kelajuan dan posisi yang sesuai dengan trafik.', NULL, 'KPP Automatic Driving Curriculum, PDF page 117'),
  ('8c81e40d-0e07-529e-9ffb-5bbf63a07012'::uuid, 'traffic-rules', 'quiz-b-2', 21, 'The handbook estimates seven seconds to recover from glare. At 70 km/h, about how far do you travel in that time?', 'Buku menganggarkan tujuh saat untuk pulih daripada silau. Pada 70 km/j, kira-kira sejauh manakah anda bergerak dalam tempoh itu?', '["140 m","70 m","100 m","200 m"]'::jsonb, '["140 m","70 m","100 m","200 m"]'::jsonb, 0, 'At 70 km/h the car travels about 19 metres per second. In seven seconds that is about 140 metres.', 'Pada 70 km/j, kereta bergerak kira-kira 19 meter sesaat. Dalam tujuh saat jaraknya sekitar 140 meter.', NULL, 'KPP Automatic Driving Curriculum, PDF page 122'),
  ('448286e4-75f2-59a3-a1f1-b1685076b257'::uuid, 'traffic-rules', 'quiz-b-2', 22, 'What can you do if an oncoming driver leaves their high beams on?', 'Apakah yang boleh anda lakukan jika pemandu dari arah bertentangan terus menggunakan lampu tinggi?', '["Flash your lights briefly","Hold your high beams on","Turn your headlights off","Switch on your fog lights"]'::jsonb, '["Kelipkan lampu seketika","Biarkan lampu tinggi menyala","Padamkan lampu hadapan","Nyalakan lampu kabus"]'::jsonb, 0, 'A brief flash can remind the other driver to dip their beams.', 'Kelipan seketika boleh mengingatkan pemandu itu supaya merendahkan lampu.', NULL, 'KPP Automatic Driving Curriculum, PDF page 142'),
  ('25533ad6-3ef0-53ec-9a32-85c43d02f581'::uuid, 'traffic-rules', 'quiz-b-2', 23, 'You catch up with another car at night. Which headlights should you use?', 'Anda menghampiri kereta lain pada waktu malam. Lampu manakah patut digunakan?', '["Low beam","High beam","Parking lamps only","Front fog lamps only"]'::jsonb, '["Lampu rendah","Lampu tinggi","Lampu parkir sahaja","Lampu kabus hadapan sahaja"]'::jsonb, 0, 'Use low beam when following a vehicle. High beam can dazzle its driver through the mirrors.', 'Gunakan lampu rendah ketika mengekori kenderaan. Lampu tinggi boleh menyilaukan pemandu melalui cermin.', NULL, 'KPP Automatic Driving Curriculum, PDF page 142'),
  ('aaf18373-b379-56b0-b8b3-ae0f6ac0b496'::uuid, 'traffic-rules', 'quiz-b-2', 24, 'During a headlight check before a night trip, what should you verify besides whether the lights turn on?', 'Semasa memeriksa lampu hadapan sebelum perjalanan malam, apakah yang perlu diperiksa selain sama ada lampu menyala?', '["The beams are aimed correctly","The beams point as high as possible","The beams reach the same height as the mirrors","The beams illuminate the bonnet evenly"]'::jsonb, '["Pancaran dilaras dengan betul","Pancaran dihalakan setinggi mungkin","Pancaran mencapai paras cermin sisi","Pancaran menyinari bonet secara sekata"]'::jsonb, 0, 'Check that the lights work and are adjusted before setting off at night.', 'Pastikan lampu berfungsi dan dilaraskan sebelum memulakan perjalanan pada waktu malam.', NULL, 'KPP Automatic Driving Curriculum, PDF page 142'),
  ('5115fbc5-c43e-58d3-882d-0a3a0c31331b'::uuid, 'traffic-rules', 'quiz-b-2', 25, 'After hitting standing water, a driver briefly loses steering response. What can cause this?', 'Selepas meredah air bertakung, stereng tidak memberi tindak balas seketika. Apakah puncanya?', '["A layer of water lifts the tyres off the road","Water covers the outside of the tyres","Wet tread grips more strongly on one side","Water cools the tyre and improves its grip"]'::jsonb, '["Lapisan air mengangkat tayar dari jalan","Air meliputi permukaan luar tayar","Bunga basah lebih mencengkam di satu sisi","Air menyejukkan tayar dan menambah cengkaman"]'::jsonb, 0, 'Water collects under the tyres. As they lose grip, steering and braking become less effective.', 'Air terkumpul di bawah tayar. Apabila cengkaman hilang, stereng dan brek menjadi kurang berkesan.', NULL, 'KPP Automatic Driving Curriculum, PDF page 146'),
  ('ffe902fd-7396-59cb-8ec1-cff2252f89cd'::uuid, 'traffic-rules', 'quiz-b-3', 1, 'Your tyres begin to aquaplane. What should you do first?', 'Tayar mula menggelungsur di atas air. Apakah tindakan pertama anda?', '["Ease off the accelerator","Brake in short pulses","Steer toward the shoulder","Hold your current speed"]'::jsonb, '["Lepaskan pedal minyak perlahan-lahan","Tekan brek secara berselang","Pusing stereng ke bahu jalan","Kekalkan kelajuan semasa"]'::jsonb, 0, 'Slow gradually by easing off the accelerator. Avoid braking or changing direction until grip returns.', 'Perlahankan kenderaan dengan melepaskan pedal minyak secara beransur-ansur. Elakkan membrek atau menukar arah sehingga tayar kembali mencengkam.', NULL, 'KPP Automatic Driving Curriculum, PDF page 146'),
  ('f3528f4d-4d94-5a3a-8ce8-929ac7d9bee4'::uuid, 'traffic-rules', 'quiz-b-3', 2, 'Rain makes your car hard for other drivers to see. What should you do?', 'Hujan menyebabkan kereta anda sukar dilihat oleh pemandu lain. Apakah tindakan anda?', '["Switch on the headlights","Turn on the cabin light","Leave the lights off","Flash the headlights periodically"]'::jsonb, '["Nyalakan lampu hadapan","Nyalakan lampu kabin","Biarkan lampu terpadam","Kelipkan lampu hadapan sekali-sekala"]'::jsonb, 0, 'Use headlights in poor visibility so other road users can see your vehicle.', 'Gunakan lampu hadapan apabila penglihatan terhad supaya pengguna jalan raya lain dapat melihat kenderaan anda.', NULL, 'KPP Automatic Driving Curriculum, PDF page 146'),
  ('f8670e36-d455-5bf2-88d9-9167c2a8a1fe'::uuid, 'traffic-rules', 'quiz-b-3', 3, 'You have confirmed that the floodwater is shallow enough to cross. How should you drive through?', 'Anda telah memastikan air banjir cukup cetek untuk dilalui. Bagaimanakah anda patut memandu merentasinya?', '["Slowly in a low gear","Slowly in a high gear","Quickly in a low gear","Coasting in neutral"]'::jsonb, '["Perlahan dalam gear rendah","Perlahan dalam gear tinggi","Laju dalam gear rendah","Meluncur dalam gear neutral"]'::jsonb, 0, 'Only cross after assessing the depth. Use a low gear and keep speed low.', 'Lalui hanya selepas menilai kedalaman air. Gunakan gear rendah dan kekalkan kelajuan rendah.', NULL, 'KPP Automatic Driving Curriculum, PDF page 148'),
  ('882c9651-145a-5942-b5a0-69b4a621af1f'::uuid, 'traffic-rules', 'quiz-b-3', 4, 'Floodwater ahead is too deep to cross safely. What should you do?', 'Air banjir di hadapan terlalu dalam untuk dilalui dengan selamat. Apakah tindakan anda?', '["Turn back and find another route","Follow a larger vehicle across","Cross near the edge of the road","Wait for a gap and cross slowly"]'::jsonb, '["Patah balik dan cari laluan lain","Ikut kenderaan lebih besar merentasi air","Lintas berhampiran tepi jalan","Tunggu ruang dan lintas perlahan-lahan"]'::jsonb, 0, 'Choose another route. Deep water can stall the engine or damage it if water reaches the air intake.', 'Pilih laluan lain. Air dalam boleh mematikan enjin atau merosakkannya jika air masuk melalui salur udara.', NULL, 'KPP Automatic Driving Curriculum, PDF page 148'),
  ('48cbab18-a7b7-54bb-84f9-6db10e84c52f'::uuid, 'traffic-rules', 'quiz-b-3', 5, 'What should you switch on when entering a tunnel?', 'Apakah yang patut dihidupkan apabila memasuki terowong?', '["Headlights","Hazard lights","Interior lights","Rear fog lights"]'::jsonb, '["Lampu hadapan","Lampu kecemasan","Lampu kabin","Lampu kabus belakang"]'::jsonb, 0, 'Use your headlights in the tunnel and leave a safe gap because visibility is limited.', 'Gunakan lampu hadapan di dalam terowong dan kekalkan jarak selamat kerana penglihatan terhad.', NULL, 'KPP Automatic Driving Curriculum, PDF page 139'),
  ('e2214e9a-6d7f-5c7c-a9f4-864d3fbc943b'::uuid, 'traffic-rules', 'quiz-b-3', 6, 'Where should you avoid stopping to pick someone up?', 'Di manakah anda patut mengelak daripada berhenti untuk mengambil penumpang?', '["Beside a fire hydrant","In a designated pickup bay","In a legal parking space","At a passenger drop-off point"]'::jsonb, '["Di sebelah pili bomba","Di petak mengambil penumpang","Di petak parkir yang dibenarkan","Di tempat menurunkan penumpang"]'::jsonb, 0, 'The book lists fire hydrants among places where drivers should avoid stopping.', 'Pili bomba ialah antara tempat yang perlu dielakkan ketika berhenti.', NULL, 'KPP Automatic Driving Curriculum, PDF page 263'),
  ('e7904cb7-0e75-50c8-bcc5-74bd3c90b9ae'::uuid, 'traffic-rules', 'quiz-b-3', 7, 'Which location should you avoid when picking up a passenger?', 'Lokasi manakah patut dielakkan ketika mengambil penumpang?', '["A stop marked for buses","A bay marked for pickups","An open public car park","A lay-by open to cars"]'::jsonb, '["Perhentian bertanda untuk bas","Petak bertanda untuk mengambil penumpang","Tempat letak kereta awam yang dibuka","Ruang berhenti yang terbuka kepada kereta"]'::jsonb, 0, 'The stopping lesson lists bends, junctions, fire hydrants and bus stops as places to avoid.', 'Pelajaran berhenti menyenaraikan selekoh, persimpangan, pili bomba dan perhentian bas sebagai tempat yang perlu dielakkan.', NULL, 'KPP Kelas DA Automatik, PDF 263'),
  ('5c5a348d-f75c-5541-9262-2297997760f2'::uuid, 'traffic-rules', 'quiz-b-3', 8, 'When should you apply the parking brake during the normal stopping routine?', 'Bilakah brek tangan perlu ditarik semasa rutin berhenti biasa?', '["As you release the accelerator","Once the car has stopped","As the car starts to slow","Just before pressing the foot brake"]'::jsonb, '["Semasa melepaskan pemecut","Selepas kereta berhenti","Ketika kereta mula perlahan","Sebelum menekan pedal brek"]'::jsonb, 1, 'The lesson first uses the foot brake to stop the vehicle. It then calls for applying the parking brake once stationary.', 'Pelajaran menggunakan pedal brek dahulu untuk menghentikan kereta. Tarik brek tangan selepas kereta berhenti.', NULL, 'KPP Kelas DA Automatik, PDF 263'),
  ('284da69c-24e2-5b57-8ae6-199963fe0e2c'::uuid, 'traffic-rules', 'quiz-b-3', 9, 'You have applied the parking brake and are about to leave the parked car. What else should you do before getting out?', 'Brek tangan sudah ditarik dan anda hendak meninggalkan kereta. Apakah yang perlu dibuat sebelum keluar?', '["Leave the engine idling","Leave the blower running","Switch off the engine","Raise the idle speed"]'::jsonb, '["Biarkan enjin melahu","Biarkan penghembus hidup","Matikan enjin","Tingkatkan putaran melahu"]'::jsonb, 2, 'The curriculum flags leaving a vehicle without switching off the engine or applying the parking brake.', 'Kurikulum menyenaraikan meninggalkan kenderaan tanpa mematikan enjin atau menggunakan brek tangan sebagai kesalahan.', NULL, 'KPP Kelas DA Automatik, PDF 166'),
  ('3660a861-009c-5913-bfb2-3cad2af1ea79'::uuid, 'traffic-rules', 'quiz-b-3', 10, 'What distinguishes the two dangerous-driving categories listed next to each other in the curriculum?', 'Apakah yang membezakan dua kategori pemanduan berbahaya yang disenaraikan berturutan dalam kurikulum?', '["Whether property was damaged","Whether a warning was given","Whether there was a passenger","Whether someone was killed"]'::jsonb, '["Sama ada harta benda rosak","Sama ada amaran diberikan","Sama ada terdapat penumpang","Sama ada terdapat kematian"]'::jsonb, 3, 'The table distinguishes dangerous driving causing death from dangerous driving with no death.', 'Jadual membezakan pemanduan berbahaya yang menyebabkan kematian daripada pemanduan berbahaya tanpa kematian.', NULL, 'KPP Kelas DA Automatik, PDF 162'),
  ('1ef3e6fd-d137-5def-a24e-ee300b8eb208'::uuid, 'traffic-rules', 'quiz-b-3', 11, 'A driver cuts through tight gaps at speed and forces others to brake. There is no crash. How does the curriculum classify that conduct?', 'Seorang pemandu menyelit melalui ruang sempit pada kelajuan tinggi sehingga pemandu lain terpaksa membrek. Tiada perlanggaran. Bagaimanakah kurikulum mengelaskan perbuatan itu?', '["Reckless or dangerous driving","Failure to yield at a junction","Failure to follow a speed sign","Obstruction by a stopped car"]'::jsonb, '["Pemanduan melulu atau berbahaya","Gagal memberi laluan di simpang","Gagal mematuhi tanda had laju","Halangan oleh kereta yang berhenti"]'::jsonb, 0, 'The table includes a category for reckless or dangerous driving even when no one is killed.', 'Jadual menyenaraikan pemanduan melulu atau berbahaya walaupun tidak menyebabkan kematian.', NULL, 'KPP Kelas DA Automatik, PDF 162'),
  ('2547e6ee-293f-5342-9adf-fbea6d0dcacb'::uuid, 'traffic-rules', 'quiz-b-3', 12, 'Which section does the curriculum associate with careless and inconsiderate driving?', 'Seksyen manakah dikaitkan dengan pemanduan cuai dan tidak bertimbang rasa dalam kurikulum?', '["Section 41","Section 43","Section 44","Section 46"]'::jsonb, '["Seksyen 41","Seksyen 43","Seksyen 44","Seksyen 46"]'::jsonb, 1, 'The curriculum’s offence table lists careless and inconsiderate driving under Section 43.', 'Jadual kesalahan dalam kurikulum menyenaraikan pemanduan cuai dan tidak bertimbang rasa di bawah Seksyen 43.', NULL, 'KPP Kelas DA Automatik, PDF 163'),
  ('99533a7d-26d8-5782-9948-b80152c96a3c'::uuid, 'traffic-rules', 'quiz-b-3', 13, 'Which fact does the textbook use to identify the offence under Section 45A?', 'Fakta manakah digunakan dalam buku untuk mengenal pasti kesalahan di bawah Seksyen 45A?', '["The driver has no valid licence","The vehicle has no insurance cover","Alcohol exceeds the prescribed limit","The car enters a restricted road"]'::jsonb, '["Pemandu tiada lesen yang sah","Kenderaan tiada perlindungan insurans","Alkohol melebihi had ditetapkan","Kereta memasuki jalan terhad"]'::jsonb, 2, 'The offence table lists driving or being in charge of a motor vehicle with alcohol above the prescribed limit.', 'Jadual menyenaraikan memandu atau menjaga kenderaan motor dengan kepekatan alkohol melebihi had yang ditetapkan.', NULL, 'KPP Kelas DA Automatik, PDF 163'),
  ('0473f3eb-da5d-55bc-bb69-beeb1d3cc5eb'::uuid, 'traffic-rules', 'quiz-b-3', 14, 'Which activity does the curriculum list under Section 81?', 'Aktiviti manakah disenaraikan di bawah Seksyen 81 dalam kurikulum?', '["Ignoring a marked no-entry sign","Passing another car on the left","Blocking a pedestrian crossing","Joining an unapproved road race"]'::jsonb, '["Mengabaikan tanda dilarang masuk","Memotong kereta lain di sebelah kiri","Menghalang lintasan pejalan kaki","Menyertai perlumbaan jalan tanpa kebenaran"]'::jsonb, 3, 'The offence table includes both organising and taking part in an unauthorised road race.', 'Jadual kesalahan merangkumi kedua-dua menaja dan menyertai perlumbaan jalan raya tanpa kebenaran.', NULL, 'KPP Kelas DA Automatik, PDF 164'),
  ('4d6817ad-98d9-5c82-83d3-0df830244be6'::uuid, 'traffic-rules', 'quiz-b-3', 15, 'Which conduct does the curriculum list under Section 79(2)?', 'Perbuatan manakah disenaraikan di bawah Seksyen 79(2) dalam kurikulum?', '["Ignoring a traffic sign","Parking at a bus stop","Driving an uninsured car","Failing to stop at a roadblock"]'::jsonb, '["Mengabaikan isyarat lalu lintas","Meletak kereta di perhentian bas","Memandu kereta tanpa insurans","Gagal berhenti di sekatan jalan"]'::jsonb, 0, 'The offence table identifies failing to obey traffic signs. It lists roadblocks and pedestrian crossing offences separately.', 'Jadual menyenaraikan kegagalan mematuhi isyarat lalu lintas. Kesalahan sekatan jalan dan lintasan pejalan kaki disenaraikan berasingan.', NULL, 'KPP Kelas DA Automatik, PDF 164'),
  ('e1955d6b-1c9c-573b-abe5-0109b3f0d0f9'::uuid, 'traffic-rules', 'quiz-b-3', 16, 'You want to return a missed call while driving. When should you use the phone?', 'Anda ingin membalas panggilan yang terlepas ketika memandu. Bilakah anda patut menggunakan telefon?', '["After parking safely","While stopped at a traffic light","While crawling in a queue","While another driver is passing"]'::jsonb, '["Selepas parkir dengan selamat","Semasa berhenti di lampu isyarat","Semasa bergerak perlahan dalam kesesakan","Semasa dipotong oleh pemandu lain"]'::jsonb, 0, 'Using a phone can draw your attention away from the road.', 'Penggunaan telefon boleh mengalihkan perhatian daripada jalan.', NULL, 'KPP Automatic Driving Curriculum, PDF page 78'),
  ('50f47572-5e5e-5183-93d6-bb813dba0c00'::uuid, 'traffic-rules', 'quiz-b-3', 17, 'Your car breaks down on an expressway. Where should you pull over if you can still steer?', 'Kereta anda rosak di lebuh raya. Di manakah anda patut berhenti jika masih boleh mengawal stereng?', '["In the emergency lane","In the left travel lane","In the right travel lane","In the central median"]'::jsonb, '["Di lorong kecemasan","Di lorong perjalanan kiri","Di lorong perjalanan kanan","Di pembahagi jalan"]'::jsonb, 0, 'Signal left, stop in the emergency lane and switch on your hazard lights.', 'Beri isyarat kiri, berhenti di lorong kecemasan dan nyalakan lampu kecemasan.', NULL, 'KPP Automatic Driving Curriculum, PDF page 128'),
  ('db45ce2c-d419-5c05-b528-119d980d9ed8'::uuid, 'traffic-rules', 'quiz-b-3', 18, 'Which side should you normally use on a two-way road in Malaysia?', 'Bahagian manakah yang biasanya digunakan di jalan dua hala di Malaysia?', '["The left side","The right side","The clearer side","The wider side"]'::jsonb, '["Bahagian kiri","Bahagian kanan","Bahagian lebih lapang","Bahagian lebih lebar"]'::jsonb, 0, 'The normal rule is to keep to the left side of the road.', 'Peraturan biasa ialah memandu di sebelah kiri jalan.', NULL, 'KPP Automatic Driving Curriculum, PDF page 165'),
  ('82949816-7a88-5d6a-bcc6-547c346c86e4'::uuid, 'traffic-rules', 'quiz-b-3', 19, 'On an open two-way road, which side should you move to when it is safe to pass a slower vehicle?', 'Di jalan dua hala, di sebelah manakah anda patut bergerak apabila selamat untuk memotong kenderaan yang lebih perlahan?', '["To its right","To its left","To the road shoulder","To the centre without passing"]'::jsonb, '["Ke sebelah kanannya","Ke sebelah kirinya","Ke bahu jalan","Ke tengah tanpa memotong"]'::jsonb, 0, 'The textbook’s overtaking routine calls for checking ahead, behind and beside you before moving to the right.', 'Rutin memotong dalam buku mengarahkan anda menyemak hadapan, belakang dan sisi sebelum bergerak ke kanan.', NULL, 'KPP Kelas DA Automatik, PDF 261'),
  ('542f729c-9ff6-5a5a-82de-ef4abb673cc4'::uuid, 'traffic-rules', 'quiz-b-3', 20, 'After stopping at a crash, when must the driver report it to the police under the rule in the curriculum?', 'Selepas berhenti di tempat kemalangan, bilakah pemandu perlu melaporkannya kepada polis mengikut peraturan dalam kurikulum?', '["Within 48 hours","Within 24 hours","Within 72 hours","Within 7 days"]'::jsonb, '["Dalam masa 48 jam","Dalam masa 24 jam","Dalam masa 72 jam","Dalam masa 7 hari"]'::jsonb, 1, 'The rule lists two duties after a crash: stop and report to the police within 24 hours.', 'Peraturan menyenaraikan dua kewajipan selepas kemalangan: berhenti dan lapor kepada polis dalam masa 24 jam.', NULL, 'KPP Kelas DA Automatik, PDF 164'),
  ('6c4a027f-5d26-590f-9ce1-6592e87e3575'::uuid, 'traffic-rules', 'quiz-b-3', 21, 'A uniformed officer directs you to the roadside. What is the correct response?', 'Seorang pegawai beruniform mengarahkan anda ke tepi jalan. Apakah tindakan yang betul?', '["Slow down and wait for a second signal","Continue to the next staffed checkpoint","Stop where it is safe as directed","Keep going unless other drivers stop"]'::jsonb, '["Perlahankan kenderaan dan tunggu isyarat kedua","Teruskan ke pusat pemeriksaan seterusnya","Berhenti dengan selamat seperti diarahkan","Teruskan kecuali pemandu lain berhenti"]'::jsonb, 2, 'The offence table lists failure to stop when directed by a uniformed officer. Follow the direction and stop safely.', 'Jadual menyenaraikan kesalahan gagal berhenti apabila diarahkan oleh pegawai beruniform. Patuhi arahan dan berhenti dengan selamat.', NULL, 'KPP Kelas DA Automatik, PDF 164'),
  ('fb00d016-563e-5077-ba7d-17c438ca0dd7'::uuid, 'traffic-rules', 'quiz-b-3', 22, 'Your driving licence expired yesterday. What should you do before driving again?', 'Lesen memandu anda tamat tempoh semalam. Apakah yang perlu dibuat sebelum memandu semula?', '["Keep the old licence with you","Carry the vehicle registration","Book a renewal for later","Renew the driving licence"]'::jsonb, '["Bawa lesen lama bersama","Bawa pendaftaran kenderaan","Tempah pembaharuan untuk kemudian","Perbaharui lesen memandu"]'::jsonb, 3, 'The licensing table lists driving on an expired licence as an offence. Renew it before driving.', 'Jadual pelesenan menyenaraikan memandu dengan lesen tamat tempoh sebagai kesalahan. Perbaharui lesen sebelum memandu.', NULL, 'KPP Kelas DA Automatik, PDF 161'),
  ('934d13f0-c2ac-5861-b550-cf569bd37053'::uuid, 'traffic-rules', 'quiz-b-3', 23, 'A car is about to be used on a public road. What must its minimum policy provide?', 'Kereta akan digunakan di jalan awam. Apakah perlindungan minimum yang mesti diberikan oleh polisinya?', '["Cover for third-party injury","Cover for wear and tear","Cover for theft of luggage","Cover for engine breakdown"]'::jsonb, '["Perlindungan kecederaan pihak ketiga","Perlindungan kehausan biasa","Perlindungan kecurian bagasi","Perlindungan kerosakan enjin"]'::jsonb, 0, 'The curriculum lists using a vehicle without cover under the provisions for third-party risks.', 'Kurikulum menyenaraikan penggunaan kenderaan tanpa perlindungan di bawah peruntukan risiko pihak ketiga.', NULL, 'KPP Kelas DA Automatik, PDF 168'),
  ('1c139cfe-05b2-58ed-adee-11cc72f449a8'::uuid, 'traffic-rules', 'quiz-b-3', 24, 'A route restriction lists bicycles and micromobility vehicles. Which road user is also covered by that restriction?', 'Sekatan laluan menyenaraikan basikal dan kenderaan mikromobiliti. Pengguna jalan raya manakah turut tertakluk pada sekatan itu?', '["An e-scooter rider","A passenger in a car","A driver in a light van","A bus passenger"]'::jsonb, '["Penunggang skuter elektrik","Penumpang kereta","Pemandu van ringan","Penumpang bas"]'::jsonb, 0, 'An e-scooter is a micromobility vehicle. Its rider must use an allowed route.', 'Skuter elektrik ialah kenderaan mikromobiliti. Penunggang mesti menggunakan laluan yang dibenarkan.', NULL, 'KPP General, PDF page 58'),
  ('00f68580-d2f0-519b-a651-5fb148b7a799'::uuid, 'traffic-rules', 'quiz-b-3', 25, 'At 20 km/h, the braking distance is 3 m and the total stopping distance is 9 m. How far does the car travel before braking?', 'Pada 20 km/j, jarak membrek ialah 3 m dan jumlah jarak berhenti ialah 9 m. Berapakah jarak yang dilalui sebelum membrek?', '["6 m","3 m","9 m","12 m"]'::jsonb, '["6 m","3 m","9 m","12 m"]'::jsonb, 0, 'Subtract braking distance from total stopping distance: 9 m minus 3 m is 6 m.', 'Tolak jarak membrek daripada jumlah jarak berhenti: 9 m tolak 3 m ialah 6 m.', NULL, 'KPP Automatic Driving Curriculum, PDF page 264'),
  ('30ae9870-dfdb-53aa-9d91-bdd14a9a2517'::uuid, 'safety-principles', 'quiz-c-da-1', 1, 'What is the minimum age to apply for a motorcycle licence?', 'Berapakah umur minimum untuk memohon lesen motosikal?', '["15 years","17 years","16 years","18 years"]'::jsonb, '["15 tahun","17 tahun","16 tahun","18 tahun"]'::jsonb, 2, 'The curriculum lists 16 as the minimum age for a motorcycle licence.', 'Kurikulum menetapkan umur minimum 16 tahun bagi permohonan lesen motosikal.', NULL, 'KPP General, PDF 9'),
  ('14ad2e95-f559-5964-995d-8acc655d0c86'::uuid, 'safety-principles', 'quiz-c-da-1', 2, 'What is the minimum age for the motorcar licence classes?', 'Berapakah umur minimum bagi kelas lesen motokar?', '["16 years","18 years","17 years","21 years"]'::jsonb, '["16 tahun","18 tahun","17 tahun","21 tahun"]'::jsonb, 2, 'Applicants for a motorcar licence must be at least 17 years old.', 'Pemohon lesen motokar mestilah berumur sekurang-kurangnya 17 tahun.', NULL, 'KPP Kelas DA Automatik, PDF 11'),
  ('14223139-d594-5ac2-8a70-25f73f764700'::uuid, 'safety-principles', 'quiz-c-da-1', 3, 'What kind of vehicle does the Class E classification cover in this textbook?', 'Apakah jenis kenderaan bagi Kelas E dalam buku ini?', '["A car without a clutch pedal","An adapted motorcycle","A light tracked tractor","A heavy motor vehicle"]'::jsonb, '["Motokar tanpa pedal cekam","Motosikal yang diubah suai","Traktor ringan berantai","Motokar berat"]'::jsonb, 3, 'Class E is listed for heavy motor vehicles over 7,500 kg unladen.', 'Kelas E disenaraikan untuk motokar berat dengan berat tanpa muatan melebihi 7,500 kg.', NULL, 'KPP Kelas DA Automatik, PDF 10'),
  ('2182f30b-272f-57e4-a54b-156e508a3388'::uuid, 'safety-principles', 'quiz-c-da-1', 4, 'Which vocational endorsement applies to a rider delivering parcels for work?', 'Lesen vokasional manakah digunakan oleh penunggang yang menghantar bungkusan untuk kerja?', '["GDL","PSV","Conductor licence","No vocational endorsement"]'::jsonb, '["GDL","PSV","Lesen konduktor","Tiada lesen vokasional"]'::jsonb, 0, 'The vocational categories list goods vehicle licensing, including motorcycles, under GDL.', 'Kategori lesen vokasional menyenaraikan motosikal barangan di bawah lesen GDL.', NULL, 'KPP Kelas DA Automatik, PDF 23'),
  ('403a8a24-ae8b-5275-9863-b1558d155746'::uuid, 'safety-principles', 'quiz-c-da-1', 5, 'Which vehicle does a Class A1 licence cover?', 'Kenderaan manakah yang termasuk dalam lesen Kelas A1?', '["An adapted motorcycle","A light goods vehicle","An adapted motorcar","A three-wheel motorcycle"]'::jsonb, '["Motosikal yang diubah suai","Kenderaan barangan ringan","Motokar yang diubah suai","Motosikal tiga roda"]'::jsonb, 2, 'Class A1 covers adapted motorcars for drivers with disabilities. Class A covers adapted motorcycles.', 'Kelas A1 meliputi motokar yang diubah suai untuk pemandu orang kurang upaya. Kelas A meliputi motosikal yang diubah suai.', NULL, 'KPP Kelas DA Automatik, PDF 17'),
  ('988e8088-940b-5fbc-8399-b73e10181cd4'::uuid, 'safety-principles', 'quiz-c-da-1', 6, 'What is the engine capacity limit for a Class B2 motorcycle?', 'Berapakah had kapasiti enjin bagi motosikal Kelas B2?', '["150 cc","300 cc","500 cc","250 cc"]'::jsonb, '["150 cc","300 cc","500 cc","250 cc"]'::jsonb, 3, 'Class B2 covers personal motorcycles up to 250 cc.', 'Kelas B2 meliputi motosikal persendirian sehingga 250 cc.', NULL, 'KPP Kelas DA Automatik, PDF 10'),
  ('9f938747-0f20-5d41-bf10-51783a315f19'::uuid, 'safety-principles', 'quiz-c-da-1', 7, 'What is the maximum unladen weight for a Class D or DA motorcar?', 'Berapakah berat tanpa muatan maksimum bagi motokar Kelas D atau DA?', '["2500 kg","5000 kg","7500 kg","3500 kg"]'::jsonb, '["2500 kg","5000 kg","7500 kg","3500 kg"]'::jsonb, 3, 'The Class D and DA classifications both have an unladen weight limit of 3,500 kg.', 'Kelas D dan DA mempunyai had berat tanpa muatan sebanyak 3,500 kg.', NULL, 'KPP Kelas DA Automatik, PDF 10'),
  ('465b5662-6db9-52d5-9b13-f10f2001e782'::uuid, 'safety-principles', 'quiz-c-da-1', 8, 'Which group of vehicles is covered by Classes F, G, H and I?', 'Kumpulan kenderaan manakah yang diliputi oleh Kelas F, G, H dan I?', '["Lorries and articulated trailers","Tractors and mobile machinery","Buses and passenger vans","Motorcars and small vans"]'::jsonb, '["Lori dan treler bersendi","Traktor dan jentera bergerak","Bas dan van penumpang","Motokar dan van kecil"]'::jsonb, 1, 'These classes cover tractors and mobile machinery. They distinguish wheels from tracks and lighter from heavier vehicles.', 'Kelas ini meliputi traktor dan jentera bergerak. Kelasnya dibezakan mengikut roda atau rantai serta berat kenderaan.', NULL, 'KPP Kelas DA Automatik, PDF 10'),
  ('68cebec4-0d28-5ecd-93fe-aa9f49f3b84b'::uuid, 'safety-principles', 'quiz-c-da-1', 9, 'How long is the KPP01 course for this class before the Part I test?', 'Berapa lamakah kursus KPP01 bagi kelas ini sebelum Ujian Bahagian I?', '["4 hours","6 hours","5 hours","8 hours"]'::jsonb, '["4 jam","6 jam","5 jam","8 jam"]'::jsonb, 1, 'Candidates attend six hours of KPP01 before taking the Part I test.', 'Calon mengikuti KPP01 selama enam jam sebelum menduduki Ujian Bahagian I.', NULL, 'KPP Kelas DA Automatik, PDF 15'),
  ('6b31aba9-cc8a-52c3-88fc-f34d0f7652fb'::uuid, 'safety-principles', 'quiz-c-da-1', 10, 'What score passes the 50-question Part I test described in this curriculum?', 'Berapakah markah lulus bagi Ujian Bahagian I dengan 50 soalan yang diterangkan dalam kurikulum ini?', '["40 out of 50","43 out of 50","42 out of 50","45 out of 50"]'::jsonb, '["40 daripada 50","43 daripada 50","42 daripada 50","45 daripada 50"]'::jsonb, 2, 'This curriculum describes a 50-question test with a pass mark of 42 and a time limit of 45 minutes.', 'Kurikulum ini menerangkan ujian 50 soalan dengan markah lulus 42 dan tempoh 45 minit.', NULL, 'KPP Kelas DA Automatik, PDF 15'),
  ('fc4c76f3-c49b-51ed-9689-bd4b197eb929'::uuid, 'safety-principles', 'quiz-c-da-1', 11, 'For how long is a Part I pass valid?', 'Berapa lamakah keputusan lulus Ujian Bahagian I sah?', '["6 months","18 months","24 months","12 months"]'::jsonb, '["6 bulan","18 bulan","24 bulan","12 bulan"]'::jsonb, 3, 'The validity period starts on the day the candidate passes and lasts one year.', 'Tempoh sah bermula pada tarikh calon lulus dan berakhir selepas setahun.', NULL, 'KPP Kelas DA Automatik, PDF 16'),
  ('a403644c-d4cb-5f19-bc67-02e9b8f68ea1'::uuid, 'safety-principles', 'quiz-c-da-1', 12, 'Which selector position should you use before leaving an automatic car?', 'Kedudukan gear manakah yang patut dipilih sebelum meninggalkan kereta automatik?', '["P","N","R","D"]'::jsonb, '["P","N","R","D"]'::jsonb, 0, 'Park keeps the car from moving and is used when leaving it.', 'Kedudukan P menghalang kereta daripada bergerak dan digunakan apabila meninggalkannya.', NULL, 'KPP Kelas DA Automatik, PDF 210'),
  ('ab0ccd2e-cc7b-59dc-8b89-6271c0479f66'::uuid, 'safety-principles', 'quiz-c-da-1', 13, 'What should you do with the brake pedal before selecting Park?', 'Apakah yang perlu dibuat dengan pedal brek sebelum memilih kedudukan P?', '["Press it lightly","Press it fully","Pump it twice","Release it first"]'::jsonb, '["Tekan sedikit","Tekan sepenuhnya","Pam dua kali","Lepaskan dahulu"]'::jsonb, 1, 'Stop the car, press the brake pedal fully, and press the selector lock button when selecting P.', 'Hentikan kereta, tekan pedal brek sepenuhnya dan tekan butang pengunci ketika memilih kedudukan P.', NULL, 'KPP Kelas DA Automatik, PDF 215'),
  ('889be359-c027-5356-bc37-8879860ec96a'::uuid, 'safety-principles', 'quiz-c-da-1', 14, 'Which selector position moves an automatic car backwards?', 'Kedudukan gear manakah yang menggerakkan kereta automatik ke belakang?', '["N","L","R","D"]'::jsonb, '["N","L","R","D"]'::jsonb, 2, 'Select R to move the car backwards.', 'Pilih R untuk menggerakkan kereta ke belakang.', NULL, 'KPP Kelas DA Automatik, PDF 210'),
  ('bb3f096b-74b6-5a77-850d-532cee4bdb3c'::uuid, 'safety-principles', 'quiz-c-da-1', 15, 'What is the transmission doing when the selector is in N?', 'Apakah keadaan transmisi apabila tombol gear berada pada kedudukan N?', '["First gear is held","Reverse is engaged","Forward gears alternate","No gear is engaged"]'::jsonb, '["Gear satu dikekalkan","Gear undur dipilih","Gear hadapan bertukar","Tiada gear dipilih"]'::jsonb, 3, 'In Neutral, no drive gear is engaged. The book uses it as one option when starting the engine or stopping briefly.', 'Pada kedudukan N, tiada gear pemacu dipilih. Buku menyatakan kedudukan ini boleh digunakan ketika menghidupkan enjin atau berhenti seketika.', NULL, 'KPP Kelas DA Automatik, PDF 211'),
  ('307ca457-7884-5db3-a017-cc3e0e015ce0'::uuid, 'safety-principles', 'quiz-c-da-2', 1, 'How are the practical training hours split in this curriculum?', 'Bagaimanakah jam latihan amali dibahagikan dalam kurikulum ini?', '["10 circuit, 5½ road","6 circuit, 10 road","5½ circuit, 10 road","5½ circuit, 8 road"]'::jsonb, '["10 litar, 5½ jalan raya","6 litar, 10 jalan raya","5½ litar, 10 jalan raya","5½ litar, 8 jalan raya"]'::jsonb, 2, 'This curriculum lists five and a half hours of circuit training and ten hours of road training.', 'Kurikulum ini menyenaraikan lima jam setengah di litar dan sepuluh jam di jalan raya.', NULL, 'KPP Kelas DA Automatik, PDF 16'),
  ('366cfe73-2d16-5b85-a6c9-edfb63207b54'::uuid, 'safety-principles', 'quiz-c-da-2', 2, 'Your learner licence is still valid. How long must you have held it before you can take the practical tests in this curriculum?', 'Lesen belajar anda masih sah. Berapa lamakah lesen itu mesti dipegang sebelum menduduki ujian amali mengikut kurikulum ini?', '["More than 14 days","More than 21 days","More than 60 days","More than 30 days"]'::jsonb, '["Lebih daripada 14 hari","Lebih daripada 21 hari","Lebih daripada 60 hari","Lebih daripada 30 hari"]'::jsonb, 3, 'Before Parts II and III, the learner licence must still be valid and more than 30 days must have passed since issue.', 'Sebelum Ujian Bahagian II dan III, lesen belajar mesti masih sah dan lebih daripada 30 hari telah berlalu sejak tarikh ia dikeluarkan.', NULL, 'KPP Kelas DA Automatik, PDF 16'),
  ('1ddaf8c1-191a-541f-b955-cc77b60a5be0'::uuid, 'safety-principles', 'quiz-c-da-2', 3, 'What is the maximum total validity of a learner licence from its first issue?', 'Berapakah tempoh sah keseluruhan maksimum lesen belajar memandu dari tarikh pertama dikeluarkan?', '["12 months","18 months","36 months","24 months"]'::jsonb, '["12 bulan","18 bulan","36 bulan","24 bulan"]'::jsonb, 3, 'Learner licences can be renewed for three or six months at a time, up to two years from the first issue.', 'Lesen belajar memandu boleh diperbaharui untuk tiga atau enam bulan pada satu masa, sehingga dua tahun dari tarikh pertama dikeluarkan.', NULL, 'KPP Kelas DA Automatik, PDF 18'),
  ('389db7a7-b8c6-566e-9030-92ee2fe9cd6c'::uuid, 'safety-principles', 'quiz-c-da-2', 4, 'Who must accompany a learner driving a motorcar on an L licence?', 'Siapakah yang mesti menemani pemegang lesen L semasa memandu motokar?', '["Any competent licence holder","A driving institute instructor","A parent or guardian","A probationary licence holder"]'::jsonb, '["Mana-mana pemegang lesen kompeten","Pengajar institut memandu","Ibu bapa atau penjaga","Pemegang lesen percubaan"]'::jsonb, 1, 'A learner motorcar driver must drive with a driving institute instructor.', 'Pemegang lesen L bagi motokar mesti memandu bersama pengajar institut memandu.', NULL, 'KPP Kelas DA Automatik, PDF 18'),
  ('df588a0d-8bd0-5e12-8df5-96ef41e07583'::uuid, 'safety-principles', 'quiz-c-da-2', 5, 'Where are L signs displayed on a learner’s motorcar?', 'Di manakah tanda L dipamerkan pada motokar pelajar?', '["At the front and left","At the front and rear","At the rear and right","At the left and right"]'::jsonb, '["Di hadapan dan kiri","Di hadapan dan belakang","Di belakang dan kanan","Di kiri dan kanan"]'::jsonb, 1, 'A learner motorcar displays an L sign at the front and rear.', 'Motokar pelajar mempamerkan tanda L di bahagian hadapan dan belakang.', NULL, 'KPP Kelas DA Automatik, PDF 18'),
  ('ea75edcc-523a-57bd-a8aa-51f2d3ce3d78'::uuid, 'safety-principles', 'quiz-c-da-2', 6, 'How soon after passing the practical test should you apply for a probationary licence?', 'Dalam tempoh berapakah selepas lulus ujian praktikal anda perlu memohon lesen memandu percubaan?', '["6 months","18 months","12 months","24 months"]'::jsonb, '["6 bulan","18 bulan","12 bulan","24 bulan"]'::jsonb, 2, 'The practical test pass is valid for one year. Apply for the probationary licence within that period.', 'Keputusan lulus ujian praktikal sah selama setahun. Mohon lesen memandu percubaan dalam tempoh itu.', NULL, 'KPP Kelas DA Automatik, PDF 16'),
  ('2ceb9828-d702-5867-9422-5111788f61f9'::uuid, 'safety-principles', 'quiz-c-da-2', 7, 'How long is the probation period for a new probationary licence?', 'Berapa lamakah tempoh percubaan bagi lesen memandu percubaan yang baharu?', '["12 months","18 months","36 months","24 months"]'::jsonb, '["12 bulan","18 bulan","36 bulan","24 bulan"]'::jsonb, 3, 'The probationary licence gives new drivers two years to build experience under probation conditions.', 'Lesen memandu percubaan memberi pemandu baharu dua tahun untuk menimba pengalaman di bawah syarat percubaan.', NULL, 'KPP Kelas DA Automatik, PDF 20'),
  ('87a19d36-c8e1-54f6-aea7-7376f5ba211f'::uuid, 'safety-principles', 'quiz-c-da-2', 8, 'Where should you display the P signs on a motorcar?', 'Di manakah tanda P perlu dipamerkan pada motokar?', '["Upper right on both windscreens","Upper left on both windscreens","Lower left on both windscreens","Lower right on both windscreens"]'::jsonb, '["Kanan atas pada kedua-dua cermin","Kiri atas pada kedua-dua cermin","Kiri bawah pada kedua-dua cermin","Kanan bawah pada kedua-dua cermin"]'::jsonb, 1, 'Display a P sign at the upper left corner of both the front and rear windscreens.', 'Pamerkan tanda P di penjuru kiri atas cermin hadapan dan belakang.', NULL, 'KPP Kelas DA Automatik, PDF 21'),
  ('71bc0954-24cd-5791-9946-87ce6c45c9b9'::uuid, 'safety-principles', 'quiz-c-da-2', 9, 'What alcohol level does this curriculum specify for a P licence holder while driving?', 'Apakah kadar alkohol yang ditetapkan dalam kurikulum ini bagi pemegang lesen P semasa memandu?', '["0.02%","0.05%","0.00%","0.08%"]'::jsonb, '["0.02%","0.05%","0.00%","0.08%"]'::jsonb, 2, 'The probationary licence conditions specify 0.00% alcohol in breath, blood and urine.', 'Syarat lesen percubaan menetapkan 0.00% alkohol dalam nafas, darah dan air kencing.', NULL, 'KPP Kelas DA Automatik, PDF 20'),
  ('ec06b292-cf09-5014-92d9-3f0d8aabeeb2'::uuid, 'safety-principles', 'quiz-c-da-2', 10, 'How long after a probationary licence expires can you apply to convert it to a competent licence?', 'Berapa lamakah selepas lesen percubaan tamat tempoh anda boleh memohon pertukaran kepada lesen kompeten?', '["3 months","6 months","12 months","24 months"]'::jsonb, '["3 bulan","6 bulan","12 bulan","24 bulan"]'::jsonb, 2, 'Apply within one year of the probationary licence expiry date.', 'Buat permohonan dalam tempoh setahun daripada tarikh tamat lesen percubaan.', NULL, 'KPP Kelas DA Automatik, PDF 22'),
  ('3d90970a-a1b0-533d-8d4c-41cb12979203'::uuid, 'safety-principles', 'quiz-c-da-2', 11, 'How long after expiry does this textbook list for automatic cancellation of a competent licence?', 'Berapa lamakah selepas tamat tempoh lesen kompeten terbatal secara automatik mengikut buku ini?', '["More than 1 year","More than 2 years","More than 5 years","More than 3 years"]'::jsonb, '["Melebihi 1 tahun","Melebihi 2 tahun","Melebihi 5 tahun","Melebihi 3 tahun"]'::jsonb, 3, 'The table lists cancellation once a competent licence has remained expired for more than three years.', 'Jadual menyenaraikan pembatalan apabila lesen kompeten telah tamat tempoh melebihi tiga tahun.', NULL, 'KPP Kelas DA Automatik, PDF 25'),
  ('2fe239d6-4fb7-53de-bb9e-d06c5a86a2f9'::uuid, 'safety-principles', 'quiz-c-da-2', 12, 'You are on a level road in an automatic car and speed varies with traffic. How are forward gears selected in the normal selector position?', 'Anda memandu kereta automatik di jalan rata dan kelajuan berubah mengikut trafik. Bagaimanakah gear hadapan dipilih pada kedudukan pemanduan biasa?', '["The car selects them","The driver selects each one","The car holds one gear","The driver must stop to shift"]'::jsonb, '["Kereta memilih gear","Pemandu memilih setiap gear","Kereta kekal pada satu gear","Pemandu mesti berhenti untuk menukar gear"]'::jsonb, 0, 'The transmission selects a gear to suit vehicle speed and the power needed.', 'Transmisi memilih gear mengikut kelajuan kenderaan dan kuasa yang diperlukan.', NULL, 'KPP Kelas DA Automatik, PDF 211'),
  ('617e5d81-c3f7-5c48-b667-e35682082ec7'::uuid, 'safety-principles', 'quiz-c-da-2', 13, 'In an automatic with a 3 position, which gears are available when you select it?', 'Bagi kereta automatik dengan kedudukan 3, gear manakah yang boleh digunakan apabila kedudukan itu dipilih?', '["Gear 3 only","Gears 1 to 3","Gears 2 and 3","All forward gears"]'::jsonb, '["Gear 3 sahaja","Gear 1 hingga 3","Gear 2 dan 3","Semua gear hadapan"]'::jsonb, 1, 'Position 3 allows gears 1, 2 and 3. The book gives downhill driving as one example of its use.', 'Kedudukan 3 membenarkan gear 1, 2 dan 3. Buku memberikan pemanduan menuruni bukit sebagai satu contoh penggunaannya.', NULL, 'KPP Kelas DA Automatik, PDF 212'),
  ('9062ee2a-b27f-5edc-b5dd-9ccc8bc0b0ad'::uuid, 'safety-principles', 'quiz-c-da-2', 14, 'Why might you select 2 on a steep descent in an automatic with that selector position?', 'Mengapakah kedudukan 2 boleh dipilih ketika menuruni cerun curam dengan kereta automatik yang mempunyai pilihan itu?', '["For less engine braking","To let the car coast","For more engine braking","To allow higher gears"]'::jsonb, '["Untuk mengurangkan brek enjin","Untuk membiarkan kereta meluncur","Untuk menambah brek enjin","Untuk membenarkan gear lebih tinggi"]'::jsonb, 2, 'The book describes using position 2 on steep descents to increase engine braking.', 'Buku menerangkan penggunaan kedudukan 2 ketika menuruni cerun curam untuk menambah kesan brek enjin.', NULL, 'KPP Kelas DA Automatik, PDF 212'),
  ('fe6eff64-3b49-5265-9d87-c9eb4d443694'::uuid, 'safety-principles', 'quiz-c-da-2', 15, 'With the selector in L, which behaviour should you expect?', 'Dengan pemilih gear pada L, apakah tindak balas yang patut dijangka?', '["The transmission stays in its lowest range","The transmission steps through the forward ranges","The transmission disengages drive","The transmission shifts straight into top gear"]'::jsonb, '["Transmisi kekal dalam julat terendah","Transmisi bertukar melalui julat hadapan","Transmisi memutuskan pacuan","Transmisi terus menukar ke gear tertinggi"]'::jsonb, 0, 'L holds the transmission in low gear. The book uses it for very steep slopes.', 'Kedudukan L mengekalkan gear rendah. Buku menerangkan penggunaannya pada cerun yang sangat curam.', NULL, 'KPP Kelas DA Automatik, PDF 213'),
  ('1a41d36b-9838-58a4-97c4-1c0ccbf016c8'::uuid, 'safety-principles', 'quiz-c-da-3', 1, 'Which licence follows the probationary licence in the curriculum’s licensing process?', 'Lesen manakah menyusuli lesen percubaan dalam proses pelesenan yang diterangkan?', '["Learner’s driving licence","Competent driving licence","Vocational driving licence","International driving permit"]'::jsonb, '["Lesen belajar memandu","Lesen memandu kompeten","Lesen memandu vokasional","Permit memandu antarabangsa"]'::jsonb, 1, 'Drivers who complete probation apply to change from a probationary to a competent driving licence.', 'Pemandu yang menamatkan tempoh percubaan memohon pertukaran daripada lesen percubaan kepada lesen kompeten.', NULL, 'KPP Kelas DA Automatik, PDF 22'),
  ('61301589-fc11-5283-b867-8f24c91e0834'::uuid, 'safety-principles', 'quiz-c-da-3', 2, 'Under this curriculum, what can a driver skip when adding a class from the same licence group?', 'Mengikut kurikulum ini, apakah yang boleh dikecualikan apabila menambah kelas daripada kumpulan lesen yang sama?', '["The practical training and tests","The practical tests only","The road training only","The theory course and test"]'::jsonb, '["Latihan dan ujian amali","Ujian amali sahaja","Latihan jalan raya sahaja","Kursus dan ujian teori"]'::jsonb, 3, 'The same-group exemption covers the KPP01 course and Part I theory test. Practical training and tests still apply.', 'Pengecualian bagi kumpulan yang sama meliputi kursus KPP01 dan ujian teori Bahagian I. Latihan dan ujian amali masih diperlukan.', NULL, 'KPP Kelas DA Automatik, PDF 14'),
  ('0949895f-9228-52c6-b01f-56b3e67a628d'::uuid, 'safety-principles', 'quiz-c-da-3', 3, 'Which licence category covers driving a bus with fare-paying passengers?', 'Kategori lesen manakah meliputi pemanduan bas yang membawa penumpang berbayar?', '["PSV","GDL","CDL alone","PDL alone"]'::jsonb, '["PSV","GDL","CDL sahaja","PDL sahaja"]'::jsonb, 0, 'PSV covers public service vehicles, including buses. GDL is for goods vehicles.', 'PSV meliputi kenderaan perkhidmatan awam termasuk bas. GDL ialah lesen untuk kenderaan barangan.', NULL, 'KPP Kelas DA Automatik, PDF 23'),
  ('c5a67b24-68a3-52b9-9bf5-91a727b86c52'::uuid, 'safety-principles', 'quiz-c-da-3', 4, 'Which specific vision check appears in the handbook’s eligibility requirements?', 'Pemeriksaan penglihatan khusus manakah dinyatakan dalam syarat kelayakan buku panduan?', '["Colour vision","Peripheral vision","Night vision","Depth perception"]'::jsonb, '["Penglihatan warna","Penglihatan sisi","Penglihatan malam","Persepsi kedalaman"]'::jsonb, 0, 'Eligibility includes being able to see ahead for 23 metres and not being colour blind.', 'Kelayakan termasuk boleh melihat ke hadapan sejauh 23 meter dan tidak buta warna.', NULL, 'KPP Kelas DA Automatik, PDF 11'),
  ('9ed30234-6567-5a65-8730-1175df00a96b'::uuid, 'safety-principles', 'quiz-c-da-3', 5, 'What does the name KEJARA stand for?', 'Apakah nama penuh KEJARA?', '["Sistem Kelayakan Jalan Raya","Sistem Keselamatan Jalan Raya","Sistem Kesalahan Jalan Raya","Sistem Kawalan Jalan Raya"]'::jsonb, '["Sistem Kelayakan Jalan Raya","Sistem Keselamatan Jalan Raya","Sistem Kesalahan Jalan Raya","Sistem Kawalan Jalan Raya"]'::jsonb, 1, 'KEJARA is short for Sistem Keselamatan Jalan Raya. It assigns demerit points for scheduled offences.', 'KEJARA ialah singkatan bagi Sistem Keselamatan Jalan Raya. Sistem ini memberikan mata demerit bagi kesalahan terjadual.', NULL, 'KPP General, PDF 93'),
  ('3aa09fe1-a4de-506e-a3e5-a5135fe23b9c'::uuid, 'safety-principles', 'quiz-c-da-3', 6, 'What does this curriculum say happens to a P licence at 20 demerit points?', 'Apakah kesan 20 mata demerit pada lesen P mengikut kurikulum ini?', '["The licence is suspended","A warning is issued","The licence is cancelled","A course is required"]'::jsonb, '["Lesen digantung","Amaran dikeluarkan","Lesen dibatalkan","Kursus diwajibkan"]'::jsonb, 2, 'The P licence conditions state that reaching 20 points or more results in cancellation.', 'Syarat lesen P menyatakan bahawa 20 mata atau lebih mengakibatkan lesen dibatalkan.', NULL, 'KPP Kelas DA Automatik, PDF 20'),
  ('644c2720-f22c-5723-b84f-b1fdb445e0e1'::uuid, 'safety-principles', 'quiz-c-da-3', 7, 'What is the first action shown in the KEJARA schedule when a competent licence holder reaches 20 points?', 'Apakah tindakan pertama dalam jadual KEJARA apabila pemegang lesen kompeten mencapai 20 mata?', '["A suspension","A cancellation","A course referral","A warning"]'::jsonb, '["Penggantungan","Pembatalan","Rujukan kursus","Amaran"]'::jsonb, 3, 'The first threshold shown in the schedule results in a warning.', 'Ambang kali pertama dalam jadual ini membawa kepada amaran.', NULL, 'KPP General, PDF 95'),
  ('570b097b-57be-5bf9-90e8-417d01290fc9'::uuid, 'safety-principles', 'quiz-c-da-3', 8, 'A competent licence holder has already received one KEJARA warning and reaches another 20 points. What suspension range applies in the handbook table?', 'Pemegang lesen kompeten telah menerima satu amaran KEJARA dan mencapai 20 mata lagi. Apakah julat penggantungan dalam jadual buku panduan?', '["6–8 months","4–6 months","8–10 months","10–12 months"]'::jsonb, '["6–8 bulan","4–6 bulan","8–10 bulan","10–12 bulan"]'::jsonb, 0, 'The table shows a first suspension of six to eight months for the second threshold.', 'Jadual menunjukkan penggantungan pertama selama enam hingga lapan bulan bagi ambang kali kedua.', NULL, 'KPP General, PDF 95'),
  ('cdcaa97a-c612-5231-a71c-aeab15386075'::uuid, 'safety-principles', 'quiz-c-da-3', 9, 'A competent licence holder receives a second suspension under the handbook KEJARA schedule. Which range applies?', 'Pemegang lesen kompeten menerima penggantungan kali kedua mengikut jadual KEJARA. Apakah julatnya?', '["8–10 months","4–6 months","6–8 months","10–12 months"]'::jsonb, '["8–10 bulan","4–6 bulan","6–8 bulan","10–12 bulan"]'::jsonb, 0, 'The third threshold in the table can result in a suspension of eight to ten months.', 'Ambang kali ketiga dalam jadual boleh menyebabkan penggantungan lapan hingga sepuluh bulan.', NULL, 'KPP General, PDF 95'),
  ('1151c489-8fb0-540a-96b1-951c280ae482'::uuid, 'safety-principles', 'quiz-c-da-3', 10, 'What action can follow three licence suspensions within five years?', 'Apakah tindakan yang boleh diambil selepas tiga penggantungan lesen dalam tempoh lima tahun?', '["An additional warning","A driving course referral","Licence cancellation","Automatic licence renewal"]'::jsonb, '["Amaran tambahan","Rujukan kursus memandu","Pembatalan lesen","Pembaharuan lesen automatik"]'::jsonb, 2, 'The KEJARA schedule describes cancellation action after three suspensions within five years.', 'Jadual KEJARA menerangkan tindakan pembatalan selepas tiga penggantungan dalam tempoh lima tahun.', NULL, 'KPP General, PDF 95'),
  ('dc877c0e-2e5a-5c34-b0d0-9171bb32aafd'::uuid, 'safety-principles', 'quiz-c-da-3', 11, 'What reduction can be considered after 12 months without a scheduled offence?', 'Apakah pengurangan yang boleh dipertimbangkan selepas 12 bulan tanpa kesalahan terjadual?', '["Up to a quarter of the points","Half of the court fine","All points immediately","Up to half the points"]'::jsonb, '["Sehingga suku mata","Separuh denda mahkamah","Semua mata serta-merta","Sehingga separuh mata"]'::jsonb, 3, 'The schedule lists a possible deduction of up to half the accumulated demerit points.', 'Jadual menyenaraikan potongan sehingga separuh daripada mata demerit yang terkumpul.', NULL, 'KPP General, PDF 95'),
  ('24a7d974-4d7d-5f22-ba42-83d30a9eb19b'::uuid, 'safety-principles', 'quiz-c-da-3', 12, 'Why does the automatic selector have a button you must press for some movements?', 'Mengapa pemilih gear automatik mempunyai butang yang perlu ditekan bagi sesetengah pergerakan?', '["To stop certain shifts happening by accident","To help the selector move more quickly","To make selected gears easier to read","To let the driver skip every other position"]'::jsonb, '["Untuk mengelakkan pertukaran tertentu secara tidak sengaja","Untuk membantu tuil bergerak lebih pantas","Untuk memudahkan bacaan gear terpilih","Untuk membolehkan pemandu melangkau kedudukan tertentu"]'::jsonb, 0, 'The lock helps prevent accidental selection of positions that need extra care.', 'Pengunci membantu mengelakkan pemilihan gear yang memerlukan perhatian tambahan secara tidak sengaja.', NULL, 'KPP Kelas DA Automatik, PDF 213'),
  ('cf3f3eea-c51e-5447-a72a-35df8d5bbfe6'::uuid, 'safety-principles', 'quiz-c-da-3', 13, 'Which pair of positions requires the lock button on the selector shown in this curriculum?', 'Pasangan kedudukan manakah memerlukan butang pengunci pada tombol gear yang ditunjukkan dalam kurikulum ini?', '["N and D","P and R","D and 3","N and 3"]'::jsonb, '["N dan D","P dan R","D dan 3","N dan 3"]'::jsonb, 1, 'The book says to press the button when selecting P or R. It also describes using the button for low positions 2 and L.', 'Buku menyatakan butang perlu ditekan apabila memilih P atau R. Butang juga digunakan bagi kedudukan rendah 2 dan L.', NULL, 'KPP Kelas DA Automatik, PDF 214'),
  ('298552f9-2475-520c-a335-5c75e87d100a'::uuid, 'safety-principles', 'quiz-c-da-3', 14, 'You move the selector while stopped. Which readout confirms the transmission is in the intended range?', 'Anda menggerakkan pemilih semasa berhenti. Paparan manakah mengesahkan transmisi berada dalam julat yang dimaksudkan?', '["The P/R/N/D indicator","The engine speed reading","The speedometer reading","The parking brake warning lamp"]'::jsonb, '["Penunjuk P/R/N/D","Bacaan putaran enjin","Bacaan meter laju","Lampu amaran brek parkir"]'::jsonb, 0, 'Check the gear position on the instrument display. Avoid looking down at the gear lever while driving.', 'Semak kedudukan gear pada paparan panel meter. Elakkan melihat ke bawah pada tombol gear semasa memandu.', NULL, 'KPP Kelas DA Automatik, PDF 215'),
  ('623e6fb6-3f4a-517a-990a-e9cc460d8a63'::uuid, 'safety-principles', 'quiz-c-da-3', 15, 'During the pre-drive routine, how should you use the accelerator when starting an automatic car?', 'Semasa rutin sebelum memandu, bagaimanakah pedal pemecut perlu digunakan ketika menghidupkan kereta automatik?', '["Press it slightly","Press it fully","Pump it once","Leave it released"]'::jsonb, '["Tekan sedikit","Tekan sepenuhnya","Pam sekali","Biarkan tanpa ditekan"]'::jsonb, 3, 'The pre-drive routine says to start the engine without pressing the accelerator.', 'Rutin sebelum memandu menyatakan enjin perlu dihidupkan tanpa menekan pedal pemecut.', NULL, 'KPP Kelas DA Automatik, PDF 208'),
  ('1532b093-0e9b-59cb-8732-12e2022fd5ae'::uuid, 'safety-principles', 'quiz-c-d-1', 1, 'What is the minimum age to apply for a motorcycle licence?', 'Berapakah umur minimum untuk memohon lesen motosikal?', '["15 years","17 years","16 years","18 years"]'::jsonb, '["15 tahun","17 tahun","16 tahun","18 tahun"]'::jsonb, 2, 'The curriculum lists 16 as the minimum age for a motorcycle licence.', 'Kurikulum menetapkan umur minimum 16 tahun bagi permohonan lesen motosikal.', NULL, 'KPP General, PDF 9'),
  ('87b76e13-c358-52c8-851b-a03f4325a9e5'::uuid, 'safety-principles', 'quiz-c-d-1', 2, 'What is the minimum age for the motorcar licence classes?', 'Berapakah umur minimum bagi kelas lesen motokar?', '["16 years","18 years","17 years","21 years"]'::jsonb, '["16 tahun","18 tahun","17 tahun","21 tahun"]'::jsonb, 2, 'Applicants for a motorcar licence must be at least 17 years old.', 'Pemohon lesen motokar mestilah berumur sekurang-kurangnya 17 tahun.', NULL, 'KPP Kelas DA Automatik, PDF 11'),
  ('15a1188f-b504-51b8-91ed-fd3b0adb5bcb'::uuid, 'safety-principles', 'quiz-c-d-1', 3, 'What kind of vehicle does the Class E classification cover in this textbook?', 'Apakah jenis kenderaan bagi Kelas E dalam buku ini?', '["A car without a clutch pedal","An adapted motorcycle","A light tracked tractor","A heavy motor vehicle"]'::jsonb, '["Motokar tanpa pedal cekam","Motosikal yang diubah suai","Traktor ringan berantai","Motokar berat"]'::jsonb, 3, 'Class E is listed for heavy motor vehicles over 7,500 kg unladen.', 'Kelas E disenaraikan untuk motokar berat dengan berat tanpa muatan melebihi 7,500 kg.', NULL, 'KPP Kelas DA Automatik, PDF 10'),
  ('4eca0a4c-2ff5-5525-ba65-ce90b5c7c4cc'::uuid, 'safety-principles', 'quiz-c-d-1', 4, 'Which vocational endorsement applies to a rider delivering parcels for work?', 'Lesen vokasional manakah digunakan oleh penunggang yang menghantar bungkusan untuk kerja?', '["GDL","PSV","Conductor licence","No vocational endorsement"]'::jsonb, '["GDL","PSV","Lesen konduktor","Tiada lesen vokasional"]'::jsonb, 0, 'The vocational categories list goods vehicle licensing, including motorcycles, under GDL.', 'Kategori lesen vokasional menyenaraikan motosikal barangan di bawah lesen GDL.', NULL, 'KPP Kelas DA Automatik, PDF 23'),
  ('7c6c4b24-573d-5060-98dd-c056de095332'::uuid, 'safety-principles', 'quiz-c-d-1', 5, 'Which vehicle does a Class A1 licence cover?', 'Kenderaan manakah yang termasuk dalam lesen Kelas A1?', '["An adapted motorcycle","A light goods vehicle","An adapted motorcar","A three-wheel motorcycle"]'::jsonb, '["Motosikal yang diubah suai","Kenderaan barangan ringan","Motokar yang diubah suai","Motosikal tiga roda"]'::jsonb, 2, 'Class A1 covers adapted motorcars for drivers with disabilities. Class A covers adapted motorcycles.', 'Kelas A1 meliputi motokar yang diubah suai untuk pemandu orang kurang upaya. Kelas A meliputi motosikal yang diubah suai.', NULL, 'KPP Kelas DA Automatik, PDF 17'),
  ('5a6a1e81-44e3-5a1e-9f85-5ae82d4eddc8'::uuid, 'safety-principles', 'quiz-c-d-1', 6, 'What is the engine capacity limit for a Class B2 motorcycle?', 'Berapakah had kapasiti enjin bagi motosikal Kelas B2?', '["150 cc","300 cc","500 cc","250 cc"]'::jsonb, '["150 cc","300 cc","500 cc","250 cc"]'::jsonb, 3, 'Class B2 covers personal motorcycles up to 250 cc.', 'Kelas B2 meliputi motosikal persendirian sehingga 250 cc.', NULL, 'KPP Kelas DA Automatik, PDF 10'),
  ('cc2194b4-08c4-5d6b-8a98-859053a4622d'::uuid, 'safety-principles', 'quiz-c-d-1', 7, 'What is the maximum unladen weight for a Class D or DA motorcar?', 'Berapakah berat tanpa muatan maksimum bagi motokar Kelas D atau DA?', '["2500 kg","5000 kg","7500 kg","3500 kg"]'::jsonb, '["2500 kg","5000 kg","7500 kg","3500 kg"]'::jsonb, 3, 'The Class D and DA classifications both have an unladen weight limit of 3,500 kg.', 'Kelas D dan DA mempunyai had berat tanpa muatan sebanyak 3,500 kg.', NULL, 'KPP Kelas DA Automatik, PDF 10'),
  ('c09e9bbb-24c4-50d8-b46d-6693d9139416'::uuid, 'safety-principles', 'quiz-c-d-1', 8, 'Which group of vehicles is covered by Classes F, G, H and I?', 'Kumpulan kenderaan manakah yang diliputi oleh Kelas F, G, H dan I?', '["Lorries and articulated trailers","Tractors and mobile machinery","Buses and passenger vans","Motorcars and small vans"]'::jsonb, '["Lori dan treler bersendi","Traktor dan jentera bergerak","Bas dan van penumpang","Motokar dan van kecil"]'::jsonb, 1, 'These classes cover tractors and mobile machinery. They distinguish wheels from tracks and lighter from heavier vehicles.', 'Kelas ini meliputi traktor dan jentera bergerak. Kelasnya dibezakan mengikut roda atau rantai serta berat kenderaan.', NULL, 'KPP Kelas DA Automatik, PDF 10'),
  ('503ce92d-9422-5df1-afd6-e2fec6992fdf'::uuid, 'safety-principles', 'quiz-c-d-1', 9, 'How long is the KPP01 course for this class before the Part I test?', 'Berapa lamakah kursus KPP01 bagi kelas ini sebelum Ujian Bahagian I?', '["4 hours","6 hours","5 hours","8 hours"]'::jsonb, '["4 jam","6 jam","5 jam","8 jam"]'::jsonb, 1, 'Candidates attend six hours of KPP01 before taking the Part I test.', 'Calon mengikuti KPP01 selama enam jam sebelum menduduki Ujian Bahagian I.', NULL, 'KPP Kelas DA Automatik, PDF 15'),
  ('08c36aee-c226-5461-8342-d42e7e50a185'::uuid, 'safety-principles', 'quiz-c-d-1', 10, 'What score passes the 50-question Part I test described in this curriculum?', 'Berapakah markah lulus bagi Ujian Bahagian I dengan 50 soalan yang diterangkan dalam kurikulum ini?', '["40 out of 50","43 out of 50","42 out of 50","45 out of 50"]'::jsonb, '["40 daripada 50","43 daripada 50","42 daripada 50","45 daripada 50"]'::jsonb, 2, 'This curriculum describes a 50-question test with a pass mark of 42 and a time limit of 45 minutes.', 'Kurikulum ini menerangkan ujian 50 soalan dengan markah lulus 42 dan tempoh 45 minit.', NULL, 'KPP Kelas DA Automatik, PDF 15'),
  ('23b9ebe7-9c75-5c34-a488-cf2fd6c06b51'::uuid, 'safety-principles', 'quiz-c-d-1', 11, 'For how long is a Part I pass valid?', 'Berapa lamakah keputusan lulus Ujian Bahagian I sah?', '["6 months","18 months","24 months","12 months"]'::jsonb, '["6 bulan","18 bulan","24 bulan","12 bulan"]'::jsonb, 3, 'The validity period starts on the day the candidate passes and lasts one year.', 'Tempoh sah bermula pada tarikh calon lulus dan berakhir selepas setahun.', NULL, 'KPP Kelas DA Automatik, PDF 16'),
  ('71fac706-76b7-598d-8c6d-651c46d4a629'::uuid, 'safety-principles', 'quiz-c-d-1', 12, 'Which is the correct left-to-right pedal order in the manual car shown?', 'Apakah susunan pedal dari kiri ke kanan dalam kereta manual yang ditunjukkan?', '["Clutch, brake, accelerator","Brake, clutch, accelerator","Clutch, accelerator, brake","Accelerator, brake, clutch"]'::jsonb, '["Cekam, brek, pemecut","Brek, cekam, pemecut","Cekam, pemecut, brek","Pemecut, brek, cekam"]'::jsonb, 0, 'The diagram shows the clutch on the left, brake in the middle, and accelerator on the right.', 'Rajah menunjukkan pedal cekam di kiri, brek di tengah dan pemecut di kanan.', NULL, 'KPP Kelas D Manual, PDF 218'),
  ('be3d3ad4-9ec2-51db-a409-7fa135906c99'::uuid, 'safety-principles', 'quiz-c-d-1', 13, 'What happens to engine power going to the gearbox when you press the clutch fully?', 'Apakah yang berlaku kepada kuasa enjin ke kotak gear apabila pedal cekam ditekan sepenuhnya?', '["Power is increased","Power is disconnected","Power stays connected","Power changes direction"]'::jsonb, '["Kuasa bertambah","Kuasa diputuskan","Kuasa kekal bersambung","Kuasa bertukar arah"]'::jsonb, 1, 'Pressing the clutch with the left foot disconnects engine power from the gearbox. Releasing it reconnects the power.', 'Menekan cekam dengan kaki kiri memutuskan kuasa enjin ke kotak gear. Melepaskannya menyambungkan semula kuasa.', NULL, 'KPP Kelas D Manual, PDF 215'),
  ('a6e4d877-1ba3-5739-9505-6c90c94cee37'::uuid, 'safety-principles', 'quiz-c-d-1', 14, 'What engine sound can indicate that you have reached the clutch biting point while moving off?', 'Apakah perubahan bunyi enjin yang menunjukkan titik pergerakan cekam ketika mula bergerak?', '["The engine speeds up slightly","The engine holds the same note","The engine slows slightly","The engine goes completely quiet"]'::jsonb, '["Putaran enjin mula meningkat","Bunyi enjin kekal sama","Putaran enjin mula perlahan","Bunyi enjin hilang sepenuhnya"]'::jsonb, 2, 'Raise the clutch slowly with slight accelerator pressure. The book says a drop in engine speed indicates the biting point.', 'Angkat pedal cekam perlahan-lahan sambil menekan pemecut sedikit. Buku menyatakan putaran enjin yang mula perlahan menandakan titik pergerakan.', NULL, 'KPP Kelas D Manual, PDF 216'),
  ('a18b1396-757a-51e0-92f3-df1a1d6b009f'::uuid, 'safety-principles', 'quiz-c-d-1', 15, 'How should you raise the clutch pedal to pull away smoothly?', 'Bagaimanakah pedal cekam perlu diangkat supaya kereta mula bergerak dengan lancar?', '["Raise it in one quick motion","Raise it halfway at once","Pump it up and down","Raise it gradually"]'::jsonb, '["Angkat dengan satu gerakan cepat","Angkat separuh dengan segera","Pam ke atas dan ke bawah","Angkat secara beransur-ansur"]'::jsonb, 3, 'With first gear selected and slight accelerator pressure, raise the clutch gradually to the biting point.', 'Dengan gear satu dipilih dan pemecut ditekan sedikit, angkat pedal cekam secara beransur-ansur hingga titik pergerakan.', NULL, 'KPP Kelas D Manual, PDF 216'),
  ('482626c7-fd1f-5a5c-9213-8a4b723195ff'::uuid, 'safety-principles', 'quiz-c-d-2', 1, 'How are the practical training hours split in this curriculum?', 'Bagaimanakah jam latihan amali dibahagikan dalam kurikulum ini?', '["10 circuit, 5½ road","6 circuit, 10 road","5½ circuit, 10 road","5½ circuit, 8 road"]'::jsonb, '["10 litar, 5½ jalan raya","6 litar, 10 jalan raya","5½ litar, 10 jalan raya","5½ litar, 8 jalan raya"]'::jsonb, 2, 'This curriculum lists five and a half hours of circuit training and ten hours of road training.', 'Kurikulum ini menyenaraikan lima jam setengah di litar dan sepuluh jam di jalan raya.', NULL, 'KPP Kelas DA Automatik, PDF 16'),
  ('032d9db4-6ac2-50ee-9c6d-536112a34828'::uuid, 'safety-principles', 'quiz-c-d-2', 2, 'Your learner licence is still valid. How long must you have held it before you can take the practical tests in this curriculum?', 'Lesen belajar anda masih sah. Berapa lamakah lesen itu mesti dipegang sebelum menduduki ujian amali mengikut kurikulum ini?', '["More than 14 days","More than 21 days","More than 60 days","More than 30 days"]'::jsonb, '["Lebih daripada 14 hari","Lebih daripada 21 hari","Lebih daripada 60 hari","Lebih daripada 30 hari"]'::jsonb, 3, 'Before Parts II and III, the learner licence must still be valid and more than 30 days must have passed since issue.', 'Sebelum Ujian Bahagian II dan III, lesen belajar mesti masih sah dan lebih daripada 30 hari telah berlalu sejak tarikh ia dikeluarkan.', NULL, 'KPP Kelas DA Automatik, PDF 16'),
  ('367dbd33-f423-5634-9920-f717497cadb0'::uuid, 'safety-principles', 'quiz-c-d-2', 3, 'What is the maximum total validity of a learner licence from its first issue?', 'Berapakah tempoh sah keseluruhan maksimum lesen belajar memandu dari tarikh pertama dikeluarkan?', '["12 months","18 months","36 months","24 months"]'::jsonb, '["12 bulan","18 bulan","36 bulan","24 bulan"]'::jsonb, 3, 'Learner licences can be renewed for three or six months at a time, up to two years from the first issue.', 'Lesen belajar memandu boleh diperbaharui untuk tiga atau enam bulan pada satu masa, sehingga dua tahun dari tarikh pertama dikeluarkan.', NULL, 'KPP Kelas DA Automatik, PDF 18'),
  ('ca5db830-332f-5f02-ad61-8949ea5ccf17'::uuid, 'safety-principles', 'quiz-c-d-2', 4, 'Who must accompany a learner driving a motorcar on an L licence?', 'Siapakah yang mesti menemani pemegang lesen L semasa memandu motokar?', '["Any competent licence holder","A driving institute instructor","A parent or guardian","A probationary licence holder"]'::jsonb, '["Mana-mana pemegang lesen kompeten","Pengajar institut memandu","Ibu bapa atau penjaga","Pemegang lesen percubaan"]'::jsonb, 1, 'A learner motorcar driver must drive with a driving institute instructor.', 'Pemegang lesen L bagi motokar mesti memandu bersama pengajar institut memandu.', NULL, 'KPP Kelas DA Automatik, PDF 18'),
  ('4c3ba8ae-3188-5576-a108-70e026925e53'::uuid, 'safety-principles', 'quiz-c-d-2', 5, 'Where are L signs displayed on a learner’s motorcar?', 'Di manakah tanda L dipamerkan pada motokar pelajar?', '["At the front and left","At the front and rear","At the rear and right","At the left and right"]'::jsonb, '["Di hadapan dan kiri","Di hadapan dan belakang","Di belakang dan kanan","Di kiri dan kanan"]'::jsonb, 1, 'A learner motorcar displays an L sign at the front and rear.', 'Motokar pelajar mempamerkan tanda L di bahagian hadapan dan belakang.', NULL, 'KPP Kelas DA Automatik, PDF 18'),
  ('5a837190-b917-5df6-9bb9-60a4f7823bc5'::uuid, 'safety-principles', 'quiz-c-d-2', 6, 'How soon after passing the practical test should you apply for a probationary licence?', 'Dalam tempoh berapakah selepas lulus ujian praktikal anda perlu memohon lesen memandu percubaan?', '["6 months","18 months","12 months","24 months"]'::jsonb, '["6 bulan","18 bulan","12 bulan","24 bulan"]'::jsonb, 2, 'The practical test pass is valid for one year. Apply for the probationary licence within that period.', 'Keputusan lulus ujian praktikal sah selama setahun. Mohon lesen memandu percubaan dalam tempoh itu.', NULL, 'KPP Kelas DA Automatik, PDF 16'),
  ('b9670e16-85cf-5b76-8bcf-26021bc747e6'::uuid, 'safety-principles', 'quiz-c-d-2', 7, 'How long is the probation period for a new probationary licence?', 'Berapa lamakah tempoh percubaan bagi lesen memandu percubaan yang baharu?', '["12 months","18 months","36 months","24 months"]'::jsonb, '["12 bulan","18 bulan","36 bulan","24 bulan"]'::jsonb, 3, 'The probationary licence gives new drivers two years to build experience under probation conditions.', 'Lesen memandu percubaan memberi pemandu baharu dua tahun untuk menimba pengalaman di bawah syarat percubaan.', NULL, 'KPP Kelas DA Automatik, PDF 20'),
  ('1b4d817d-002f-5fbf-8c8d-b913fb7676c6'::uuid, 'safety-principles', 'quiz-c-d-2', 8, 'Where should you display the P signs on a motorcar?', 'Di manakah tanda P perlu dipamerkan pada motokar?', '["Upper right on both windscreens","Upper left on both windscreens","Lower left on both windscreens","Lower right on both windscreens"]'::jsonb, '["Kanan atas pada kedua-dua cermin","Kiri atas pada kedua-dua cermin","Kiri bawah pada kedua-dua cermin","Kanan bawah pada kedua-dua cermin"]'::jsonb, 1, 'Display a P sign at the upper left corner of both the front and rear windscreens.', 'Pamerkan tanda P di penjuru kiri atas cermin hadapan dan belakang.', NULL, 'KPP Kelas DA Automatik, PDF 21'),
  ('a147cc55-afa1-548b-91cf-bf55d35b7058'::uuid, 'safety-principles', 'quiz-c-d-2', 9, 'What alcohol level does this curriculum specify for a P licence holder while driving?', 'Apakah kadar alkohol yang ditetapkan dalam kurikulum ini bagi pemegang lesen P semasa memandu?', '["0.02%","0.05%","0.00%","0.08%"]'::jsonb, '["0.02%","0.05%","0.00%","0.08%"]'::jsonb, 2, 'The probationary licence conditions specify 0.00% alcohol in breath, blood and urine.', 'Syarat lesen percubaan menetapkan 0.00% alkohol dalam nafas, darah dan air kencing.', NULL, 'KPP Kelas DA Automatik, PDF 20'),
  ('9203c254-a475-57bb-bf1f-e5ecad90f947'::uuid, 'safety-principles', 'quiz-c-d-2', 10, 'How long after a probationary licence expires can you apply to convert it to a competent licence?', 'Berapa lamakah selepas lesen percubaan tamat tempoh anda boleh memohon pertukaran kepada lesen kompeten?', '["3 months","6 months","12 months","24 months"]'::jsonb, '["3 bulan","6 bulan","12 bulan","24 bulan"]'::jsonb, 2, 'Apply within one year of the probationary licence expiry date.', 'Buat permohonan dalam tempoh setahun daripada tarikh tamat lesen percubaan.', NULL, 'KPP Kelas DA Automatik, PDF 22'),
  ('0d983059-ac29-516c-9a63-680dde825282'::uuid, 'safety-principles', 'quiz-c-d-2', 11, 'How long after expiry does this textbook list for automatic cancellation of a competent licence?', 'Berapa lamakah selepas tamat tempoh lesen kompeten terbatal secara automatik mengikut buku ini?', '["More than 1 year","More than 2 years","More than 5 years","More than 3 years"]'::jsonb, '["Melebihi 1 tahun","Melebihi 2 tahun","Melebihi 5 tahun","Melebihi 3 tahun"]'::jsonb, 3, 'The table lists cancellation once a competent licence has remained expired for more than three years.', 'Jadual menyenaraikan pembatalan apabila lesen kompeten telah tamat tempoh melebihi tiga tahun.', NULL, 'KPP Kelas DA Automatik, PDF 25'),
  ('2fc35aef-0cbf-5085-ac34-fe669a226b23'::uuid, 'safety-principles', 'quiz-c-d-2', 12, 'How far should you press the clutch before changing gear?', 'Sejauh manakah pedal cekam perlu ditekan sebelum menukar gear?', '["All the way down","About halfway down","Just past the free play","Only to the biting point"]'::jsonb, '["Tekan sepenuhnya","Tekan kira-kira separuh","Tekan sedikit melepasi ruang bebas","Tekan hingga titik pergerakan"]'::jsonb, 0, 'Press the clutch all the way down before shifting, then release it to reconnect power.', 'Tekan cekam sepenuhnya sebelum menukar gear, kemudian lepaskan untuk menyambungkan kuasa semula.', NULL, 'KPP Kelas D Manual, PDF 215'),
  ('dd3ef893-5cfc-55a1-a8eb-5ed50ca701c1'::uuid, 'safety-principles', 'quiz-c-d-2', 13, 'How do you check that the gear lever is in Neutral before starting a manual car?', 'Bagaimanakah anda memastikan tombol gear dalam kedudukan bebas sebelum menghidupkan kereta manual?', '["Move it forward and back","Move it side to side","Push it toward first gear","Pull it toward reverse"]'::jsonb, '["Gerakkan ke depan dan belakang","Gerakkan ke kiri dan kanan","Tolak ke arah gear satu","Tarik ke arah gear undur"]'::jsonb, 1, 'In Neutral, the lever moves freely from side to side.', 'Dalam kedudukan bebas, tombol gear boleh bergerak dengan bebas ke kiri dan ke kanan.', NULL, 'KPP Kelas D Manual, PDF 200'),
  ('411409cc-ac49-5a1e-84df-2c6df832a02e'::uuid, 'safety-principles', 'quiz-c-d-2', 14, 'On the manual gear pattern shown in the curriculum, where is reverse from Neutral?', 'Dalam corak gear manual yang ditunjukkan, ke manakah tombol perlu digerakkan dari kedudukan bebas untuk memilih gear undur?', '["Fully right, then forward","Fully left, then back","Fully right, then back","Fully left, then forward"]'::jsonb, '["Kanan sepenuhnya, kemudian ke hadapan","Kiri sepenuhnya, kemudian ke belakang","Kanan sepenuhnya, kemudian ke belakang","Kiri sepenuhnya, kemudian ke hadapan"]'::jsonb, 2, 'For the illustrated gear pattern, press the clutch, move the lever fully right, then pull back.', 'Bagi corak gear dalam rajah, tekan cekam, gerakkan tombol sepenuhnya ke kanan, kemudian tarik ke belakang.', NULL, 'KPP Kelas D Manual, PDF 214'),
  ('fcf4adf9-c85d-5336-b379-90a786d85441'::uuid, 'safety-principles', 'quiz-c-d-2', 15, 'Which gear does the manual curriculum use to start moving forward from a standstill?', 'Gear manakah yang digunakan dalam kurikulum manual untuk mula bergerak ke hadapan dari keadaan berhenti?', '["Second gear","Third gear","Fourth gear","First gear"]'::jsonb, '["Gear dua","Gear tiga","Gear empat","Gear satu"]'::jsonb, 3, 'Select first gear before balancing the clutch and accelerator to move off.', 'Pilih gear satu sebelum mengimbangi cekam dan pemecut untuk mula bergerak.', NULL, 'KPP Kelas D Manual, PDF 216'),
  ('bf4e1555-926a-5741-aa09-fe70164f6dd8'::uuid, 'safety-principles', 'quiz-c-d-3', 1, 'Which licence follows the probationary licence in the curriculum’s licensing process?', 'Lesen manakah menyusuli lesen percubaan dalam proses pelesenan yang diterangkan?', '["Learner’s driving licence","Competent driving licence","Vocational driving licence","International driving permit"]'::jsonb, '["Lesen belajar memandu","Lesen memandu kompeten","Lesen memandu vokasional","Permit memandu antarabangsa"]'::jsonb, 1, 'Drivers who complete probation apply to change from a probationary to a competent driving licence.', 'Pemandu yang menamatkan tempoh percubaan memohon pertukaran daripada lesen percubaan kepada lesen kompeten.', NULL, 'KPP Kelas DA Automatik, PDF 22'),
  ('37f51327-d949-53d9-bf1c-346e75f1599a'::uuid, 'safety-principles', 'quiz-c-d-3', 2, 'Under this curriculum, what can a driver skip when adding a class from the same licence group?', 'Mengikut kurikulum ini, apakah yang boleh dikecualikan apabila menambah kelas daripada kumpulan lesen yang sama?', '["The practical training and tests","The practical tests only","The road training only","The theory course and test"]'::jsonb, '["Latihan dan ujian amali","Ujian amali sahaja","Latihan jalan raya sahaja","Kursus dan ujian teori"]'::jsonb, 3, 'The same-group exemption covers the KPP01 course and Part I theory test. Practical training and tests still apply.', 'Pengecualian bagi kumpulan yang sama meliputi kursus KPP01 dan ujian teori Bahagian I. Latihan dan ujian amali masih diperlukan.', NULL, 'KPP Kelas DA Automatik, PDF 14'),
  ('7bad7ac8-836a-5bb8-8a57-bbc78a58b573'::uuid, 'safety-principles', 'quiz-c-d-3', 3, 'Which licence category covers driving a bus with fare-paying passengers?', 'Kategori lesen manakah meliputi pemanduan bas yang membawa penumpang berbayar?', '["PSV","GDL","CDL alone","PDL alone"]'::jsonb, '["PSV","GDL","CDL sahaja","PDL sahaja"]'::jsonb, 0, 'PSV covers public service vehicles, including buses. GDL is for goods vehicles.', 'PSV meliputi kenderaan perkhidmatan awam termasuk bas. GDL ialah lesen untuk kenderaan barangan.', NULL, 'KPP Kelas DA Automatik, PDF 23'),
  ('01cbf84c-a04c-5f7e-bbf4-5b5f15240c92'::uuid, 'safety-principles', 'quiz-c-d-3', 4, 'Which specific vision check appears in the handbook’s eligibility requirements?', 'Pemeriksaan penglihatan khusus manakah dinyatakan dalam syarat kelayakan buku panduan?', '["Colour vision","Peripheral vision","Night vision","Depth perception"]'::jsonb, '["Penglihatan warna","Penglihatan sisi","Penglihatan malam","Persepsi kedalaman"]'::jsonb, 0, 'Eligibility includes being able to see ahead for 23 metres and not being colour blind.', 'Kelayakan termasuk boleh melihat ke hadapan sejauh 23 meter dan tidak buta warna.', NULL, 'KPP Kelas DA Automatik, PDF 11'),
  ('a418d181-ae9a-5506-80ac-40eb01f4eed6'::uuid, 'safety-principles', 'quiz-c-d-3', 5, 'What does the name KEJARA stand for?', 'Apakah nama penuh KEJARA?', '["Sistem Kelayakan Jalan Raya","Sistem Keselamatan Jalan Raya","Sistem Kesalahan Jalan Raya","Sistem Kawalan Jalan Raya"]'::jsonb, '["Sistem Kelayakan Jalan Raya","Sistem Keselamatan Jalan Raya","Sistem Kesalahan Jalan Raya","Sistem Kawalan Jalan Raya"]'::jsonb, 1, 'KEJARA is short for Sistem Keselamatan Jalan Raya. It assigns demerit points for scheduled offences.', 'KEJARA ialah singkatan bagi Sistem Keselamatan Jalan Raya. Sistem ini memberikan mata demerit bagi kesalahan terjadual.', NULL, 'KPP General, PDF 93'),
  ('6b09e828-9940-5fde-8859-d94a8b9d0013'::uuid, 'safety-principles', 'quiz-c-d-3', 6, 'What does this curriculum say happens to a P licence at 20 demerit points?', 'Apakah kesan 20 mata demerit pada lesen P mengikut kurikulum ini?', '["The licence is suspended","A warning is issued","The licence is cancelled","A course is required"]'::jsonb, '["Lesen digantung","Amaran dikeluarkan","Lesen dibatalkan","Kursus diwajibkan"]'::jsonb, 2, 'The P licence conditions state that reaching 20 points or more results in cancellation.', 'Syarat lesen P menyatakan bahawa 20 mata atau lebih mengakibatkan lesen dibatalkan.', NULL, 'KPP Kelas DA Automatik, PDF 20'),
  ('79c8a23d-76fc-5412-b3ff-85ef5fc6ce5d'::uuid, 'safety-principles', 'quiz-c-d-3', 7, 'What is the first action shown in the KEJARA schedule when a competent licence holder reaches 20 points?', 'Apakah tindakan pertama dalam jadual KEJARA apabila pemegang lesen kompeten mencapai 20 mata?', '["A suspension","A cancellation","A course referral","A warning"]'::jsonb, '["Penggantungan","Pembatalan","Rujukan kursus","Amaran"]'::jsonb, 3, 'The first threshold shown in the schedule results in a warning.', 'Ambang kali pertama dalam jadual ini membawa kepada amaran.', NULL, 'KPP General, PDF 95'),
  ('896ad58f-d6e5-5456-a45c-28cf062f40f7'::uuid, 'safety-principles', 'quiz-c-d-3', 8, 'A competent licence holder has already received one KEJARA warning and reaches another 20 points. What suspension range applies in the handbook table?', 'Pemegang lesen kompeten telah menerima satu amaran KEJARA dan mencapai 20 mata lagi. Apakah julat penggantungan dalam jadual buku panduan?', '["6–8 months","4–6 months","8–10 months","10–12 months"]'::jsonb, '["6–8 bulan","4–6 bulan","8–10 bulan","10–12 bulan"]'::jsonb, 0, 'The table shows a first suspension of six to eight months for the second threshold.', 'Jadual menunjukkan penggantungan pertama selama enam hingga lapan bulan bagi ambang kali kedua.', NULL, 'KPP General, PDF 95'),
  ('447f0a7e-3ccb-533a-912c-f6fde03a5115'::uuid, 'safety-principles', 'quiz-c-d-3', 9, 'A competent licence holder receives a second suspension under the handbook KEJARA schedule. Which range applies?', 'Pemegang lesen kompeten menerima penggantungan kali kedua mengikut jadual KEJARA. Apakah julatnya?', '["8–10 months","4–6 months","6–8 months","10–12 months"]'::jsonb, '["8–10 bulan","4–6 bulan","6–8 bulan","10–12 bulan"]'::jsonb, 0, 'The third threshold in the table can result in a suspension of eight to ten months.', 'Ambang kali ketiga dalam jadual boleh menyebabkan penggantungan lapan hingga sepuluh bulan.', NULL, 'KPP General, PDF 95'),
  ('4c2b11c1-d72e-5973-b6cd-0c183db41328'::uuid, 'safety-principles', 'quiz-c-d-3', 10, 'What action can follow three licence suspensions within five years?', 'Apakah tindakan yang boleh diambil selepas tiga penggantungan lesen dalam tempoh lima tahun?', '["An additional warning","A driving course referral","Licence cancellation","Automatic licence renewal"]'::jsonb, '["Amaran tambahan","Rujukan kursus memandu","Pembatalan lesen","Pembaharuan lesen automatik"]'::jsonb, 2, 'The KEJARA schedule describes cancellation action after three suspensions within five years.', 'Jadual KEJARA menerangkan tindakan pembatalan selepas tiga penggantungan dalam tempoh lima tahun.', NULL, 'KPP General, PDF 95'),
  ('b67eec19-9d94-5751-8c71-7489f91728fa'::uuid, 'safety-principles', 'quiz-c-d-3', 11, 'What reduction can be considered after 12 months without a scheduled offence?', 'Apakah pengurangan yang boleh dipertimbangkan selepas 12 bulan tanpa kesalahan terjadual?', '["Up to a quarter of the points","Half of the court fine","All points immediately","Up to half the points"]'::jsonb, '["Sehingga suku mata","Separuh denda mahkamah","Semua mata serta-merta","Sehingga separuh mata"]'::jsonb, 3, 'The schedule lists a possible deduction of up to half the accumulated demerit points.', 'Jadual menyenaraikan potongan sehingga separuh daripada mata demerit yang terkumpul.', NULL, 'KPP General, PDF 95'),
  ('302fae59-32e1-52fb-b688-03fc81398b25'::uuid, 'safety-principles', 'quiz-c-d-3', 12, 'In the illustrated gear pattern, how do you move from first to second?', 'Dalam corak gear yang ditunjukkan, bagaimanakah anda menukar dari gear satu ke gear dua?', '["Back through Neutral","Forward through Neutral","Right and then forward","Right and then back"]'::jsonb, '["Ke belakang melalui kedudukan bebas","Ke hadapan melalui kedudukan bebas","Ke kanan dan kemudian ke hadapan","Ke kanan dan kemudian ke belakang"]'::jsonb, 0, 'With the clutch fully pressed, move the lever back through Neutral into second.', 'Tekan cekam sepenuhnya, kemudian tarik tombol ke belakang melalui kedudukan bebas hingga gear dua.', NULL, 'KPP Kelas D Manual, PDF 213'),
  ('2e846637-b19f-54b6-855d-a90e1035d934'::uuid, 'safety-principles', 'quiz-c-d-3', 13, 'From second gear, what is the final lever movement after crossing to the third-gear gate?', 'Dari gear dua, apakah gerakan akhir tombol selepas masuk ke laluan gear tiga?', '["Pull the lever back","Push the lever forward","Push the lever left","Push the lever right"]'::jsonb, '["Tarik tombol ke belakang","Tolak tombol ke hadapan","Tolak tombol ke kiri","Tolak tombol ke kanan"]'::jsonb, 1, 'The illustrated second-to-third shift passes through Neutral and then goes forward into third.', 'Pertukaran yang ditunjukkan melalui kedudukan bebas sebelum tombol ditolak ke hadapan ke gear tiga.', NULL, 'KPP Kelas D Manual, PDF 213'),
  ('822a1ecc-0f75-50df-81e7-074da3a7ca7a'::uuid, 'safety-principles', 'quiz-c-d-3', 14, 'From third gear, which way does the lever move to select fourth on the illustrated pattern?', 'Dari gear tiga, ke arah manakah tombol perlu digerakkan untuk memilih gear empat dalam rajah?', '["Straight ahead through Neutral","Left and then back","Straight back through Neutral","Right and then back"]'::jsonb, '["Lurus ke hadapan melalui kedudukan bebas","Ke kiri dan kemudian ke belakang","Lurus ke belakang melalui kedudukan bebas","Ke kanan dan kemudian ke belakang"]'::jsonb, 2, 'Press the clutch fully and move the lever straight back through Neutral.', 'Tekan cekam sepenuhnya dan tarik tombol lurus ke belakang melalui kedudukan bebas.', NULL, 'KPP Kelas D Manual, PDF 214'),
  ('8c4ff22f-50f4-582f-a613-57711ec04a69'::uuid, 'safety-principles', 'quiz-c-d-3', 15, 'After reaching Neutral from fourth, where do you move the lever to select fifth on the illustrated pattern?', 'Selepas mencapai kedudukan bebas dari gear empat, ke manakah tombol perlu digerakkan untuk memilih gear lima dalam rajah?', '["Right, then back","Left, then forward","Left, then back","Right, then forward"]'::jsonb, '["Ke kanan, kemudian ke belakang","Ke kiri, kemudian ke hadapan","Ke kiri, kemudian ke belakang","Ke kanan, kemudian ke hadapan"]'::jsonb, 3, 'For the illustrated fourth-to-fifth shift, move from Neutral to the right and then forward.', 'Untuk pertukaran dari gear empat ke gear lima dalam rajah, gerakkan tombol ke kanan dari kedudukan bebas, kemudian ke hadapan.', NULL, 'KPP Kelas D Manual, PDF 214'),
  ('72f436e8-8ce2-5790-8293-f84f0878d49b'::uuid, 'road-signs', 'mock-da-1', 1, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Pass on the right","Pass on either side","Pass on the left","Keep left unless overtaking"]'::jsonb, '["Lalu di sebelah kanan","Lalu di mana-mana sisi","Lalu di sebelah kiri","Ikut kiri kecuali memotong"]'::jsonb, 2, 'This sign means pass on the left.', 'Papan tanda ini bermaksud lalu di sebelah kiri.', '/signs/24dc89f9e7127cca.svg', 'KPP General PDF page 64'),
  ('457b9f2e-28c6-5632-b3de-0b83b235014b'::uuid, 'road-signs', 'mock-da-1', 2, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Pass on the left","Pass on either side","Keep left unless overtaking","Pass on the right"]'::jsonb, '["Lalu di sebelah kiri","Lalu di mana-mana sisi","Ikut kiri kecuali memotong","Lalu di sebelah kanan"]'::jsonb, 3, 'This sign means pass on the right.', 'Papan tanda ini bermaksud lalu di sebelah kanan.', '/signs/a50c8dd8a202a25e.svg', 'KPP General PDF page 64'),
  ('3362b19b-acbb-5565-96a2-be61b5110e31'::uuid, 'road-signs', 'mock-da-1', 3, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Pass on either side","Pass on the right","Pass on the left","Keep left unless overtaking"]'::jsonb, '["Lalu di mana-mana sisi","Lalu di sebelah kanan","Lalu di sebelah kiri","Ikut kiri kecuali memotong"]'::jsonb, 0, 'This sign means pass on either side.', 'Papan tanda ini bermaksud lalu di mana-mana sisi.', '/signs/6103dff69316bf86.svg', 'KPP General PDF page 64'),
  ('7140cc39-2b91-5917-862a-af7307980087'::uuid, 'road-signs', 'mock-da-1', 5, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Lane for bicycles","Lane for trishaws","Lane for motorcycles","Lane for taxis"]'::jsonb, '["Lorong untuk basikal","Lorong untuk beca","Lorong untuk motosikal","Lorong untuk teksi"]'::jsonb, 2, 'This sign means lane for motorcycles.', 'Papan tanda ini bermaksud lorong untuk motosikal.', '/signs/e0389a069e72ed52.png', 'KPP General PDF page 65'),
  ('589043a9-cb01-5e06-ad09-8863faf7592b'::uuid, 'road-signs', 'mock-da-1', 6, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Lane for trishaws","Lane for motorcycles","Lane for taxis","Lane for bicycles"]'::jsonb, '["Lorong untuk beca","Lorong untuk motosikal","Lorong untuk teksi","Lorong untuk basikal"]'::jsonb, 3, 'This sign means lane for bicycles.', 'Papan tanda ini bermaksud lorong untuk basikal.', '/signs/e86785fec1877d75.png', 'KPP General PDF page 65'),
  ('8b82dacb-52e8-51b4-9772-a7206da63d6b'::uuid, 'road-signs', 'mock-da-1', 7, 'What does this sign prohibit?', 'Apakah larangan pada papan tanda ini?', '["No overtaking","No stopping","No left turn","No right turn"]'::jsonb, '["Dilarang memotong","Dilarang berhenti","Dilarang membelok ke kiri","Dilarang membelok ke kanan"]'::jsonb, 0, 'This sign means no overtaking.', 'Papan tanda ini bermaksud dilarang memotong.', '/signs/2f019822b1b9e39f.svg', 'KPP General PDF page 57'),
  ('f9101314-8799-5c17-be42-5b6b2732ab35'::uuid, 'road-signs', 'mock-da-1', 8, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Lane for bicycles","Lane for trishaws","Lane for buses","Lane for taxis"]'::jsonb, '["Lorong untuk basikal","Lorong untuk beca","Lorong untuk bas","Lorong untuk teksi"]'::jsonb, 1, 'This sign means lane for trishaws.', 'Papan tanda ini bermaksud lorong untuk beca.', '/signs/fad437bbc08b75fa.png', 'KPP General PDF page 65'),
  ('99496ca9-846c-55e7-96b7-5e6bbc3ff2f8'::uuid, 'road-signs', 'mock-da-1', 13, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Medical clinic","Public telephone","Hospital","Bus stop"]'::jsonb, '["Klinik perubatan","Telefon awam","Hospital","Perhentian bas"]'::jsonb, 2, 'This sign means hospital.', 'Papan tanda ini bermaksud hospital.', '/signs/dde5874c6044c5f3.svg', 'KPP General PDF page 67'),
  ('4a0ff7b4-b7cb-5bf5-a954-d84f58e550ac'::uuid, 'road-signs', 'mock-da-1', 15, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Vehicle parking","Medical clinic","JPJ weighing station","Public telephone"]'::jsonb, '["Tempat letak kenderaan","Klinik perubatan","Stesen timbang JPJ","Telefon awam"]'::jsonb, 0, 'This sign means vehicle parking.', 'Papan tanda ini bermaksud tempat letak kenderaan.', '/signs/f6459f68e216bc5d.svg', 'KPP General PDF page 67'),
  ('5832477f-e6e2-5f39-ae29-e588176b5042'::uuid, 'traffic-rules', 'mock-da-1', 16, 'Someone offers to guarantee your test result for a private payment. What should you do?', 'Seseorang menawarkan keputusan ujian terjamin dengan bayaran peribadi. Apakah tindakan anda?', '["Decline and use the official process","Ask whether the offer is genuine","Accept if the fee is refundable","Ask your instructor to arrange it"]'::jsonb, '["Tolak dan ikut proses rasmi","Tanya sama ada tawaran itu sahih","Terima jika bayaran boleh dipulangkan","Minta pengajar menguruskannya"]'::jsonb, 0, 'Candidates must deal honestly with the driving institute and JPJ. Never offer a reward in exchange for a guaranteed pass.', 'Calon mesti berurusan secara jujur dengan institut memandu dan JPJ. Jangan tawarkan ganjaran sebagai pertukaran untuk jaminan lulus.', NULL, 'Kurikulum Pendidikan Pemandu, PDF page 100'),
  ('9d290037-546b-549e-ab38-493b75afd0c6'::uuid, 'traffic-rules', 'mock-da-1', 17, 'Where is another car likely to be hidden in your blind spot?', 'Di manakah kereta lain mungkin terlindung dalam titik buta anda?', '["Alongside near a rear corner","Directly behind your rear window","Directly in front of your bonnet","Well ahead in the next lane"]'::jsonb, '["Di sisi berhampiran penjuru belakang","Tepat di belakang cermin belakang","Tepat di hadapan bonet","Jauh di hadapan di lorong sebelah"]'::jsonb, 0, 'A vehicle beside a rear quarter can be outside the view of the side and rear-view mirrors.', 'Kenderaan di sisi bahagian belakang mungkin berada di luar pandangan cermin sisi dan cermin pandang belakang.', NULL, 'KPP Kelas D Automatik, PDF page 98'),
  ('db220d5a-36b4-572f-80f5-6f2935fe7df9'::uuid, 'traffic-rules', 'mock-da-1', 18, 'You have passed a loaded lorry. What gap should you leave before moving in front of it?', 'Anda baru memotong lori bermuatan. Berapakah ruang yang patut ditinggalkan sebelum masuk ke hadapannya?', '["Only enough to clear its bumper","Just enough if you maintain speed","Only enough if the road is dry","Enough for the lorry to stop safely"]'::jsonb, '["Sekadar melepasi bampar lori","Sekadar cukup jika kelajuan dikekalkan","Sekadar cukup jika jalan kering","Cukup untuk lori berhenti"]'::jsonb, 3, 'A heavy vehicle needs a longer distance to stop. Avoid moving sharply into its path after passing.', 'Kenderaan berat memerlukan jarak berhenti lebih panjang. Elakkan masuk secara tiba-tiba ke laluannya selepas memotong.', NULL, 'KPP Kelas D Automatik, PDF page 88'),
  ('22d06bda-9918-588d-8fe1-8d943f77d949'::uuid, 'traffic-rules', 'mock-da-1', 19, 'Why should you avoid an unnecessary horn blast beside a motorcyclist?', 'Mengapa anda patut mengelakkan bunyi hon yang tidak perlu di sisi penunggang motosikal?', '["It could startle the rider into swerving","It could make the rider slow gradually","It could make the rider check the mirror","It could make the rider hold a steady line"]'::jsonb, '["Penunggang mungkin terkejut dan melencong","Penunggang mungkin memperlahankan motosikal","Penunggang mungkin memeriksa cermin","Penunggang mungkin mengekalkan laluan"]'::jsonb, 0, 'A sudden horn can startle a rider and cause them to stray from their lane. Sound it only when needed.', 'Bunyi hon secara tiba-tiba boleh mengejutkan penunggang dan menyebabkan mereka terkeluar dari lorong. Bunyikan hon hanya apabila perlu.', NULL, 'KPP Kelas D Automatik, PDF page 85'),
  ('c1cd9b6c-ae1d-5971-8dea-0c46edb2363c'::uuid, 'traffic-rules', 'mock-da-1', 20, 'Which hand signal shows that a driver intends to turn right?', 'Isyarat tangan manakah menunjukkan bahawa pemandu hendak membelok ke kanan?', '["Hold the right arm vertically","Move the right arm in a circle","Extend the right arm horizontally","Wave the right arm up and down"]'::jsonb, '["Tegakkan lengan kanan","Gerakkan lengan kanan secara membulat","Luruskan lengan kanan secara mendatar","Gerakkan lengan kanan ke atas dan ke bawah"]'::jsonb, 2, 'A straight, horizontal right arm indicates a right turn.', 'Lengan kanan yang lurus dan mendatar menandakan belok kanan.', NULL, 'KPP Kelas D Automatik, PDF page 75'),
  ('2862fc3c-1493-56cf-92d7-0e199f8790bf'::uuid, 'traffic-rules', 'mock-da-1', 21, 'The driver ahead raises their right hand upright outside the window and holds it still. What are they signalling?', 'Pemandu di hadapan menegakkan tangan kanan di luar tingkap tanpa menggerakkannya. Apakah isyarat itu?', '["Turning left","Slowing down","Turning right","Stopping"]'::jsonb, '["Belok kiri","Perlahankan kenderaan","Belok kanan","Berhenti"]'::jsonb, 3, 'The upright hand signals a stop. Leave enough space to respond.', 'Tangan yang ditegakkan menandakan berhenti. Tinggalkan ruang yang cukup untuk bertindak.', NULL, 'KPP Kelas D Automatik, PDF page 75'),
  ('5e23a289-9d77-54bb-a7f7-f077db656d1b'::uuid, 'traffic-rules', 'mock-da-1', 22, 'The driver ahead is moving their right arm in a circle outside the window. What does that signal mean?', 'Pemandu di hadapan menggerakkan lengan kanan secara membulat di luar tingkap. Apakah maksud isyarat itu?', '["Slowing down","Turning left","Stopping","Turning right"]'::jsonb, '["Perlahankan kenderaan","Belok kiri","Berhenti","Belok kanan"]'::jsonb, 1, 'A circular movement of the right arm indicates a left turn.', 'Gerakan membulat lengan kanan menandakan belok kiri.', NULL, 'KPP Kelas D Automatik, PDF page 75'),
  ('cff38980-d8bb-563c-bef1-47c78b0ced5e'::uuid, 'traffic-rules', 'mock-da-1', 23, 'A traffic officer faces you, extends their right arm straight out to their right and bends their left arm across their chest. Where can you go?', 'Polis trafik menghadap anda, meluruskan lengan kanannya ke sebelah kanannya dan membengkokkan lengan kiri di hadapan dada. Ke manakah anda boleh bergerak?', '["Straight through","Left at the junction","Right at the junction","Wait at the line"]'::jsonb, '["Terus melalui persimpangan","Belok kiri di persimpangan","Belok kanan di persimpangan","Tunggu di garisan"]'::jsonb, 2, 'For this signal, traffic approaching the officer from the front can turn right. Traffic behind the officer stops.', 'Dengan isyarat ini, trafik yang menghadap anggota polis boleh membelok ke kanan. Trafik di belakang anggota polis mesti berhenti.', NULL, 'KPP Kelas D Automatik, PDF page 74'),
  ('20f06aa3-9990-5146-8b6f-b845a348ef0b'::uuid, 'traffic-rules', 'mock-da-1', 24, 'A traffic officer holds both forearms upright and beckons with both hands. Which traffic may go?', 'Polis trafik menegakkan kedua-dua lengan bawah dan melambai dengan kedua-dua tangan. Trafik manakah boleh bergerak?', '["From the front and rear","From the left and right","From the front only","From the rear only"]'::jsonb, '["Dari hadapan dan belakang","Dari kiri dan kanan","Dari hadapan sahaja","Dari belakang sahaja"]'::jsonb, 1, 'This signal allows traffic on both sides of the officer to proceed.', 'Isyarat ini membenarkan trafik di kedua-dua sisi anggota polis meneruskan perjalanan.', NULL, 'KPP Kelas D Automatik, PDF page 74'),
  ('cd59a93f-09bf-5df2-9f6a-84217bb38328'::uuid, 'traffic-rules', 'mock-da-1', 25, 'When should you finish adjusting your speed for an S-bend?', 'Bilakah anda perlu selesai melaraskan kelajuan untuk selekoh S?', '["Just after entering the bend","Between the two curves","Before entering the bend","Just before leaving the bend"]'::jsonb, '["Sejurus selepas masuk selekoh","Antara dua lengkungan","Sebelum masuk selekoh","Sejurus sebelum keluar selekoh"]'::jsonb, 2, 'Enter slowly and hold a steady speed through the curves. Avoid changing gear or braking in the bend.', 'Masuk perlahan-lahan dan kekalkan kelajuan sepanjang selekoh. Elakkan menukar gear atau membrek di dalam selekoh.', NULL, 'KPP Kelas D Automatik, PDF page 249'),
  ('45e4e29f-3df5-527c-bb39-b8c305fc4fdb'::uuid, 'traffic-rules', 'mock-da-1', 26, 'At the first turn of a tight Z-bend, how should your hands move on the steering wheel?', 'Pada belokan pertama dalam selekoh Z yang sempit, bagaimana tangan patut bergerak pada stereng?', '["One hand pulls while the other slides","Both hands pull down together","One hand holds while the other crosses over","Both hands let the wheel slide freely"]'::jsonb, '["Sebelah tangan menarik sementara yang lain melurut","Kedua-dua tangan menarik ke bawah serentak","Sebelah tangan memegang sementara yang lain menyilang","Kedua-dua tangan membiarkan stereng melurut bebas"]'::jsonb, 0, 'Use controlled push-and-pull movements to steer continuously through the narrow path.', 'Gunakan teknik tarik dan tolak secara terkawal untuk memandu secara berterusan di laluan sempit.', NULL, 'KPP Kelas D Automatik, PDF page 250'),
  ('959a93cf-35ac-58b9-9af0-b61e3b72d61a'::uuid, 'traffic-rules', 'mock-da-1', 27, 'What is the time limit for the three-point turn in the Class DA circuit test?', 'Berapakah had masa pusingan tiga penjuru dalam ujian litar Kelas DA?', '["2 minutes","4 minutes","5 minutes","3 minutes"]'::jsonb, '["2 minit","4 minit","5 minit","3 minit"]'::jsonb, 3, 'Complete the forward, reverse and final forward moves within three minutes.', 'Selesaikan gerakan ke hadapan, mengundur dan ke hadapan semula dalam masa tiga minit.', NULL, 'KPP Kelas D Automatik, PDF page 280'),
  ('c39a839c-ea7b-59c8-99fb-f089f74b7462'::uuid, 'traffic-rules', 'mock-da-1', 28, 'What is the time limit for side parking in the Class DA circuit test?', 'Berapakah had masa parkir sisi dalam ujian litar Kelas DA?', '["4 minutes","5 minutes","3 minutes","6 minutes"]'::jsonb, '["4 minit","5 minit","3 minit","6 minit"]'::jsonb, 1, 'You have five minutes to complete the manoeuvre, including leaving the bay.', 'Anda mempunyai lima minit untuk melengkapkan olah gerak, termasuk keluar dari petak.', NULL, 'KPP Kelas D Automatik, PDF page 278'),
  ('0129d3b0-0b71-524b-9bba-7acc2c99ecf0'::uuid, 'traffic-rules', 'mock-da-1', 29, 'An injured person is conscious and asks for a drink. Which action follows the handbook guidance?', 'Mangsa yang sedar meminta minuman. Tindakan manakah mengikut panduan buku?', '["Ask them to wait for medical help","Offer water if there is no visible injury","Give water after they sit up","Offer water if the trip to hospital is long"]'::jsonb, '["Minta mangsa menunggu bantuan perubatan","Beri air jika tiada kecederaan kelihatan","Beri air selepas mangsa duduk","Beri air jika perjalanan ke hospital panjang"]'::jsonb, 0, 'Do not give a road-crash casualty food or drink at the scene.', 'Jangan beri makanan atau minuman kepada mangsa kemalangan di tempat kejadian.', NULL, 'Kurikulum Pendidikan Pemandu, PDF page 200'),
  ('0d685c4a-9d18-5541-adda-013f2f7a2975'::uuid, 'traffic-rules', 'mock-da-1', 30, 'After a crash, you can take photographs safely. What should you capture first?', 'Selepas kemalangan, anda boleh mengambil gambar dengan selamat. Apakah yang patut dirakam terlebih dahulu?', '["Vehicle interiors and belongings","The nearest service station","The damage and marks on the road","The other driver’s route home"]'::jsonb, '["Ruang dalam kenderaan dan barang peribadi","Stesen minyak yang terdekat","Kerosakan dan kesan di jalan","Laluan pulang pemandu lain"]'::jsonb, 2, 'Photograph the scene, vehicle damage and any road marks that may help explain what happened.', 'Ambil gambar tempat kejadian, kerosakan kenderaan dan sebarang kesan di jalan yang boleh membantu menjelaskan kejadian.', NULL, 'Kurikulum Pendidikan Pemandu, PDF page 200'),
  ('5cd7c884-6e6c-545f-bf57-3a635040f215'::uuid, 'traffic-rules', 'mock-da-1', 31, 'After a crash with serious property damage, whom should you contact to make a formal accident report?', 'Selepas kemalangan yang menyebabkan kerosakan harta benda yang serius, kepada siapakah laporan rasmi kemalangan patut dibuat?', '["Your insurer","The police","The local council","Your towing company"]'::jsonb, '["Syarikat insurans","Pihak polis","Pihak berkuasa tempatan","Syarikat tunda"]'::jsonb, 1, 'Report the collision to the police, especially when there are injuries or serious damage. Insurance notifications are separate.', 'Laporkan kemalangan kepada polis, terutama jika terdapat kecederaan atau kerosakan serius. Makluman kepada syarikat insurans dibuat secara berasingan.', NULL, 'Kurikulum Pendidikan Pemandu, PDF page 199'),
  ('698910af-1f11-5609-bf89-6364b04cf5ef'::uuid, 'traffic-rules', 'mock-da-1', 32, 'You find someone seriously injured in a road crash. Which service should you request first?', 'Anda menjumpai seseorang yang cedera parah dalam kemalangan jalan raya. Perkhidmatan manakah yang perlu diminta dahulu?', '["An ambulance","A tow truck","A highway maintenance crew","An insurance assessor"]'::jsonb, '["Ambulans","Trak tunda","Pasukan penyelenggaraan lebuh raya","Penilai insurans"]'::jsonb, 0, 'Call for urgent medical assistance if someone is seriously injured.', 'Hubungi perkhidmatan perubatan kecemasan jika ada orang yang cedera parah.', NULL, 'Kurikulum Pendidikan Pemandu, PDF page 199'),
  ('37e786aa-415e-5517-aabb-9086f496c507'::uuid, 'traffic-rules', 'mock-da-1', 33, 'You pass parked cars in a housing estate. Which situation calls for more room and a lower speed?', 'Anda melalui kereta yang diletakkan di kawasan perumahan. Keadaan manakah memerlukan ruang tambahan dan kelajuan lebih rendah?', '["Children playing near the parked cars","A resident watering a garden behind a fence","A car parked fully inside a driveway","People waiting inside a building"]'::jsonb, '["Kanak-kanak bermain berhampiran kereta","Penduduk menyiram kebun di sebalik pagar","Kereta diletakkan sepenuhnya di laluan masuk","Orang menunggu di dalam bangunan"]'::jsonb, 0, 'Children can suddenly enter the road in residential areas. Drive at a speed that gives you time to react.', 'Kanak-kanak boleh tiba-tiba memasuki jalan di kawasan perumahan. Pandu pada kelajuan yang memberi anda masa untuk bertindak.', NULL, 'KPP Kelas D Automatik, PDF page 82'),
  ('546f6c1f-858f-50fe-8138-392791478485'::uuid, 'traffic-rules', 'mock-da-1', 34, 'Rain reduces visibility near a pedestrian crossing. What extra risk should you expect?', 'Hujan mengurangkan jarak penglihatan berhampiran lintasan pejalan kaki. Apakah risiko tambahan yang perlu dijangkakan?', '["Pedestrians may wait longer to cross","Pedestrians may hurry across the road","Pedestrians may stand further from the road","Pedestrians may make more eye contact"]'::jsonb, '["Pejalan kaki mungkin menunggu lebih lama","Pejalan kaki mungkin tergesa-gesa melintas","Pejalan kaki mungkin berdiri lebih jauh dari jalan","Pejalan kaki mungkin lebih kerap memandang pemandu"]'::jsonb, 1, 'In bad weather, pedestrians may hurry and pay less attention while drivers also see less clearly.', 'Dalam cuaca buruk, pejalan kaki mungkin tergesa-gesa dan kurang memberi perhatian, manakala pandangan pemandu turut terjejas.', NULL, 'KPP Kelas D Automatik, PDF page 83'),
  ('5ad528fa-9f3a-5a83-b726-15439285f83a'::uuid, 'traffic-rules', 'mock-da-1', 35, 'Another driver cuts in front of you. What is a patient response?', 'Pemandu lain masuk secara tiba-tiba di hadapan anda. Apakah tindak balas yang sabar?', '["Close up to discourage another merge","Pass at the first available opening","Ease off and restore your following gap","Keep your speed to hold your position"]'::jsonb, '["Rapatkan jarak supaya kenderaan lain tidak masuk","Potong sebaik sahaja ada ruang","Perlahankan dan pulihkan jarak mengekori","Kekalkan kelajuan untuk mempertahankan kedudukan"]'::jsonb, 2, 'Stay calm and avoid letting someone else’s mistake dictate how you drive. Restore space to react.', 'Bertenang dan jangan biarkan kesilapan orang lain mempengaruhi cara anda memandu. Pulihkan ruang untuk bertindak.', NULL, 'KPP Kelas D Automatik, PDF page 78'),
  ('694dcb92-3111-5a2d-af92-ca460e50f005'::uuid, 'traffic-rules', 'mock-da-1', 36, 'Your phone shows a new message while you are driving. When should you read it?', 'Telefon anda menunjukkan mesej baharu semasa anda memandu. Bilakah anda patut membacanya?', '["While traffic is moving slowly","When you are safely parked","When the lane ahead is clear","While rolling up to a red light"]'::jsonb, '["Semasa trafik bergerak perlahan","Apabila anda sudah parkir dengan selamat","Apabila lorong di hadapan lapang","Semasa bergerak menghampiri lampu merah"]'::jsonb, 1, 'Reading a phone takes attention away from the road. Wait until the car is safely parked.', 'Membaca telefon mengalihkan tumpuan daripada jalan. Tunggu sehingga kereta diparkir dengan selamat.', NULL, 'KPP Kelas D Automatik, PDF page 78'),
  ('dacf6275-fd9d-508a-b703-403f01f64033'::uuid, 'traffic-rules', 'mock-da-1', 37, 'You are struggling to stay awake before a planned drive. What should you do?', 'Anda sukar berjaga sebelum perjalanan yang dirancang. Apakah tindakan anda?', '["Drive with a window open","Start and stop if you feel worse","Let a rested driver take over","Take a slower route and continue"]'::jsonb, '["Pandu dengan tingkap terbuka","Mula memandu dan berhenti jika semakin letih","Minta pemandu yang cukup rehat mengambil alih","Pilih laluan lebih perlahan dan teruskan"]'::jsonb, 2, 'Do not start driving when sleepy or tired. Fatigue can impair your ability to drive safely.', 'Jangan mula memandu apabila mengantuk atau letih. Keletihan boleh menjejaskan keupayaan memandu dengan selamat.', NULL, 'KPP Kelas D Automatik, PDF page 119'),
  ('9e212abc-94d3-5ecb-8ac7-e69823c47dea'::uuid, 'traffic-rules', 'mock-da-1', 38, 'Your brake lights fail during a pre-drive check. What is the best response?', 'Lampu brek anda tidak berfungsi semasa pemeriksaan sebelum memandu. Apakah tindakan terbaik?', '["Continue using your hazard lights","Drive more slowly than usual","Wait until daylight to drive","Have the lights repaired first"]'::jsonb, '["Teruskan dengan lampu amaran kecemasan","Pandu lebih perlahan daripada biasa","Tunggu sehingga siang untuk memandu","Baiki lampu sebelum memandu"]'::jsonb, 3, 'Brake lights need to work so following drivers can tell when you are braking.', 'Lampu brek mesti berfungsi supaya pemandu di belakang tahu apabila anda membrek.', NULL, 'KPP Kelas D Automatik, PDF page 120'),
  ('5c94562b-06e4-5da3-875c-2b58d3e24bbd'::uuid, 'traffic-rules', 'mock-da-1', 39, 'On a two-way road, another driver starts passing you. What should you do?', 'Di jalan dua hala, pemandu lain mula memotong anda. Apakah tindakan anda?', '["Keep left and avoid speeding up","Keep left and speed up briefly","Move right and hold your speed","Move right and slow down"]'::jsonb, '["Kekal di kiri tanpa memecut","Kekal di kiri dan tambah kelajuan seketika","Bergerak ke kanan dan kekalkan kelajuan","Bergerak ke kanan dan perlahankan kenderaan"]'::jsonb, 0, 'Cooperate with the driver passing you. Keep to the left and leave space for them to finish passing.', 'Beri kerjasama kepada pemandu yang memotong. Kekal di sebelah kiri dan tinggalkan ruang untuk mereka selesai memotong.', NULL, 'KPP Kelas D Automatik, PDF page 124'),
  ('ae6beb0d-10bc-55cb-9711-8a8f4e2a3373'::uuid, 'traffic-rules', 'mock-da-1', 40, 'When making a left turn, when should you begin to accelerate back to a safe road speed?', 'Ketika membelok ke kiri, bilakah anda patut mula menambah kelajuan semula ke kelajuan yang selamat?', '["Before slowing for the junction","As soon as you signal","Once clear of the hazard","As you enter the turn"]'::jsonb, '["Sebelum memperlahankan kenderaan untuk simpang","Sebaik sahaja memberi isyarat","Selepas melepasi halangan","Semasa mula membelok"]'::jsonb, 2, 'Set a suitable speed before the turn. Accelerate smoothly once you have cleared the hazard.', 'Tetapkan kelajuan yang sesuai sebelum membelok. Tambah kelajuan secara lancar selepas melepasi halangan.', NULL, 'KPP Kelas D Automatik, PDF page 111'),
  ('44e6f150-60c3-5343-98a7-fd65528211d8'::uuid, 'safety-principles', 'mock-da-1', 41, 'Which licence does the curriculum require for ordinary GDL or PSV applications?', 'Lesen manakah diperlukan untuk permohonan GDL atau PSV biasa mengikut kurikulum ini?', '["A learner driving licence","A competent driving licence","A probationary driving licence","An international driving permit"]'::jsonb, '["Lesen belajar memandu","Lesen memandu kompeten","Lesen memandu percubaan","Permit memandu antarabangsa"]'::jsonb, 1, 'The vocational application requirements list a competent driving licence. The probationary licence exception is for Class C only.', 'Syarat permohonan lesen vokasional menyenaraikan lesen memandu kompeten. Pengecualian untuk lesen percubaan hanya bagi Kelas C.', NULL, 'KPP Kelas DA Automatik, PDF 23'),
  ('30ce4e8f-383e-5add-ad51-abb20b09cfa6'::uuid, 'safety-principles', 'mock-da-1', 42, 'A PSV bus applicant has completed the course and wants to book the practical test. Which result is needed first?', 'Pemohon PSV bas telah mengikuti kursus dan ingin menempah ujian amali. Keputusan manakah diperlukan dahulu?', '["A pass in vocational theory","A pass in the motorcar theory test alone","A pass in the ordinary road test","A pass in a driving institute trial run"]'::jsonb, '["Lulus ujian teori vokasional","Lulus ujian teori motokar sahaja","Lulus ujian jalan raya biasa","Lulus percubaan di institut memandu"]'::jsonb, 0, 'Vocational practical tests take place after a theory pass. PSV bus applicants are one of the groups required to take a practical test.', 'Ujian amali lesen vokasional dijalankan selepas lulus ujian teori. Pemohon PSV bas ialah antara kumpulan yang perlu menjalani ujian amali.', NULL, 'KPP Kelas DA Automatik, PDF 24'),
  ('26436b1a-a5d0-5490-b57f-30bdc7cdeaf0'::uuid, 'safety-principles', 'mock-da-1', 43, 'What does this curriculum say happens to a vocational licence that stays expired for over three years?', 'Apakah yang berlaku kepada lesen vokasional yang tamat tempoh melebihi tiga tahun mengikut kurikulum ini?', '["It is put on probation","It is suspended for a year","It is renewed for a year","It is cancelled"]'::jsonb, '["Lesen diletak dalam percubaan","Lesen digantung setahun","Lesen diperbaharui setahun","Lesen dibatalkan"]'::jsonb, 3, 'The curriculum lists automatic cancellation for a vocational licence that has been expired for more than three years.', 'Kurikulum menyenaraikan pembatalan automatik bagi lesen vokasional yang tamat tempoh melebihi tiga tahun.', NULL, 'KPP Kelas DA Automatik, PDF 25'),
  ('52ed5523-1be9-53da-bad5-b6b6cf67ab5c'::uuid, 'safety-principles', 'mock-da-1', 44, 'Which part of the driving test assesses practical driving on public roads?', 'Bahagian ujian memandu manakah menilai pemanduan amali di jalan raya?', '["Part III","Part II","Part I","The theory course"]'::jsonb, '["Bahagian III","Bahagian II","Bahagian I","Kursus teori"]'::jsonb, 0, 'Part II tests circuit skills. Part III tests applying safe driving skills on the road.', 'Bahagian II menguji kemahiran di litar. Bahagian III menguji amalan pemanduan selamat di jalan raya.', NULL, 'KPP Kelas DA Automatik, PDF 15'),
  ('d6181835-3bbb-5680-bf10-a64a88a4c7e6'::uuid, 'safety-principles', 'mock-da-1', 45, 'How long must a candidate wait after failing the circuit and road practical tests before retesting, according to this curriculum?', 'Berapa lamakah calon perlu menunggu selepas gagal ujian amali litar dan jalan raya sebelum mengulang ujian mengikut kurikulum ini?', '["One day","One week","Two weeks","One month"]'::jsonb, '["Satu hari","Satu minggu","Dua minggu","Satu bulan"]'::jsonb, 1, 'The book lists a one-week wait after failing the practical driving test before a candidate can retest.', 'Buku menetapkan tempoh menunggu seminggu selepas gagal ujian amali sebelum calon boleh mengulang ujian.', NULL, 'KPP Kelas DA Automatik, PDF 17'),
  ('ec17e0ac-1883-5857-9b33-718ff011b257'::uuid, 'safety-principles', 'mock-da-1', 46, 'Which form records the training the institute confirms for a practical test booking?', 'Borang manakah merekodkan latihan yang disahkan oleh institut untuk tempahan ujian amali?', '["SM4","A copy of the LDL","The theory test result sheet","The practical test booking slip"]'::jsonb, '["SM4","Salinan LDL","Slip keputusan ujian teori","Slip tempahan ujian amali"]'::jsonb, 0, 'The booking requirements include a copy of the learner licence and the SM4 driving training record.', 'Syarat tempahan termasuk salinan lesen belajar memandu dan rekod latihan memandu SM4.', NULL, 'KPP Kelas DA Automatik, PDF 16'),
  ('0c07b70f-dc0e-5883-869b-e65753cfebb6'::uuid, 'safety-principles', 'mock-da-1', 47, 'Where does a licence applicant with a disability obtain the medical verification specified in the handbook?', 'Di manakah pemohon lesen yang mempunyai ketidakupayaan mendapatkan pengesahan kesihatan yang dinyatakan dalam buku panduan?', '["A government clinic","The driving institute","A JPJ testing centre","An optical shop"]'::jsonb, '["Klinik kerajaan","Institut memandu","Pusat ujian JPJ","Kedai optik"]'::jsonb, 0, 'The curriculum requires medical verification by a medical officer at a government health clinic.', 'Kurikulum memerlukan pengesahan oleh pegawai perubatan di klinik kesihatan kerajaan.', NULL, 'KPP Kelas DA Automatik, PDF 11'),
  ('5af1d9ea-5584-5502-a87e-1c65153eab9d'::uuid, 'safety-principles', 'mock-da-1', 48, 'When are demerit points counted for a scheduled offence?', 'Bilakah mata demerit dikira bagi kesalahan terjadual?', '["When the summons is issued","After payment of the penalty","When the licence is renewed","When a hearing is scheduled"]'::jsonb, '["Apabila saman dikeluarkan","Selepas penalti dibayar","Apabila lesen diperbaharui","Apabila perbicaraan dijadualkan"]'::jsonb, 1, 'The curriculum ties demerit points to a scheduled offence after the compound payment or court fine has been paid.', 'Kurikulum mengaitkan mata demerit bagi kesalahan terjadual dengan pembayaran kompaun atau denda mahkamah.', NULL, 'KPP General, PDF 93'),
  ('0c1e0d35-f73f-5e8a-af02-92b3c1b14a3d'::uuid, 'safety-principles', 'mock-da-1', 49, 'What is one use of selector position 3 on the automatic car in this curriculum?', 'Apakah satu kegunaan kedudukan gear 3 dalam kereta automatik yang diterangkan?', '["Starting in Neutral","Controlling speed downhill","Reversing into a space","Securing the parked car"]'::jsonb, '["Menghidupkan enjin dalam N","Mengawal kelajuan menuruni bukit","Mengundur ke petak parkir","Menahan kereta yang diparkir"]'::jsonb, 1, 'Selector position 3 allows the first three gears. It can be used on descents or when more power is needed for overtaking or climbing.', 'Kedudukan 3 membenarkan tiga gear pertama. Ia boleh digunakan ketika menuruni bukit atau apabila memerlukan lebih kuasa untuk memotong atau mendaki.', NULL, 'KPP Kelas DA Automatik, PDF 212'),
  ('ffe190a5-61ab-53b9-909a-9ad9c5dc8a28'::uuid, 'safety-principles', 'mock-da-1', 50, 'What distinguishes the vehicle covered by Class DA in the classification table?', 'Apakah yang membezakan kenderaan Kelas DA dalam jadual pengelasan?', '["It has a manual clutch pedal","It has a hand-operated clutch","It has no clutch pedal","It has a separate low-range lever"]'::jsonb, '["Ada pedal cekam manual","Ada cekam kendalian tangan","Tiada pedal cekam","Ada tuil julat rendah berasingan"]'::jsonb, 2, 'The table lists Class DA for cars without a clutch pedal and with an unladen weight of no more than 3,500 kg.', 'Jadual menyenaraikan Kelas DA bagi motokar tanpa pedal cekam dengan berat tanpa muatan tidak melebihi 3,500 kg.', NULL, 'KPP Kelas DA Automatik, PDF 10'),
  ('aec53c70-e504-581e-ba99-f2f81faa6db8'::uuid, 'road-signs', 'mock-da-2', 3, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Distance to a destination exit","Directions at a junction ahead","Distances to upcoming destinations","Road with no through access"]'::jsonb, '["Jarak ke susur keluar destinasi","Arah di simpang yang akan datang","Jarak ke destinasi seterusnya","Jalan buntu di hadapan"]'::jsonb, 3, 'This sign means road with no through access. The road does not continue through to another route.', 'Papan tanda ini bermaksud jalan buntu di hadapan. Jalan itu tidak bersambung dengan laluan lain.', '/signs/082877f6ec086be6.svg', 'KPP General PDF page 68'),
  ('57fd195f-efed-5274-98c3-85808e9e1940'::uuid, 'road-signs', 'mock-da-2', 4, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Designated U-turn","Designated P-turn","Road with no through access","Directions at a junction ahead"]'::jsonb, '["Tempat pusingan U","Tempat pusingan P","Jalan buntu di hadapan","Arah di simpang yang akan datang"]'::jsonb, 0, 'This sign means designated U-turn. It marks a place to turn around. Give way to oncoming traffic before turning.', 'Papan tanda ini bermaksud tempat pusingan U. Tanda ini menunjukkan tempat untuk berpatah balik. Beri laluan kepada trafik dari arah bertentangan sebelum membelok.', '/signs/8956fe8a103938b3.svg', 'KPP General PDF page 69'),
  ('0d14bacd-9417-5caa-b4ca-5d5a86343864'::uuid, 'road-signs', 'mock-da-2', 8, 'What does this sign prohibit?', 'Apakah larangan pada papan tanda ini?', '["No vehicle entry","No sounding the horn","No left turn","No right turn"]'::jsonb, '["Kenderaan dilarang masuk","Dilarang membunyikan hon","Dilarang membelok ke kiri","Dilarang membelok ke kanan"]'::jsonb, 0, 'This sign means no vehicle entry.', 'Papan tanda ini bermaksud kenderaan dilarang masuk.', '/signs/9a316a4baac9f49a.svg', 'KPP General PDF page 57'),
  ('fea8fc74-f5ea-5aa9-8267-a7667e613fb8'::uuid, 'road-signs', 'mock-da-2', 9, 'What does this sign prohibit?', 'Apakah larangan pada papan tanda ini?', '["No parking","No U-turn","No left turn","No right turn"]'::jsonb, '["Dilarang meletak kenderaan","Dilarang membuat pusingan U","Dilarang membelok ke kiri","Dilarang membelok ke kanan"]'::jsonb, 1, 'This sign means no U-turn.', 'Papan tanda ini bermaksud dilarang membuat pusingan U.', '/signs/a299aef5bccc0fca.svg', 'KPP General PDF page 58'),
  ('249185c6-1c54-55de-b132-b62b97cfcca2'::uuid, 'road-signs', 'mock-da-2', 14, 'What does this sign prohibit?', 'Apakah larangan pada papan tanda ini?', '["No vehicle entry","No right turn","No U-turn","No left turn"]'::jsonb, '["Kenderaan dilarang masuk","Dilarang membelok ke kanan","Dilarang membuat pusingan U","Dilarang membelok ke kiri"]'::jsonb, 3, 'You must use a route that does not require turning left here.', 'Gunakan laluan yang tidak memerlukan anda membelok ke kiri di sini.', '/signs/ef495735d6870ce2.svg', 'KPP General PDF page 57'),
  ('cecd4c71-6c70-5530-b2df-6ba005558598'::uuid, 'traffic-rules', 'mock-da-2', 16, 'You are in the wrong lane as the queues split at a toll plaza. What should you avoid?', 'Anda berada di lorong yang salah apabila barisan berpecah di plaza tol. Apakah yang perlu dielakkan?', '["Cutting across the queues","Slowing with the traffic","Watching the lane signs","Leaving a gap ahead"]'::jsonb, '["Memotong merentasi barisan","Memperlahankan kenderaan mengikut trafik","Memerhatikan papan tanda lorong","Meninggalkan ruang di hadapan"]'::jsonb, 0, 'Choose the correct toll lane early. Last-second lane changes across queues increase the crash risk.', 'Pilih lorong tol yang betul lebih awal. Pertukaran lorong pada saat akhir merentasi barisan meningkatkan risiko kemalangan.', NULL, 'KPP Kelas D Automatik, PDF page 135'),
  ('213ee87a-4a29-586b-acdb-44fb00b44ae1'::uuid, 'traffic-rules', 'mock-da-2', 17, 'A motorway lane looks empty in your mirrors. Should you still indicate before moving over?', 'Lorong lebuh raya kelihatan kosong dalam cermin anda. Adakah anda masih perlu memberi isyarat sebelum menukar lorong?', '["Yes, before moving across","Yes, once halfway across","Only if a car is visible","Only if it is the right lane"]'::jsonb, '["Ya, sebelum bergerak ke lorong sebelah","Ya, apabila separuh masuk ke lorong sebelah","Hanya jika kelihatan kereta","Hanya jika itu lorong kanan"]'::jsonb, 0, 'Signal before every lane change. An apparently empty lane may contain a vehicle outside your mirror view.', 'Beri isyarat sebelum setiap pertukaran lorong. Kenderaan di lorong yang kelihatan kosong mungkin berada di luar pandangan cermin.', NULL, 'KPP Kelas D Automatik, PDF page 141'),
  ('36a3c293-611b-5d21-a75d-f285bfa1694b'::uuid, 'traffic-rules', 'mock-da-2', 18, 'You have just passed a car on a three-lane motorway. Where should you drive once the road ahead is clear?', 'Anda baru memotong kereta di lebuh raya tiga lorong. Di manakah anda patut memandu apabila jalan di hadapan lapang?', '["Stay in the right lane","Return to the normal driving lane","Stay in the centre lane","Return to the emergency lane"]'::jsonb, '["Kekal di lorong kanan","Ke lorong pemanduan kiri","Kekal di lorong tengah","Kembali ke lorong kecemasan"]'::jsonb, 1, 'The centre and right lanes are for overtaking. Return to the normal driving lane when safe.', 'Lorong tengah dan kanan digunakan untuk memotong. Kembali ke lorong pemanduan biasa apabila selamat.', NULL, 'KPP Kelas D Automatik, PDF page 141'),
  ('85b9585b-3ffb-584d-84c2-4718338126e1'::uuid, 'traffic-rules', 'mock-da-2', 19, 'A rear passenger pulls the handle from inside, but the door still opens from outside. Which control is engaged?', 'Penumpang belakang menarik pemegang dari dalam tetapi pintu masih boleh dibuka dari luar. Kawalan manakah sedang digunakan?', '["The child lock","The central locking switch","The window lock","The seat belt latch"]'::jsonb, '["Kunci kanak-kanak","Suis kunci pusat","Kunci tingkap","Kancing tali pinggang"]'::jsonb, 0, 'Use the child lock, if fitted, to help prevent a child from opening the door while travelling.', 'Gunakan kunci keselamatan kanak-kanak, jika ada, untuk membantu mengelakkan pintu dibuka oleh kanak-kanak semasa perjalanan.', NULL, 'KPP Kelas D Automatik, PDF page 140'),
  ('2154ddfb-c9d9-559b-a12e-410f58463b02'::uuid, 'traffic-rules', 'mock-da-2', 20, 'You are driving at night on a rural road with no street lights. How should you choose your speed?', 'Anda memandu pada waktu malam di jalan luar bandar tanpa lampu jalan. Bagaimanakah anda perlu memilih kelajuan?', '["Match the speed of the car ahead","Drive as fast as the limit allows","Match the speed you use by day","Leave enough time to stop for hazards"]'::jsonb, '["Ikut kelajuan kereta di hadapan","Pandu pada kelajuan maksimum yang dibenarkan","Ikut kelajuan yang digunakan pada siang hari","Pandu cukup perlahan untuk berhenti"]'::jsonb, 3, 'Drive slowly enough to respond to hazards such as pedestrians or animals that are hard to see at night.', 'Pandu cukup perlahan untuk bertindak terhadap bahaya seperti pejalan kaki atau haiwan yang sukar dilihat pada waktu malam.', NULL, 'KPP Kelas D Automatik, PDF page 137'),
  ('0ead8935-ec84-535d-a2cf-13beec51ad28'::uuid, 'traffic-rules', 'mock-da-2', 21, 'Which check helps you keep your view clear when rain starts?', 'Pemeriksaan manakah membantu memastikan pandangan anda jelas apabila hujan bermula?', '["Check the brake lights","Check the windscreen wipers","Check the hazard light switch","Check the rear-view mirror mount"]'::jsonb, '["Periksa lampu brek","Periksa pengelap cermin hadapan","Periksa suis lampu amaran kecemasan","Periksa pemegang cermin pandang belakang"]'::jsonb, 1, 'Make sure the wipers work before driving. They must clear rain from the windscreen.', 'Pastikan pengelap berfungsi sebelum memandu. Pengelap mesti dapat membersihkan air hujan dari cermin hadapan.', NULL, 'KPP Kelas D Automatik, PDF page 120'),
  ('3a19384d-6d00-51d9-abd8-7dda2908cd90'::uuid, 'traffic-rules', 'mock-da-2', 22, 'What should you switch on when driving through a tunnel?', 'Apakah yang perlu dihidupkan semasa memandu di dalam terowong?', '["Cabin lights","Hazard lights","Headlights","Rear fog lights"]'::jsonb, '["Lampu kabin","Lampu amaran kecemasan","Lampu hadapan","Lampu kabus belakang"]'::jsonb, 2, 'Use the vehicle’s headlights in a tunnel and allow a safe following gap because visibility is limited.', 'Gunakan lampu hadapan di dalam terowong dan kekalkan jarak mengekori yang selamat kerana penglihatan terhad.', NULL, 'KPP Kelas D Automatik, PDF page 139'),
  ('f2064041-4fa7-50e6-8289-9f67eaa63220'::uuid, 'traffic-rules', 'mock-da-2', 23, 'You are passing a busy market. How should you respond to pedestrians near the road?', 'Anda melalui pasar yang sibuk. Bagaimanakah anda perlu bertindak terhadap pejalan kaki berhampiran jalan?', '["Keep speed and watch the kerb","Slow down and be ready to yield","Sound the horn and continue","Move out and continue at speed"]'::jsonb, '["Kekalkan kelajuan dan perhatikan bebendul","Perlahankan dan beri laluan","Bunyikan hon dan teruskan perjalanan","Bergerak ke tepi dan kekalkan kelajuan"]'::jsonb, 1, 'Slow down and watch for pedestrians in crowded places. Give them priority when they cross and obey crossing signals.', 'Perlahankan kenderaan dan perhatikan pejalan kaki di tempat tumpuan ramai. Beri keutamaan ketika mereka melintas dan patuhi isyarat lintasan.', NULL, 'KPP Kelas D Automatik, PDF page 139'),
  ('5ada336f-16f6-503b-89c4-c4c080d8d47c'::uuid, 'traffic-rules', 'mock-da-2', 24, 'Which hidden hazard should you expect near a bus stopped at the roadside?', 'Bahaya tersembunyi manakah yang perlu dijangkakan apabila bas berhenti di tepi jalan?', '["People crossing close to the bus","The bus driver opening the luggage bay","Vehicles queuing further down the road","Passengers waiting behind the shelter"]'::jsonb, '["Orang melintas berhampiran bas","Pemandu bas membuka ruang bagasi","Kenderaan beratur lebih jauh di hadapan","Penumpang menunggu di belakang pondok"]'::jsonb, 0, 'The bus can hide passengers who step into the road in front of it or behind it. Slow down and watch both ends.', 'Bas boleh melindungi penumpang yang melangkah ke jalan dari hadapan atau belakang bas. Perlahankan kenderaan dan perhatikan kedua-dua hujung bas.', NULL, 'KPP Kelas D Automatik, PDF page 81'),
  ('3ee8b785-8450-5e3d-9900-4af1004e1201'::uuid, 'traffic-rules', 'mock-da-2', 25, 'Goats are starting to cross a village road. What should you do?', 'Kambing mula melintas jalan kampung. Apakah tindakan anda?', '["Keep speed and pass behind them","Sound the horn while passing","Move around them before they spread out","Slow down and let them cross"]'::jsonb, '["Kekalkan kelajuan dan lalu di belakangnya","Bunyikan hon ketika melintas di sisinya","Pintas sebelum haiwan itu berselerak","Perlahankan kenderaan dan beri laluan"]'::jsonb, 3, 'Slow down and give animals room to cross. Avoid sounding the horn because it can startle them.', 'Perlahankan kenderaan dan beri ruang kepada haiwan untuk melintas. Elakkan membunyikan hon kerana bunyinya boleh mengejutkan haiwan.', NULL, 'KPP Kelas D Automatik, PDF page 136'),
  ('0c236e90-3569-50ae-9e9b-e220278d970f'::uuid, 'traffic-rules', 'mock-da-2', 26, 'An oncoming vehicle approaches a bend on a narrow rural road. What should you be ready for?', 'Kenderaan dari arah bertentangan menghampiri selekoh di jalan luar bandar yang sempit. Apakah yang perlu dijangkakan?', '["It may stop at the lane line","It may cut into your lane","It may signal before the bend","It may slow on its own side"]'::jsonb, '["Ia mungkin berhenti di garisan lorong","Ia mungkin masuk ke lorong anda","Ia mungkin memberi isyarat sebelum selekoh","Ia mungkin memperlahankan kenderaan di laluannya"]'::jsonb, 1, 'On a narrow bend, an approaching vehicle may cross into your lane. Reduce speed and leave room to respond.', 'Di selekoh sempit, kenderaan dari arah bertentangan mungkin masuk ke lorong anda. Perlahankan kenderaan dan tinggalkan ruang untuk bertindak.', NULL, 'KPP Kelas D Automatik, PDF page 135'),
  ('7908f172-6889-50fa-9b13-fa124fb66ca4'::uuid, 'traffic-rules', 'mock-da-2', 27, 'You are about to follow a heavy lorry uphill. What should you do with the space in front of you?', 'Anda akan mengekori lori berat ketika mendaki bukit. Apakah yang patut anda lakukan dengan ruang di hadapan?', '["Close the gap as the lorry slows","Hold back as the lorry climbs","Move beside the lorry before the hill","Follow its rear closely at the crest"]'::jsonb, '["Rapatkan jarak apabila lori perlahan","Jarakkan kenderaan semasa lori mendaki","Bergerak ke sisi lori sebelum bukit","Ekor rapat di belakang lori di puncak"]'::jsonb, 1, 'Allow a safe gap behind heavy vehicles when they start, climb or turn. Give yourself room to react to changes in their speed.', 'Kekalkan jarak yang selamat di belakang kenderaan berat apabila ia mula bergerak, mendaki atau membelok. Sediakan ruang untuk bertindak jika kelajuannya berubah.', NULL, 'KPP Kelas D Automatik, PDF page 88'),
  ('bd90e969-3ce3-5e1e-8ac1-590c180af894'::uuid, 'traffic-rules', 'mock-da-2', 28, 'You catch up to a car on an unlit road. Which lights should you use while following it?', 'Anda menghampiri sebuah kereta di jalan yang tidak berlampu. Lampu manakah yang patut digunakan semasa mengekorinya?', '["High beams","Low beams","Side lights","Front fog lights"]'::jsonb, '["Lampu tinggi","Lampu rendah","Lampu sisi","Lampu kabus hadapan"]'::jsonb, 1, 'Dip your headlights when following another vehicle. High beams can dazzle its driver through the mirrors.', 'Gunakan lampu rendah apabila mengekori kenderaan lain. Lampu tinggi boleh menyilaukan pemandunya melalui cermin.', NULL, 'KPP Kelas D Automatik, PDF page 142'),
  ('8a96f101-286c-5838-b960-66051ea4c14c'::uuid, 'traffic-rules', 'mock-da-2', 29, 'Oncoming headlights are dazzling you. Where should you direct your gaze briefly to avoid looking into them?', 'Lampu hadapan dari arah bertentangan menyilaukan anda. Ke manakah anda patut mengalihkan pandangan seketika supaya tidak melihat terus ke arahnya?', '["Towards the centre line","Towards the right lane","Towards the left edge","Towards the rear-view mirror"]'::jsonb, '["Ke arah garisan tengah","Ke arah lorong kanan","Ke arah tepi kiri jalan","Ke arah cermin pandang belakang"]'::jsonb, 2, 'Use the left edge of the road as a reference while maintaining control. Avoid looking straight at the bright headlights.', 'Gunakan tepi kiri jalan sebagai panduan sambil mengekalkan kawalan. Elakkan melihat terus ke arah lampu yang terang.', NULL, 'KPP Kelas D Automatik, PDF page 143'),
  ('719d804a-26d4-51b5-8d89-7d6d1e54fb20'::uuid, 'traffic-rules', 'mock-da-2', 30, 'Bright sunlight is scattering across the glass in front of you. What preparation helps reduce it?', 'Cahaya matahari terang berselerak pada kaca di hadapan anda. Persediaan apakah membantu mengurangkannya?', '["Remove dirt from the glass","Raise the rear-view mirror","Move the visor up","Close both side windows"]'::jsonb, '["Bersihkan kotoran pada kaca","Naikkan cermin pandang belakang","Naikkan pengadang matahari","Tutup kedua-dua tingkap sisi"]'::jsonb, 0, 'Remove dirt from the windscreen and keep enough washer fluid to clean it as needed.', 'Bersihkan kotoran pada cermin hadapan dan pastikan cecair pencuci mencukupi apabila diperlukan.', NULL, 'KPP Kelas D Automatik, PDF page 145'),
  ('de7912d3-3994-526e-b671-f8fef3045aa4'::uuid, 'traffic-rules', 'mock-da-2', 31, 'Why does a wet road leave you needing more room to stop?', 'Mengapakah anda memerlukan lebih ruang untuk berhenti di jalan basah?', '["The tyres have less grip","The engine takes longer to respond","The steering becomes heavier","The road markings become less visible"]'::jsonb, '["Cengkaman tayar berkurang","Enjin mengambil masa lebih lama untuk bertindak","Stereng menjadi lebih berat","Garisan jalan menjadi kurang jelas"]'::jsonb, 0, 'Wet roads reduce tyre grip, lengthening the distance needed to stop. Increase your following gap.', 'Jalan basah mengurangkan cengkaman tayar dan memanjangkan jarak untuk berhenti. Tambah jarak mengekori.', NULL, 'KPP Kelas D Automatik, PDF page 146'),
  ('abb8fed4-860f-551b-8899-057a4044f276'::uuid, 'traffic-rules', 'mock-da-2', 32, 'You are behind a slow car in thick fog on a two-way road. What is the safest plan?', 'Anda berada di belakang kereta perlahan dalam kabus tebal di jalan dua hala. Apakah rancangan paling selamat?', '["Follow closer to see its lights","Pass as soon as its lane is clear","Wait behind at a safe distance","Move partly out to look ahead"]'::jsonb, '["Ekor lebih rapat untuk melihat lampunya","Potong sebaik sahaja laluannya lapang","Kekal di belakang pada jarak selamat","Keluar sedikit dari lorong untuk melihat ke hadapan"]'::jsonb, 2, 'Limited visibility makes overtaking risky in fog. Stay in your lane, leave a safe gap and match your speed to what you can see.', 'Penglihatan terhad menjadikan tindakan memotong berbahaya dalam kabus. Kekal di lorong, tinggalkan jarak yang selamat dan sesuaikan kelajuan dengan jarak penglihatan.', NULL, 'KPP Kelas D Automatik, PDF page 149'),
  ('7ec785e6-a3b5-5fc1-9fb5-38126929fe3b'::uuid, 'traffic-rules', 'mock-da-2', 33, 'Rain reduces visibility on the motorway, but your car is moving normally. Which lights should you use?', 'Hujan mengurangkan penglihatan di lebuh raya, tetapi kereta anda bergerak seperti biasa. Lampu manakah yang patut digunakan?', '["Hazard lights alone","Headlights alone","Headlights and hazard lights","Hazard lights and side lights"]'::jsonb, '["Lampu amaran kecemasan sahaja","Lampu hadapan sahaja","Lampu hadapan dan lampu amaran kecemasan","Lampu amaran kecemasan dan lampu sisi"]'::jsonb, 1, 'Use headlights so others can see your moving car. Reserve hazard lights for an emergency.', 'Gunakan lampu hadapan supaya orang lain dapat melihat kereta anda yang sedang bergerak. Gunakan lampu amaran kecemasan untuk keadaan kecemasan.', NULL, 'KPP Kelas D Automatik, PDF page 141'),
  ('5cd7b3d8-1f42-5132-bf26-a8d5e9c72c64'::uuid, 'traffic-rules', 'mock-da-2', 34, 'You are about to enter a bend just after rain. When should you reduce your speed?', 'Anda akan memasuki selekoh sejurus selepas hujan. Bilakah anda perlu memperlahankan kenderaan?', '["Before the bend","Near the middle of the bend","After the bend","When the rear starts to slide"]'::jsonb, '["Sebelum selekoh","Berhampiran pertengahan selekoh","Selepas selekoh","Apabila bahagian belakang mula tergelincir"]'::jsonb, 0, 'Wet bends offer less grip. Enter more slowly to reduce the risk of skidding.', 'Cengkaman di selekoh basah lebih rendah. Masuk dengan lebih perlahan untuk mengurangkan risiko tergelincir.', NULL, 'KPP Kelas D Automatik, PDF page 146'),
  ('9633d15e-c13a-5817-92d2-e3c3562930f6'::uuid, 'traffic-rules', 'mock-da-2', 35, 'What happens to the tyres when a car aquaplanes?', 'Apakah yang berlaku pada tayar apabila kereta mengalami gelinciran air?', '["Water separates them from the road","Water increases their tread depth","Water presses them into the road","Water cools the tread evenly"]'::jsonb, '["Air memisahkan tayar daripada jalan","Air menambah kedalaman bunga tayar","Air menekan tayar ke permukaan jalan","Air menyejukkan bunga tayar secara sekata"]'::jsonb, 0, 'Water can build up between the tyres and the road. The tyres lose contact and the car slides.', 'Air boleh terkumpul antara tayar dengan jalan. Tayar kehilangan sentuhan dan kereta tergelincir.', NULL, 'KPP Kelas D Automatik, PDF page 146'),
  ('6be0404e-7b1a-5fbd-a5e1-00103aaedf3c'::uuid, 'traffic-rules', 'mock-da-2', 36, 'A motorcycle ahead is crossing an exposed bridge in strong crosswinds. What should you allow for?', 'Motosikal di hadapan sedang melalui jambatan terbuka ketika angin lintang bertiup kencang. Apakah yang perlu dijangkakan?', '["It may drift sideways","It may need more room to accelerate","It may pull over under a bridge","It may leave a larger following gap"]'::jsonb, '["Ia mungkin teranjak ke sisi","Ia mungkin memerlukan lebih ruang untuk memecut","Ia mungkin berhenti di bawah jambatan","Ia mungkin menambah jarak mengekori"]'::jsonb, 0, 'Crosswinds can push a motorcycle sideways. Allow for this movement before passing.', 'Angin lintang boleh menolak motosikal ke sisi. Ambil kira pergerakan ini sebelum memotong.', NULL, 'KPP Kelas D Automatik, PDF page 147'),
  ('5b2c3f60-02cc-51c6-92ad-8fd2afcb04e4'::uuid, 'traffic-rules', 'mock-da-2', 37, 'Floodwater covers the road and you cannot judge its depth. What should you do?', 'Air banjir menutupi jalan dan anda tidak dapat menganggarkan kedalamannya. Apakah tindakan anda?', '["Follow a taller vehicle through","Take a different route","Try the edge at walking speed","Cross along the centre line"]'::jsonb, '["Ikut kenderaan lebih tinggi meredah air","Gunakan laluan lain","Cuba di tepi pada kelajuan berjalan kaki","Redah air di sepanjang garisan tengah"]'::jsonb, 1, 'If you cannot establish that the water is shallow enough to cross safely, turn back and take another route.', 'Jika anda tidak dapat memastikan air cukup cetek untuk dilalui dengan selamat, patah balik dan ambil laluan lain.', NULL, 'KPP Kelas D Automatik, PDF page 148'),
  ('f1eb10be-620c-53cb-bb00-2d04875d6728'::uuid, 'traffic-rules', 'mock-da-2', 38, 'A driver enters deep floodwater and the engine stops. Which component can admit water directly into the engine?', 'Pemandu meredah banjir dalam dan enjin terhenti. Komponen manakah boleh membenarkan air masuk terus ke dalam enjin?', '["The air intake","The coolant reservoir","The washer fluid tank","The wheel arch"]'::jsonb, '["Salur masuk udara","Takungan cecair penyejuk","Tangki cecair pencuci cermin","Ruang lengkung roda"]'::jsonb, 0, 'Floodwater can enter through the air intake and seriously damage the engine. Avoid driving into deep water.', 'Air banjir boleh masuk melalui salur masuk udara dan menyebabkan kerosakan serius pada enjin. Elakkan meredah air dalam.', NULL, 'KPP Kelas D Automatik, PDF page 148'),
  ('c692d03a-918d-5aa4-98f1-25b206737642'::uuid, 'traffic-rules', 'mock-da-2', 39, 'Rain becomes so heavy that you can no longer see far enough to drive. What should you do next?', 'Hujan terlalu lebat sehingga anda tidak dapat melihat cukup jauh untuk memandu. Apakah tindakan seterusnya?', '["Pull off at a suitable stopping place","Keep going behind another vehicle","Slow and stay in the live lane","Continue until visibility improves"]'::jsonb, '["Berhenti di tempat yang sesuai di luar aliran trafik","Teruskan di belakang kenderaan lain","Perlahankan dan kekal di lorong trafik","Teruskan sehingga penglihatan bertambah baik"]'::jsonb, 0, 'When visibility becomes too poor to proceed safely, stop at the nearest suitable place away from moving traffic.', 'Apabila penglihatan terlalu terhad untuk meneruskan perjalanan dengan selamat, berhenti di tempat sesuai yang terdekat, jauh daripada trafik bergerak.', NULL, 'KPP Kelas D Automatik, PDF page 147'),
  ('4a4f42e2-9a03-5b3e-a52b-481d823dd4ce'::uuid, 'traffic-rules', 'mock-da-2', 40, 'You have been driving on the motorway for about two hours. Where should you take a planned break?', 'Anda telah memandu di lebuh raya selama kira-kira dua jam. Di manakah anda patut berhenti untuk berehat?', '["At a designated rest area","On the emergency shoulder","At the entrance to an exit lane","On a wide part of an on-ramp"]'::jsonb, '["Di kawasan rehat yang disediakan","Di bahu jalan kecemasan","Di pintu masuk lorong susur keluar","Di bahagian lebar susur masuk"]'::jsonb, 0, 'Plan to stop and rest at a designated area on long journeys. The motorway guidance suggests a break after two hours.', 'Rancang untuk berhenti dan berehat di kawasan yang disediakan semasa perjalanan jauh. Panduan lebuh raya mencadangkan rehat selepas dua jam.', NULL, 'KPP Kelas D Automatik, PDF page 140'),
  ('5262efd4-c9eb-5517-9460-bab398dde2e0'::uuid, 'safety-principles', 'mock-da-2', 41, 'What is one purpose of the KEJARA system?', 'Apakah satu tujuan sistem KEJARA?', '["Track vehicle ownership","Set road speed limits","Reduce repeat offences","Manage driving-test bookings"]'::jsonb, '["Merekod pemilikan kenderaan","Menetapkan had laju jalan","Mengurangkan kesalahan berulang","Mengurus tempahan ujian memandu"]'::jsonb, 2, 'One purpose is to discourage repeat offences by educating and disciplining drivers.', 'Antara tujuannya ialah mengurangkan kesalahan berulang dengan mendidik dan mendisiplinkan pemandu.', NULL, 'KPP General, PDF 94'),
  ('6829053b-55ea-59f5-91f2-8af25a8d1a2c'::uuid, 'safety-principles', 'mock-da-2', 42, 'A driver with a competent licence reaches 20 KEJARA points for the first time. What does the schedule show?', 'Pemegang lesen kompeten mencapai 20 mata KEJARA buat kali pertama. Apakah tindakan dalam jadual?', '["A suspension","A cancellation","A course referral","A warning"]'::jsonb, '["Penggantungan","Pembatalan","Rujukan kursus","Amaran"]'::jsonb, 3, 'The first 20-point threshold shown in the schedule results in a warning.', 'Ambang 20 mata kali pertama dalam jadual ini membawa kepada amaran.', NULL, 'KPP General, PDF 95'),
  ('2d7a8de4-b592-56a5-b9b6-62601a8b7956'::uuid, 'safety-principles', 'mock-da-2', 43, 'What kind of offence can lead to KEJARA points?', 'Apakah jenis kesalahan yang boleh menyebabkan mata KEJARA dikenakan?', '["A scheduled traffic offence","An internal parking charge","An insurance contract breach","A missed service appointment"]'::jsonb, '["Kesalahan trafik terjadual","Caj parkir dalaman","Pelanggaran kontrak insurans","Janji temu servis terlepas"]'::jsonb, 0, 'KEJARA applies to scheduled offences under the road transport rules.', 'KEJARA terpakai kepada kesalahan terjadual di bawah peraturan pengangkutan jalan.', NULL, 'KPP General, PDF 93'),
  ('bc2012db-6db3-5875-9315-356360071fe4'::uuid, 'safety-principles', 'mock-da-2', 44, 'What is the largest percentage deduction listed for KEJARA points?', 'Berapakah peratusan potongan tertinggi yang disenaraikan bagi mata KEJARA?', '["25%","50%","75%","100%"]'::jsonb, '["25%","50%","75%","100%"]'::jsonb, 1, 'The curriculum describes a possible reduction of up to 50% of the demerit points under the listed conditions.', 'Kurikulum menerangkan potongan sehingga 50% daripada mata demerit tertakluk pada syarat yang disenaraikan.', NULL, 'KPP General, PDF 95'),
  ('84551108-ccb6-5484-a6f1-a3684d63be0f'::uuid, 'safety-principles', 'mock-da-2', 45, 'Which plan is allowed while your driving licence is suspended?', 'Rancangan manakah dibenarkan ketika lesen memandu anda digantung?', '["Ask someone else to drive you","Drive a borrowed car to work","Ride a different vehicle class","Take a short drive for essentials"]'::jsonb, '["Minta orang lain memandu anda","Pandu kereta pinjaman ke tempat kerja","Tunggang kenderaan kelas lain","Pandu sekejap untuk urusan penting"]'::jsonb, 0, 'Suspension prevents the person from driving. Changing vehicles does not remove the restriction.', 'Penggantungan melarang orang itu daripada memandu. Menukar kenderaan tidak menamatkan larangan tersebut.', NULL, 'KPP General, PDF 96'),
  ('46587f9c-8aea-5009-a879-4f9145217898'::uuid, 'safety-principles', 'mock-da-2', 46, 'What must a former probationary driver repeat after a cancellation ban ends?', 'Apakah yang perlu diulang oleh bekas pemegang lesen percubaan selepas larangan pembatalan tamat?', '["The medical form alone","The licence renewal alone","The training and tests","The probation period alone"]'::jsonb, '["Borang kesihatan sahaja","Pembaharuan lesen sahaja","Latihan dan ujian","Tempoh percubaan sahaja"]'::jsonb, 2, 'The curriculum requires the training and tests again, followed by a new probation period.', 'Kurikulum memerlukan latihan dan ujian semula, diikuti tempoh percubaan yang baharu.', NULL, 'KPP Kelas DA Automatik, PDF 21'),
  ('78bc5a1a-1664-56dc-8906-c701e3858371'::uuid, 'safety-principles', 'mock-da-2', 47, 'What should you look for under the car during a pre-drive walk-around?', 'Apakah yang perlu diperiksa di bawah kereta sebelum memandu?', '["Signs of tread wear","Loose washer nozzles","A blocked air filter","Signs of a leak"]'::jsonb, '["Tanda bunga tayar haus","Muncung pencuci longgar","Penapis udara tersumbat","Tanda kebocoran"]'::jsonb, 3, 'Look underneath to see whether anything is leaking before setting off.', 'Lihat di bawah kereta untuk mengesan sebarang kebocoran sebelum bergerak.', NULL, 'KPP Kelas DA Automatik, PDF 227'),
  ('e035ab53-3bba-56d2-82f9-af14814a6e36'::uuid, 'safety-principles', 'mock-da-2', 48, 'What should you check on the number plates during a walk-around?', 'Apakah yang perlu diperiksa pada plat nombor semasa pemeriksaan keliling kereta?', '["Clean and undamaged","Clean with no sharp edges","Straight and freshly painted","Rust-free with new screws"]'::jsonb, '["Bersih dan tidak rosak","Bersih dan tiada bucu tajam","Lurus dan baru dicat","Bebas karat dengan skru baharu"]'::jsonb, 0, 'Check that the plates are clean and undamaged.', 'Pastikan plat nombor bersih dan tidak rosak.', NULL, 'KPP Kelas DA Automatik, PDF 226'),
  ('eb4ec4b4-bca5-5b5d-9e21-de27be2ff1d3'::uuid, 'safety-principles', 'mock-da-2', 49, 'The automatic car has stopped on the marked ramp line and is ready to move off uphill. Which position should you select?', 'Kereta automatik telah berhenti di garisan tanjakan dan sedia bergerak mendaki. Kedudukan manakah patut dipilih?', '["D","N","P","R"]'::jsonb, '["D","N","P","R"]'::jsonb, 0, 'Select D and release the brakes as instructed, then press the accelerator gently to leave the ramp.', 'Pilih D dan lepaskan brek mengikut langkah yang diterangkan, kemudian tekan pemecut perlahan-lahan untuk keluar dari tanjakan.', NULL, 'KPP Kelas DA Automatik, PDF 284'),
  ('22087933-a3f6-50e9-95b3-1f3b0771e39c'::uuid, 'safety-principles', 'mock-da-2', 50, 'How do you start reversing slowly in the automatic car after selecting R and checking it is safe?', 'Bagaimanakah anda mula mengundur perlahan dalam kereta automatik selepas memilih R dan memastikan keadaan selamat?', '["Tap the accelerator twice","Release the foot brake quickly","Ease off the foot brake","Hold the brake and add throttle"]'::jsonb, '["Tekan pemecut dua kali","Lepaskan pedal brek dengan cepat","Lepaskan pedal brek perlahan-lahan","Tahan brek sambil menekan pemecut"]'::jsonb, 2, 'With the parking brake released, ease off the foot brake to start moving without using the accelerator.', 'Selepas melepaskan brek tangan, lepaskan pedal brek perlahan-lahan untuk bergerak tanpa menekan pemecut.', NULL, 'KPP Kelas DA Automatik, PDF 233'),
  ('48a575e9-9091-52e2-bdee-42db98d3c1fb'::uuid, 'road-signs', 'mock-da-3', 4, 'What does this sign prohibit?', 'Apakah larangan pada papan tanda ini?', '["No U-turn","No left turn","No right turn","No parking"]'::jsonb, '["Dilarang membuat pusingan U","Dilarang membelok ke kiri","Dilarang membelok ke kanan","Dilarang meletak kenderaan"]'::jsonb, 3, 'This sign means no parking.', 'Papan tanda ini bermaksud dilarang meletak kenderaan.', '/signs/fbd415b24ab21b44.svg', 'KPP General PDF page 58'),
  ('ec97d6de-f52c-51fd-980f-a5253a93a24a'::uuid, 'road-signs', 'mock-da-3', 8, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Traffic shifts lanes ahead","Narrow clearance in work zone","Right bend in work zone","Sharp work-zone diversion"]'::jsonb, '["Lencongan lorong di hadapan","Kelegaan terhad di zon kerja","Selekoh kanan di zon kerja","Lencongan tajam di zon kerja"]'::jsonb, 3, 'This sign means sharp work-zone diversion.', 'Papan tanda ini bermaksud lencongan tajam di zon kerja.', '/signs/263bc825012bcc83.svg', 'KPP General PDF page 76'),
  ('4d5c26e0-1284-51ea-8380-b54c79e5da3d'::uuid, 'road-signs', 'mock-da-3', 13, 'What does this sign prohibit?', 'Apakah larangan pada papan tanda ini?', '["No stopping","No overtaking","No left turn","No parking"]'::jsonb, '["Dilarang berhenti","Dilarang memotong","Dilarang membelok ke kiri","Dilarang meletak kenderaan"]'::jsonb, 0, 'This sign means no stopping.', 'Papan tanda ini bermaksud dilarang berhenti.', '/signs/ecd3d648f3d4a187.svg', 'KPP General PDF page 59'),
  ('eb33f804-8a8d-52af-b0f8-e44971e82502'::uuid, 'road-signs', 'mock-da-3', 14, 'What does this sign prohibit?', 'Apakah larangan pada papan tanda ini?', '["No vehicle entry","No sounding the horn","No left turn","No right turn"]'::jsonb, '["Kenderaan dilarang masuk","Dilarang membunyikan hon","Dilarang membelok ke kiri","Dilarang membelok ke kanan"]'::jsonb, 1, 'This sign means no sounding the horn.', 'Papan tanda ini bermaksud dilarang membunyikan hon.', '/signs/ce55b86645694f5d.svg', 'KPP General PDF page 57'),
  ('dc9d29fc-7f47-5a88-88fc-47078d426039'::uuid, 'traffic-rules', 'mock-da-3', 16, 'What is recorded under KEJARA for a scheduled driving offence?', 'Apakah yang direkodkan di bawah KEJARA bagi kesalahan memandu terjadual?', '["Extra training hours","Licence renewal credits","Demerit points","A revised test score"]'::jsonb, '["Jam latihan tambahan","Kredit pembaharuan lesen","Mata demerit","Markah ujian yang disemak"]'::jsonb, 2, 'KEJARA tracks scheduled traffic offences through demerit points. It aims to discourage repeat offences.', 'KEJARA merekodkan kesalahan lalu lintas terjadual melalui mata demerit. Sistem ini bertujuan mengurangkan kesalahan berulang.', NULL, 'KPP Kelas D Automatik, PDF page 169'),
  ('9a26a86c-1776-5c14-afb2-d5314c0f0560'::uuid, 'traffic-rules', 'mock-da-3', 17, 'Which step may JPJ require of a driver whose licence has been suspended under KEJARA?', 'Apakah langkah yang mungkin diarahkan oleh JPJ kepada pemandu yang lesennya digantung di bawah KEJARA?', '["Apply for a vocational licence","Attend a rehabilitation course","Replace the licence card","Join a vehicle inspection course"]'::jsonb, '["Mohon lesen vokasional","Hadiri kursus pemulihan","Gantikan kad lesen","Sertai kursus pemeriksaan kenderaan"]'::jsonb, 1, 'JPJ may direct a suspended driver to attend a rehabilitation course.', 'JPJ boleh mengarahkan pemandu yang lesennya digantung supaya menghadiri kursus pemulihan.', NULL, 'KPP Kelas D Automatik, PDF page 170'),
  ('5db8faf3-29e4-52a0-969f-2c5e5288947d'::uuid, 'traffic-rules', 'mock-da-3', 18, 'Where should a probationary car driver display the P signs?', 'Di manakah pemandu kereta dengan lesen percubaan perlu mempamerkan tanda P?', '["Front windscreen only","Rear windscreen only","Both side windows","Front and rear windscreens"]'::jsonb, '["Cermin hadapan sahaja","Cermin belakang sahaja","Kedua-dua tingkap sisi","Cermin hadapan dan belakang"]'::jsonb, 3, 'Place a P sign at the upper left of each windscreen as shown in the licence guidance.', 'Letakkan tanda P di penjuru kiri atas setiap cermin seperti yang ditunjukkan dalam panduan lesen.', NULL, 'KPP Kelas D Automatik, PDF page 21'),
  ('a418bef4-51d6-56cd-9195-8cf96e65ea1e'::uuid, 'traffic-rules', 'mock-da-3', 19, 'What is the purpose of the probationary driving period?', 'Apakah tujuan tempoh percubaan memandu?', '["To gain experience under licence conditions","To prepare for the first theory class","To qualify for a vocational driving licence","To allow unlicensed practice on roads"]'::jsonb, '["Untuk menimba pengalaman tertakluk pada syarat lesen","Untuk bersedia bagi kelas teori pertama","Untuk melayakkan diri bagi lesen vokasional","Untuk membenarkan latihan tanpa lesen di jalan"]'::jsonb, 0, 'The probationary period gives new drivers time to build skill and experience under specific conditions.', 'Tempoh percubaan memberi masa kepada pemandu baharu untuk membina kemahiran dan pengalaman tertakluk pada syarat tertentu.', NULL, 'KPP Kelas D Automatik, PDF page 20'),
  ('3e1b2a0a-3073-52c3-8b86-7369f35ccfef'::uuid, 'traffic-rules', 'mock-da-3', 20, 'Which driving ability can alcohol impair even when you can still operate the pedals?', 'Keupayaan memandu manakah boleh terjejas oleh alkohol walaupun anda masih boleh menggunakan pedal?', '["Anticipating changes in traffic","Reading the fuel level when parked","Reaching the direction indicator","Recognising the gear lever positions"]'::jsonb, '["Menjangka perubahan trafik","Membaca paras bahan api ketika parkir","Mencapai suis isyarat","Mengenal kedudukan tuil gear"]'::jsonb, 0, 'Alcohol impairs your concentration and ability to anticipate hazards. Arrange a sober driver.', 'Alkohol menjejaskan tumpuan dan keupayaan menjangka bahaya. Minta pemandu yang tidak mengambil alkohol untuk memandu.', NULL, 'KPP Kelas D Automatik, PDF page 78'),
  ('3a349abe-146a-523f-ac5b-c6007eb6f335'::uuid, 'traffic-rules', 'mock-da-3', 21, 'You cannot attend your practical test appointment. What should you arrange?', 'Anda tidak dapat menghadiri janji temu ujian amali. Apakah yang perlu diatur?', '["An approved change of date","A walk-in at another testing site","A replacement theory appointment","A switch with another candidate"]'::jsonb, '["Pertukaran tarikh yang diluluskan","Hadir tanpa tempahan di pusat lain","Janji temu ujian teori gantian","Pertukaran dengan calon lain"]'::jsonb, 0, 'If you cannot attend on the booked date, apply to change it within the permitted period.', 'Jika anda tidak dapat hadir pada tarikh yang ditempah, mohon untuk memindanya dalam tempoh yang dibenarkan.', NULL, 'KPP Kelas D Automatik, PDF page 16'),
  ('eef75dee-4e2d-516d-a56d-1009cb04e964'::uuid, 'traffic-rules', 'mock-da-3', 22, 'Traffic on a motorway speeds up above the posted limit. How should you choose your speed?', 'Trafik di lebuh raya bergerak melebihi had laju yang dipaparkan. Bagaimanakah anda patut memilih kelajuan?', '["Match traffic while passing","Keep within the posted limit","Use the speed of the fastest lane","Follow the lorry ahead at its speed"]'::jsonb, '["Ikut kelajuan trafik ketika memotong","Patuhi had laju","Ikut kelajuan lorong terpantas","Ikut kelajuan lori di hadapan"]'::jsonb, 1, 'The speed limit still applies when other drivers exceed it. Leave space and keep a safe speed within the limit.', 'Had laju masih terpakai apabila pemandu lain melampauinya. Tinggalkan ruang dan kekalkan kelajuan selamat dalam had itu.', NULL, 'KPP Kelas D Automatik, PDF page 140'),
  ('add033fc-9fba-5906-ac07-a8510b4fdd92'::uuid, 'traffic-rules', 'mock-da-3', 23, 'You stop at a junction where a building blocks your view. What must you establish before continuing?', 'Anda berhenti di persimpangan apabila sebuah bangunan menghalang pandangan. Apakah yang mesti dipastikan sebelum meneruskan perjalanan?', '["That your indicator has flashed","That the road is clear to enter","That another driver has waved","That the car behind has stopped"]'::jsonb, '["Lampu isyarat anda telah berkelip","Jalan lapang untuk dimasuki","Pemandu lain telah melambai","Kereta di belakang telah berhenti"]'::jsonb, 1, 'At a junction where you must stop, wait until you can establish that it is safe to go. Slowing alone does not establish that.', 'Di persimpangan yang memerlukan anda berhenti, tunggu sehingga anda dapat memastikan keadaan selamat. Memperlahankan kenderaan sahaja tidak mencukupi.', NULL, 'KPP Kelas D Automatik, PDF page 109'),
  ('60b667a9-f799-542a-a831-5dc738dd71fd'::uuid, 'traffic-rules', 'mock-da-3', 24, 'You see traffic joining from an on-ramp ahead. What should you plan for?', 'Anda melihat trafik memasuki lebuh raya melalui susur masuk di hadapan. Apakah yang perlu dirancang?', '["Space for vehicles to join","A turn into the joining lane","A stop at the end of the ramp","A pass along the hard shoulder"]'::jsonb, '["Ruang untuk kenderaan masuk","Belokan ke lorong susur masuk","Berhenti di hujung susur masuk","Memotong melalui bahu jalan"]'::jsonb, 0, 'Watch for vehicles entering the motorway. Leave enough space to respond to their movements.', 'Perhatikan kenderaan yang memasuki lebuh raya. Tinggalkan ruang yang cukup untuk bertindak terhadap pergerakannya.', NULL, 'KPP Kelas D Automatik, PDF page 140'),
  ('f1e160e3-bd0a-5bd5-9c17-27596dd4297d'::uuid, 'traffic-rules', 'mock-da-3', 25, 'Your car breaks down on a motorway. Where should you pull over if you can safely reach it?', 'Kereta anda rosak di lebuh raya. Di manakah anda perlu berhenti jika dapat sampai dengan selamat?', '["At the edge of the driving lane","In the next overtaking lane","At the entrance to an exit ramp","In the emergency lane"]'::jsonb, '["Di tepi lorong pemanduan","Di lorong memotong seterusnya","Di pintu masuk susur keluar","Di lorong kecemasan"]'::jsonb, 3, 'Signal left and move into the emergency lane if you can do so safely. Switch on the hazard lights once stopped.', 'Beri isyarat kiri dan masuk ke lorong kecemasan jika selamat. Hidupkan lampu amaran kecemasan selepas berhenti.', NULL, 'KPP Kelas D Automatik, PDF page 128'),
  ('9fbe0945-8dc4-5b3e-8825-3f3aa3ba2b53'::uuid, 'traffic-rules', 'mock-da-3', 26, 'The light is red and there is an empty space between the stop line and the junction. Where do you wait?', 'Lampu merah dan ada ruang kosong antara garisan berhenti dengan persimpangan. Di manakah anda perlu menunggu?', '["Just beyond the stop line","At the edge of the junction","Behind the stop line","In the empty space"]'::jsonb, '["Sejurus selepas garisan berhenti","Di tepi persimpangan","Di belakang garisan berhenti","Di ruang kosong itu"]'::jsonb, 2, 'Stop behind the white line when facing a red signal. Keep the area ahead of it clear.', 'Berhenti di belakang garisan putih apabila lampu merah. Pastikan kawasan di hadapan garisan itu tidak terhalang.', NULL, 'KPP Kelas D Automatik, PDF page 70'),
  ('4f5ced06-4a78-5f07-b97c-798401efd3b6'::uuid, 'traffic-rules', 'mock-da-3', 27, 'The light changes to green while a vehicle is still clearing the junction. What should you do?', 'Lampu bertukar hijau ketika sebuah kenderaan masih belum keluar dari persimpangan. Apakah tindakan anda?', '["Proceed when the junction is clear","Proceed along the edge of the lane","Proceed when the driver behind signals","Proceed and let the other vehicle stop"]'::jsonb, '["Teruskan apabila persimpangan lapang","Teruskan di tepi lorong","Teruskan apabila pemandu di belakang memberi isyarat","Teruskan dan biarkan kenderaan lain berhenti"]'::jsonb, 0, 'A green light lets you proceed when it is safe. Check that the junction is clear first.', 'Lampu hijau membenarkan anda meneruskan perjalanan apabila selamat. Pastikan persimpangan lapang dahulu.', NULL, 'KPP Kelas D Automatik, PDF page 70'),
  ('2d2e3ea8-9bd3-521e-923d-d369e5341dc3'::uuid, 'traffic-rules', 'mock-da-3', 28, 'You want to go straight. The main signal is red and a green arrow points right. What should you do?', 'Anda hendak bergerak lurus. Lampu utama merah dan anak panah hijau menunjuk ke kanan. Apakah tindakan anda?', '["Wait for a straight-ahead signal","Follow right-turn traffic straight","Proceed straight if the road is clear","Move forward into the junction and wait"]'::jsonb, '["Tunggu isyarat untuk bergerak lurus","Ikut trafik belok kanan secara lurus","Teruskan jika laluan lurus lapang","Maju ke dalam simpang dan tunggu"]'::jsonb, 0, 'A green arrow applies to the direction it points. If you are going straight, wait for the signal that applies to you.', 'Anak panah hijau terpakai pada arah yang ditunjukkan. Jika anda hendak terus, tunggu isyarat yang terpakai untuk anda.', NULL, 'KPP Kelas D Automatik, PDF page 70'),
  ('7f1c604f-6e96-561e-9f5f-32b376817492'::uuid, 'traffic-rules', 'mock-da-3', 29, 'You have priority at a junction. An ambulance approaches with its siren sounding. Who should go first?', 'Anda mempunyai keutamaan di persimpangan. Sebuah ambulans menghampiri dengan siren berbunyi. Siapakah patut bergerak dahulu?', '["The vehicle with the green light","The vehicle already at the line","The vehicle approaching from the right","The ambulance with its siren on"]'::jsonb, '["Kenderaan yang mendapat lampu hijau","Kenderaan yang sudah tiba di garisan","Kenderaan yang menghampiri dari kanan","Ambulans yang membunyikan siren"]'::jsonb, 3, 'Give priority to an ambulance sounding its siren even when you normally have right of way.', 'Beri keutamaan kepada ambulans yang membunyikan siren walaupun anda biasanya mempunyai hak laluan.', NULL, 'KPP Kelas D Automatik, PDF page 89'),
  ('d35fb22d-d987-5583-a758-a5a9254ccc98'::uuid, 'traffic-rules', 'mock-da-3', 30, 'You are closing on a slow car near the top of a hill. When is it appropriate to consider passing?', 'Anda menghampiri kereta perlahan berhampiran puncak bukit. Bilakah anda boleh mempertimbangkan untuk memotong?', '["While both cars are still climbing","As the car reaches the crest","After the view beyond the crest clears","As soon as the car moves slightly left"]'::jsonb, '["Semasa kedua-dua kereta masih mendaki","Ketika kereta itu tiba di puncak","Selepas pandangan melepasi puncak jelas","Sebaik sahaja kereta itu bergerak sedikit ke kiri"]'::jsonb, 2, 'Avoid overtaking at a hill crest. Wait for a clear view of oncoming traffic and a lawful place to pass.', 'Elakkan memotong di puncak bukit. Tunggu sehingga trafik dari arah bertentangan dapat dilihat dengan jelas dan anda berada di tempat yang membenarkan memotong.', NULL, 'KPP Kelas D Automatik, PDF page 106'),
  ('b32e5dd0-7aac-5799-afb2-40a32de38c2e'::uuid, 'traffic-rules', 'mock-da-3', 31, 'A car ahead slows just before a pedestrian crossing without lights. What should you do?', 'Kereta di hadapan memperlahankan kenderaan sejurus sebelum lintasan pejalan kaki tanpa lampu isyarat. Apakah tindakan anda?', '["Ease off and prepare to stop","Sound the horn and move alongside","Pass if the opposite lane is empty","Maintain speed until you see a person"]'::jsonb, '["Perlahankan kenderaan dan bersedia untuk berhenti","Bunyikan hon dan bergerak ke sisi kereta","Potong jika lorong bertentangan kosong","Kekalkan kelajuan sehingga nampak seseorang"]'::jsonb, 0, 'Slow down at an unsignalised crossing and stop if needed to let pedestrians cross. Do not overtake there.', 'Perlahankan kenderaan di lintasan tanpa lampu isyarat dan berhenti jika perlu untuk memberi laluan. Jangan memotong di lintasan itu.', NULL, 'KPP Kelas D Automatik, PDF page 72'),
  ('ece34303-7fee-5999-8e2b-fbe549790858'::uuid, 'traffic-rules', 'mock-da-3', 32, 'The car behind is following much too closely. Which change gives you more time to slow gently?', 'Kereta di belakang mengekori terlalu rapat. Perubahan manakah memberi anda lebih masa untuk memperlahankan kenderaan secara beransur-ansur?', '["Move closer to the car ahead","Leave more space ahead","Keep the same gap ahead","Speed up to close the gap"]'::jsonb, '["Dekati kereta di hadapan","Tinggalkan lebih ruang di hadapan","Kekalkan jarak yang sama di hadapan","Tambah kelajuan untuk merapatkan jarak"]'::jsonb, 1, 'Use a longer following gap when tailgated. A four-second gap ahead gives you more room to respond without sudden braking.', 'Kekalkan jarak mengekori lebih panjang apabila diekori terlalu rapat. Jarak empat saat memberi lebih ruang untuk bertindak tanpa membrek secara tiba-tiba.', NULL, 'KPP Kelas D Automatik, PDF page 102'),
  ('51c385a6-7c8a-5513-b237-7e32d9924d2d'::uuid, 'traffic-rules', 'mock-da-3', 33, 'Why should you leave a longer gap when towing a load?', 'Mengapakah anda perlu mengekalkan jarak lebih panjang apabila menarik beban?', '["The extra weight needs more stopping room","The trailer increases your view ahead","The load makes the engine turn faster","The trailer makes the car steer more sharply"]'::jsonb, '["Berat tambahan memerlukan ruang berhenti lebih jauh","Treler meluaskan pandangan ke hadapan","Beban membuat enjin berpusing lebih laju","Treler menyebabkan kereta membelok lebih tajam"]'::jsonb, 0, 'Allow more time and space to stop the combined weight of the car and load.', 'Sediakan lebih masa dan ruang untuk memberhentikan gabungan berat kereta dan beban.', NULL, 'KPP Kelas D Automatik, PDF page 104'),
  ('78109992-b64a-5cca-8120-c47e3a817eff'::uuid, 'traffic-rules', 'mock-da-3', 34, 'Traffic beyond a yellow box has stopped and there is nowhere to clear the box. Where should you wait?', 'Trafik selepas petak kuning telah berhenti dan tiada ruang untuk keluar dari petak. Di manakah anda patut menunggu?', '["Just inside the box","Before the box","Beside the first car inside the box","At the centre of the box"]'::jsonb, '["Sejurus di dalam petak","Sebelum petak","Di sisi kereta pertama di dalam petak","Di tengah petak"]'::jsonb, 1, 'Wait until there is room to cross without stopping in the yellow box and blocking other traffic.', 'Tunggu sehingga ada ruang untuk melintas tanpa berhenti di dalam petak kuning dan menghalang trafik lain.', NULL, 'KPP Kelas D Automatik, PDF page 73'),
  ('e2b1998a-e6bf-55ba-8ba2-1b097c10b951'::uuid, 'traffic-rules', 'mock-da-3', 35, 'At roadworks, the controller displays the stop side of a paddle. The temporary lane is empty. What should you do?', 'Di zon kerja jalan, pengawal menunjukkan sisi berhenti pada papan. Lorong sementara lapang. Apakah tindakan anda?', '["Wait for the controller to release you","Follow the last car through","Enter slowly and watch the controller","Move into the lane and wait there"]'::jsonb, '["Tunggu arahan pengawal untuk bergerak","Ikut kereta terakhir yang melalui lorong","Masuk perlahan sambil memerhati pengawal","Masuk ke lorong dan tunggu di situ"]'::jsonb, 0, 'Follow the instructions of the person controlling traffic through the roadworks. Stop when directed.', 'Patuhi arahan petugas yang mengawal trafik di kawasan kerja jalan. Berhenti apabila diarahkan.', NULL, 'KPP Kelas D Automatik, PDF page 69'),
  ('ea155566-0a32-5b4a-a266-042df9738500'::uuid, 'traffic-rules', 'mock-da-3', 36, 'A passenger wants to be picked up beside a reserved bus-and-taxi lane. Which location should you use?', 'Penumpang mahu diambil berhampiran lorong khas bas dan teksi. Lokasi manakah patut digunakan?', '["A permitted pickup point","The bus stop inside the reserved lane","The live lane beside the reserved lane","The line where the reserved lane starts"]'::jsonb, '["Tempat mengambil penumpang yang dibenarkan","Perhentian bas dalam lorong khas","Lorong trafik di sebelah lorong khas","Garisan permulaan lorong khas"]'::jsonb, 0, 'The bus-and-taxi lane is reserved. A private car should use a permitted pickup point outside it.', 'Lorong bas dan teksi dikhaskan untuk pengangkutan awam. Kereta persendirian perlu menggunakan tempat mengambil penumpang yang dibenarkan di luar lorong itu.', NULL, 'KPP Kelas D Automatik, PDF page 72'),
  ('970cd019-18ac-51a9-9ec5-5609f6889aa7'::uuid, 'traffic-rules', 'mock-da-3', 37, 'An oncoming car drifts into your lane. Which early warning can you give while responding safely?', 'Kereta dari arah bertentangan memasuki lorong anda. Apakah amaran awal yang boleh diberikan sambil bertindak dengan selamat?', '["Flash the headlights briefly","Turn on the right indicator","Turn on the left indicator","Switch off the headlights briefly"]'::jsonb, '["Kelipkan lampu hadapan","Hidupkan isyarat kanan","Hidupkan isyarat kiri","Padamkan lampu hadapan seketika"]'::jsonb, 0, 'A brief flash or horn can warn the oncoming driver. Keep control and act quickly to avoid a collision.', 'Kelipan lampu atau bunyi hon yang singkat boleh memberi amaran kepada pemandu dari arah bertentangan. Kekalkan kawalan dan bertindak segera untuk mengelakkan perlanggaran.', NULL, 'KPP Kelas D Automatik, PDF page 107'),
  ('a9d9b71b-7c6c-51b8-a468-3d79307ad303'::uuid, 'traffic-rules', 'mock-da-3', 38, 'You miss your turn and the next junction displays a no-U-turn sign. How should you get back?', 'Anda terlepas belokan dan simpang seterusnya memaparkan tanda larangan pusingan U. Bagaimanakah anda patut kembali?', '["Continue to a permitted turning point","Use the junction when no one is coming","Use the gap at the junction before the lights","Wait for a green signal at that junction"]'::jsonb, '["Teruskan ke tempat berpusing yang dibenarkan","Gunakan simpang apabila tiada trafik datang","Gunakan ruang di simpang sebelum lampu isyarat","Tunggu lampu hijau di simpang itu"]'::jsonb, 0, 'The prohibition still applies when the road is empty. Turn back only where it is permitted and safe.', 'Larangan masih terpakai walaupun jalan kosong. Patah balik hanya di tempat yang dibenarkan dan selamat.', NULL, 'KPP Kelas D Automatik, PDF page 56'),
  ('7f9a0952-1fac-591d-8ab9-3c0506900fef'::uuid, 'traffic-rules', 'mock-da-3', 39, 'A continuous white line is next to your lane and a broken white line is next to the opposite lane. Who may cross the lines to pass if safe?', 'Garisan putih berterusan berada di sisi lorong anda dan garisan putih putus-putus di sisi lorong bertentangan. Siapakah boleh melintasi garisan untuk memotong jika selamat?', '["Drivers in your lane only","Drivers in the opposite lane only","Drivers in either lane","Drivers in neither lane"]'::jsonb, '["Pemandu di lorong anda sahaja","Pemandu di lorong bertentangan sahaja","Pemandu di kedua-dua lorong","Tiada pemandu di kedua-dua lorong"]'::jsonb, 1, 'With a solid line and a broken line together, only traffic next to the broken line may cross to overtake when safe.', 'Apabila garisan berterusan dan putus-putus bersebelahan, hanya trafik di sisi garisan putus-putus boleh melintas untuk memotong jika selamat.', NULL, 'KPP Kelas D Automatik, PDF page 71'),
  ('06c70a14-f75c-5c66-8e6d-f19b1357bb28'::uuid, 'traffic-rules', 'mock-da-3', 40, 'You are already committed to one exit lane and a painted chevron area separates it from the branch you want. Where should you go?', 'Anda sudah berada di lorong keluar dan kawasan chevron memisahkannya daripada cabang yang dikehendaki. Ke manakah anda patut pergi?', '["Follow your current exit and reroute","Stop before the chevrons and wait","Merge across the marked area slowly","Reverse to the split when it is clear"]'::jsonb, '["Ikut susur semasa dan cari laluan lain","Berhenti sebelum chevron dan tunggu","Masuk perlahan merentasi kawasan bertanda","Undur ke percabangan apabila lapang"]'::jsonb, 0, 'Do not enter the chevron-marked area. Stay in your lane and change your route safely later.', 'Jangan masuk ke kawasan bercorak chevron. Kekal di lorong anda dan ubah laluan dengan selamat kemudian.', NULL, 'KPP Kelas D Automatik, PDF page 73'),
  ('cd0dccc3-4f50-5092-9c9e-92b83eade37a'::uuid, 'safety-principles', 'mock-da-3', 41, 'Which finding means a wiper blade may leave water on the windscreen?', 'Penemuan manakah menunjukkan bilah pengelap mungkin meninggalkan air pada cermin?', '["The rubber bends easily","The edge has small splits","The edge lies flat on the glass","The blade follows the glass curve"]'::jsonb, '["Getah mudah melentur","Tepi bilah ada rekahan kecil","Tepi bilah rata pada cermin","Bilah mengikut lengkung cermin"]'::jsonb, 1, 'Hardened, cracked or torn blade rubber may leave water behind or scratch the glass.', 'Getah bilah yang keras, retak atau koyak mungkin meninggalkan air atau mencalarkan cermin.', NULL, 'KPP Kelas DA Automatik, PDF 225'),
  ('74b123fe-8941-5478-bf24-dafbe9ef0856'::uuid, 'safety-principles', 'mock-da-3', 42, 'Where does the curriculum say to look for the car manufacturer’s recommended tyre inflation?', 'Di manakah kurikulum menyatakan anda boleh melihat cadangan pengeluar tentang angin tayar kereta?', '["On the tyre tread label","On the wheel nut cap","On the driver’s door label","On the windscreen sticker"]'::jsonb, '["Pada label bunga tayar","Pada penutup nat roda","Pada label pintu pemandu","Pada pelekat cermin hadapan"]'::jsonb, 2, 'Look for the manufacturer’s tyre pressure label on the side of the driver’s door.', 'Cari label tekanan angin tayar pengeluar di bahagian tepi pintu pemandu.', NULL, 'KPP Kelas DA Automatik, PDF 224'),
  ('d6e04323-219c-5381-b3f7-5c34ef7f4f91'::uuid, 'safety-principles', 'mock-da-3', 43, 'Which tyre fails the visual condition check even if its tread is deep?', 'Tayar manakah gagal pemeriksaan fizikal walaupun bunganya masih dalam?', '["A tyre with even wear","A tyre with deep grooves","A tyre with mould marks","A tyre with a bulge"]'::jsonb, '["Tayar yang haus sekata","Tayar dengan alur dalam","Tayar dengan kesan acuan","Tayar yang menggelembung"]'::jsonb, 3, 'During the visual inspection, check that tyres are free from bulges, cracks and tears.', 'Pastikan tayar tidak menggelembung, merekah atau koyak semasa pemeriksaan.', NULL, 'KPP Kelas DA Automatik, PDF 224'),
  ('d47615dc-308f-5233-a91d-5c6e05d77380'::uuid, 'safety-principles', 'mock-da-3', 44, 'A workshop finds that the wheel angles are out of specification. Which service addresses that problem?', 'Bengkel mendapati sudut roda tidak mengikut spesifikasi. Servis manakah membetulkan masalah itu?', '["Wheel alignment","Wheel balancing","Brake adjustment","Wheel bearing service"]'::jsonb, '["Penjajaran roda","Pengimbangan roda","Pelarasan brek","Servis galas roda"]'::jsonb, 0, 'Correct wheel alignment helps the tyre tread wear evenly. The book describes wheel balancing separately as a way to reduce vibration.', 'Penjajaran roda yang betul membantu bunga tayar haus secara sekata. Pengimbangan roda pula membantu mengurangkan gegaran.', NULL, 'KPP Kelas DA Automatik, PDF 224'),
  ('da25cefc-bd45-5cb4-a117-046711442b74'::uuid, 'safety-principles', 'mock-da-3', 45, 'Where should the engine oil level sit on the dipstick?', 'Di manakah paras minyak enjin sepatutnya berada pada batang penyukat?', '["Below the lower mark","Between the two marks","Above the upper mark","Exactly on the lower mark"]'::jsonb, '["Di bawah tanda bawah","Antara kedua-dua tanda","Di atas tanda atas","Tepat pada tanda bawah"]'::jsonb, 1, 'The book says to check that the level is between the minimum and maximum marks.', 'Buku menyatakan paras minyak perlu berada antara tanda minimum dan maksimum.', NULL, 'KPP Kelas DA Automatik, PDF 228'),
  ('b1ae371d-7694-5333-ad8d-39023090091d'::uuid, 'safety-principles', 'mock-da-3', 46, 'The washer reservoir is accessible under the bonnet. Which check can you do there?', 'Takungan pencuci boleh dicapai di bawah bonet. Pemeriksaan manakah boleh dibuat di situ?', '["Check whether fluid needs topping up","Check whether fluid reaches the glass","Check how far the fluid sprays","Check which spray jet is blocked"]'::jsonb, '["Semak sama ada cecair perlu ditambah","Semak sama ada cecair sampai ke kaca","Semak sejauh mana cecair menyembur","Semak muncung semburan yang tersumbat"]'::jsonb, 0, 'Check that the washer reservoir contains enough fluid.', 'Pastikan cecair dalam tangki pencuci cermin mencukupi.', NULL, 'KPP Kelas DA Automatik, PDF 229'),
  ('59c4d03d-5a38-5d12-8ce1-7745d329dfa1'::uuid, 'safety-principles', 'mock-da-3', 47, 'Which hose condition should you report during a check under the bonnet?', 'Keadaan hos manakah yang perlu dilaporkan semasa pemeriksaan di bawah bonet?', '["A smooth curved route","An intact hose clamp","A dry outer surface","A crack or a bulge"]'::jsonb, '["Laluan melengkung licin","Pengapit hos masih elok","Permukaan luar kering","Rekah atau bengkak"]'::jsonb, 3, 'Check that hoses have no leaks, cracks or swelling.', 'Pastikan hos tidak bocor, merekah atau mengembang.', NULL, 'KPP Kelas DA Automatik, PDF 230'),
  ('73708c9b-714f-54ac-a942-b4d164363e6d'::uuid, 'safety-principles', 'mock-da-3', 48, 'When replacing a tyre, which tool loosens the nuts before you remove the wheel?', 'Ketika mengganti tayar, alat manakah melonggarkan nat sebelum roda ditanggalkan?', '["A wheel brace","A tyre lever","A pressure gauge","A tow hook"]'::jsonb, '["Sepana roda","Tuil tayar","Tolok tekanan","Cangkuk tunda"]'::jsonb, 0, 'The book includes a wheel-nut wrench among the emergency tools to check in the boot.', 'Buku menyenaraikan pembuka nat roda antara peralatan kecemasan yang perlu diperiksa dalam but.', NULL, 'KPP Kelas DA Automatik, PDF 227'),
  ('22730cbd-e4ac-51e4-80e5-881d96a170f4'::uuid, 'safety-principles', 'mock-da-3', 49, 'When reversing direction in the automatic car, what should you do before selecting the next gear?', 'Apabila menukar arah gerakan kereta automatik, apakah yang perlu dibuat sebelum memilih gear seterusnya?', '["Slow down and keep rolling","Stop and hold the brake","Coast in Neutral first","Use the accelerator lightly"]'::jsonb, '["Perlahankan dan terus bergerak","Berhenti dan tahan brek","Biarkan kereta meluncur dalam N","Tekan pemecut sedikit"]'::jsonb, 1, 'Bring the car to a complete stop and press the foot brake fully before selecting the next gear.', 'Berhenti sepenuhnya dan tekan pedal brek sepenuhnya sebelum memilih gear seterusnya.', NULL, 'KPP Kelas DA Automatik, PDF 215'),
  ('5dafe0d0-c373-595c-b1c8-be8d8b919cc3'::uuid, 'safety-principles', 'mock-da-3', 50, 'What can you check from the MIN and MAX marks on the brake reservoir?', 'Apakah yang boleh disemak melalui tanda MIN dan MAX pada takungan brek?', '["Whether the fluid level is in range","Whether the fluid needs replacement","Whether the fluid has reached operating temperature","Whether the brakes are holding pressure"]'::jsonb, '["Sama ada paras cecair dalam julat","Sama ada cecair perlu diganti","Sama ada cecair mencapai suhu operasi","Sama ada brek mengekalkan tekanan"]'::jsonb, 0, 'Check that the brake fluid is between the minimum and maximum marks.', 'Pastikan paras cecair brek berada antara tanda minimum dan maksimum.', NULL, 'KPP Kelas DA Automatik, PDF 228'),
  ('5a06c2c1-149a-5d26-ac2a-6a4966ecc76b'::uuid, 'road-signs', 'mock-d-1', 1, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Pass on the right","Pass on either side","Pass on the left","Keep left unless overtaking"]'::jsonb, '["Lalu di sebelah kanan","Lalu di mana-mana sisi","Lalu di sebelah kiri","Ikut kiri kecuali memotong"]'::jsonb, 2, 'This sign means pass on the left.', 'Papan tanda ini bermaksud lalu di sebelah kiri.', '/signs/24dc89f9e7127cca.svg', 'KPP General PDF page 64'),
  ('f21db3af-a64b-5828-b079-f62a81b4fcde'::uuid, 'road-signs', 'mock-d-1', 2, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Pass on the left","Pass on either side","Keep left unless overtaking","Pass on the right"]'::jsonb, '["Lalu di sebelah kiri","Lalu di mana-mana sisi","Ikut kiri kecuali memotong","Lalu di sebelah kanan"]'::jsonb, 3, 'This sign means pass on the right.', 'Papan tanda ini bermaksud lalu di sebelah kanan.', '/signs/a50c8dd8a202a25e.svg', 'KPP General PDF page 64'),
  ('304f004f-6b44-5869-add9-fd8753b997ad'::uuid, 'road-signs', 'mock-d-1', 3, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Pass on either side","Pass on the right","Pass on the left","Keep left unless overtaking"]'::jsonb, '["Lalu di mana-mana sisi","Lalu di sebelah kanan","Lalu di sebelah kiri","Ikut kiri kecuali memotong"]'::jsonb, 0, 'This sign means pass on either side.', 'Papan tanda ini bermaksud lalu di mana-mana sisi.', '/signs/6103dff69316bf86.svg', 'KPP General PDF page 64'),
  ('886359aa-809b-5ca4-b4c0-25dc59c57b45'::uuid, 'road-signs', 'mock-d-1', 5, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Lane for bicycles","Lane for trishaws","Lane for motorcycles","Lane for taxis"]'::jsonb, '["Lorong untuk basikal","Lorong untuk beca","Lorong untuk motosikal","Lorong untuk teksi"]'::jsonb, 2, 'This sign means lane for motorcycles.', 'Papan tanda ini bermaksud lorong untuk motosikal.', '/signs/e0389a069e72ed52.png', 'KPP General PDF page 65'),
  ('9d933499-b70d-543e-8f82-34074e421aa3'::uuid, 'road-signs', 'mock-d-1', 6, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Lane for trishaws","Lane for motorcycles","Lane for taxis","Lane for bicycles"]'::jsonb, '["Lorong untuk beca","Lorong untuk motosikal","Lorong untuk teksi","Lorong untuk basikal"]'::jsonb, 3, 'This sign means lane for bicycles.', 'Papan tanda ini bermaksud lorong untuk basikal.', '/signs/e86785fec1877d75.png', 'KPP General PDF page 65'),
  ('1c538725-c200-5705-89a4-2d1946b6812b'::uuid, 'road-signs', 'mock-d-1', 7, 'What does this sign prohibit?', 'Apakah larangan pada papan tanda ini?', '["No overtaking","No stopping","No left turn","No right turn"]'::jsonb, '["Dilarang memotong","Dilarang berhenti","Dilarang membelok ke kiri","Dilarang membelok ke kanan"]'::jsonb, 0, 'This sign means no overtaking.', 'Papan tanda ini bermaksud dilarang memotong.', '/signs/2f019822b1b9e39f.svg', 'KPP General PDF page 57'),
  ('0aa956e6-6eff-5100-857e-584b506334df'::uuid, 'road-signs', 'mock-d-1', 8, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Lane for bicycles","Lane for trishaws","Lane for buses","Lane for taxis"]'::jsonb, '["Lorong untuk basikal","Lorong untuk beca","Lorong untuk bas","Lorong untuk teksi"]'::jsonb, 1, 'This sign means lane for trishaws.', 'Papan tanda ini bermaksud lorong untuk beca.', '/signs/fad437bbc08b75fa.png', 'KPP General PDF page 65'),
  ('16b00db2-d98e-5777-8111-923f6f98e106'::uuid, 'road-signs', 'mock-d-1', 13, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Medical clinic","Public telephone","Hospital","Bus stop"]'::jsonb, '["Klinik perubatan","Telefon awam","Hospital","Perhentian bas"]'::jsonb, 2, 'This sign means hospital.', 'Papan tanda ini bermaksud hospital.', '/signs/dde5874c6044c5f3.svg', 'KPP General PDF page 67'),
  ('ad2f0084-8195-547f-acaa-1b5cc7c36005'::uuid, 'road-signs', 'mock-d-1', 15, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Vehicle parking","Medical clinic","JPJ weighing station","Public telephone"]'::jsonb, '["Tempat letak kenderaan","Klinik perubatan","Stesen timbang JPJ","Telefon awam"]'::jsonb, 0, 'This sign means vehicle parking.', 'Papan tanda ini bermaksud tempat letak kenderaan.', '/signs/f6459f68e216bc5d.svg', 'KPP General PDF page 67'),
  ('82e7240f-24fe-5ca7-ace0-fae123dd2419'::uuid, 'traffic-rules', 'mock-d-1', 16, 'Your mirrors are clear before you move into the next lane. What final check covers the area beside the car?', 'Cermin menunjukkan laluan lapang sebelum anda berpindah ke lorong sebelah. Apakah semakan terakhir meliputi kawasan di sisi kereta?', '["Glance over the shoulder toward that lane","Look again in the interior mirror","Check the centre of the windscreen","Watch the car immediately ahead"]'::jsonb, '["Toleh ke bahu menghala ke lorong itu","Lihat semula cermin pandang belakang","Periksa bahagian tengah cermin hadapan","Perhatikan kereta tepat di hadapan"]'::jsonb, 0, 'A vehicle on the right can be hidden from both mirrors. Check that area directly before moving.', 'Kenderaan di kanan boleh terlindung daripada kedua-dua cermin. Periksa kawasan itu secara langsung sebelum bergerak.', NULL, 'KPP_D_Manual.pdf PDF page 99'),
  ('95e55c3c-d16e-51cc-83b3-28e236df2ccd'::uuid, 'traffic-rules', 'mock-d-1', 17, 'Why leave space before pulling in ahead of a lorry?', 'Mengapa perlu tinggalkan ruang sebelum masuk ke hadapan lori?', '["It needs more stopping room","It needs more turning room","It needs more passing room","It needs more merging room"]'::jsonb, '["Lori perlu ruang berhenti lebih panjang","Lori perlu ruang membelok lebih luas","Lori perlu ruang memotong lebih luas","Lori perlu ruang mencelah lebih luas"]'::jsonb, 0, 'Cutting in reduces the space the heavy vehicle has to stop.', 'Memotong masuk secara rapat mengurangkan ruang lori untuk berhenti.', NULL, 'KPP_D_Manual.pdf PDF page 89'),
  ('1467f7d9-658b-5873-99f4-701e1b227214'::uuid, 'traffic-rules', 'mock-d-1', 18, 'A child is cycling ahead near the kerb. What movement should you expect?', 'Seorang kanak-kanak berbasikal di hadapan berhampiran bebendul. Apakah pergerakan yang perlu dijangka?', '["Stopping at the kerb","Moving onto the footpath","Moving into your lane","Turning into a driveway"]'::jsonb, '["Berhenti di tepi bebendul","Bergerak masuk ke laluan pejalan kaki","Bergerak masuk ke lorong anda","Membelok masuk ke halaman"]'::jsonb, 2, 'A cyclist may turn out of their line. Leave room and be prepared to slow.', 'Penunggang basikal mungkin beralih daripada laluannya. Tinggalkan ruang dan bersedia untuk memperlahankan kenderaan.', NULL, 'KPP_D_Manual.pdf PDF page 85'),
  ('c895334e-5f52-53b2-8400-4946214821bd'::uuid, 'traffic-rules', 'mock-d-1', 19, 'A schoolchild steps onto the road with no crossing guard present. What do you do?', 'Seorang murid melangkah ke jalan tanpa pengawal lintasan. Apakah tindakan anda?', '["Slow and pass behind the child","Stop and let the child cross","Stop only when signalled","Slow and signal the child to wait"]'::jsonb, '["Perlahankan kenderaan dan lalu di belakang murid","Berhenti dan beri laluan kepada murid","Berhenti hanya jika diberi isyarat","Perlahankan kenderaan dan isyaratkan murid supaya menunggu"]'::jsonb, 1, 'Stop as the child steps onto the road. Wait until the crossing is clear.', 'Berhenti apabila murid melangkah ke jalan. Tunggu sehingga lintasan kosong.', NULL, 'KPP_D_Manual.pdf PDF page 81'),
  ('20c906d5-d21a-53df-9f44-fb971e33fd67'::uuid, 'traffic-rules', 'mock-d-1', 20, 'A bus is stopped at the kerb. What can the bus hide from view?', 'Sebuah bas berhenti di tepi jalan. Apakah yang mungkin terlindung di sebalik bas?', '["Drivers joining from a junction","Passengers crossing the road","Cyclists waiting in a side lane","Vehicles turning into a car park"]'::jsonb, '["Pemandu yang keluar dari simpang","Penumpang yang melintas jalan","Penunggang basikal yang menunggu di lorong sisi","Kenderaan yang masuk ke tempat letak kereta"]'::jsonb, 1, 'Passengers may cross from directly in front of or behind the bus, where you cannot see them.', 'Penumpang mungkin melintas dari hadapan atau belakang bas, di tempat yang terlindung daripada pandangan anda.', NULL, 'KPP_D_Manual.pdf PDF page 82'),
  ('193e9038-8ba5-5b51-9e18-afa970fc189e'::uuid, 'traffic-rules', 'mock-d-1', 21, 'An L-plate car ahead keeps slowing. How should you follow?', 'Kereta berpelekat L di hadapan kerap memperlahankan kelajuan. Bagaimanakah anda patut mengekorinya?', '["Leave room for a sudden stop","Close the gap to discourage braking","Follow closer at low speed","Use the horn to keep it moving"]'::jsonb, '["Tinggalkan ruang jika kereta berhenti mengejut","Rapatkan jarak supaya kereta kurang membrek","Ikut lebih rapat pada kelajuan rendah","Bunyikan hon supaya kereta terus bergerak"]'::jsonb, 0, 'A learner may stop unexpectedly. Leave a gap and give them time.', 'Pemandu pelajar mungkin berhenti tanpa dijangka. Tinggalkan jarak dan beri mereka masa.', NULL, 'KPP_D_Manual.pdf PDF page 87'),
  ('f9d20c8a-2226-5386-b298-6af30e429079'::uuid, 'traffic-rules', 'mock-d-1', 22, 'You have right of way when an ambulance approaches with its siren on. What should you do?', 'Anda mempunyai hak laluan apabila ambulans menghampiri dengan siren berbunyi. Apakah tindakan anda?', '["Keep going before it arrives","Give the ambulance room","Wait for its driver to wave","Hold your lane and speed"]'::jsonb, '["Teruskan sebelum ambulans tiba","Beri ruang kepada ambulans","Tunggu pemandunya melambai","Kekalkan lorong dan kelajuan"]'::jsonb, 1, 'Give priority to an emergency vehicle sounding its siren, even if you ordinarily have right of way.', 'Beri keutamaan kepada kenderaan kecemasan yang membunyikan siren walaupun anda biasanya mempunyai hak laluan.', NULL, 'KPP_D_Manual.pdf PDF page 90'),
  ('3c16da64-8eae-5f5f-b6de-38cd1ec8e794'::uuid, 'traffic-rules', 'mock-d-1', 23, 'What can you miss when the car radio is too loud?', 'Apakah yang mungkin terlepas perhatian jika radio kereta terlalu kuat?', '["Sounds from outside","Changes in engine speed","Dashboard warning symbols","Lights from other vehicles"]'::jsonb, '["Bunyi dari luar","Perubahan kelajuan enjin","Simbol amaran papan pemuka","Lampu kenderaan lain"]'::jsonb, 0, 'Listening is part of observing the road. Set the radio low enough to hear outside sounds.', 'Mendengar ialah sebahagian daripada pemerhatian. Rendahkan kelantangan radio supaya bunyi di luar dapat didengar.', NULL, 'KPP_D_Manual.pdf PDF page 93'),
  ('407d6e72-fb36-5b1c-ae8a-783d1d836456'::uuid, 'traffic-rules', 'mock-d-1', 24, 'How should a higher driving speed change where you look?', 'Bagaimanakah kelajuan yang lebih tinggi patut mengubah arah tumpuan anda?', '["Look longer in the mirrors","Focus closer to the bonnet","Scan more often to the side","Scan farther down the road"]'::jsonb, '["Lihat cermin lebih lama","Tumpukan lebih dekat dengan bonet","Imbas ke sisi dengan lebih kerap","Imbas lebih jauh ke hadapan"]'::jsonb, 3, 'Speed leaves less time to react, so look farther ahead to spot problems early.', 'Kelajuan mengurangkan masa untuk bertindak. Lihat lebih jauh ke hadapan supaya bahaya dikesan awal.', NULL, 'KPP_D_Manual.pdf PDF page 97'),
  ('7cc7925b-f5eb-5b69-ad75-c05962a895d0'::uuid, 'traffic-rules', 'mock-d-1', 25, 'What makes a good marker for timing a following gap?', 'Apakah penanda yang sesuai untuk mengukur jarak mengekor dengan masa?', '["A cloud above the road","A moving car beside you","A passing motorcycle","A fixed lamp post"]'::jsonb, '["Awan di atas jalan","Kereta yang bergerak di sebelah","Motosikal yang sedang memotong","Tiang lampu yang tetap"]'::jsonb, 3, 'Start counting when the vehicle ahead passes a fixed marker. Compare that with when you pass the same marker.', 'Mula mengira apabila kenderaan di hadapan melepasi penanda tetap. Bandingkan dengan masa anda melepasi penanda yang sama.', NULL, 'KPP_D_Manual.pdf PDF page 101'),
  ('0bec4010-351e-50bb-97be-62685692c347'::uuid, 'traffic-rules', 'mock-d-1', 26, 'A driver is tailgating you. Which gap ahead does the book teach?', 'Pemandu di belakang mengekori anda terlalu rapat. Apakah jarak masa yang diajar untuk ruang di hadapan?', '["Four seconds","One second","Two seconds","Three seconds"]'::jsonb, '["Empat saat","Satu saat","Dua saat","Tiga saat"]'::jsonb, 0, 'Increase the gap in front so you have more time to slow without braking abruptly.', 'Besarkan jarak di hadapan supaya anda mempunyai lebih masa untuk memperlahankan kenderaan tanpa membrek mengejut.', NULL, 'KPP_D_Manual.pdf PDF page 103'),
  ('b9164180-2e05-5157-900e-2e28e2accc77'::uuid, 'traffic-rules', 'mock-d-1', 27, 'Why allow more following distance when towing?', 'Mengapa jarak mengekor perlu ditambah ketika menunda?', '["The extra weight takes more room to stop","The extra length takes more room to turn","The added mirrors widen the blind spot","The tow connection changes the steering angle"]'::jsonb, '["Berat tambahan memerlukan ruang berhenti lebih panjang","Panjang tambahan memerlukan ruang membelok lebih luas","Cermin tambahan meluaskan titik buta","Sambungan tunda mengubah sudut stereng"]'::jsonb, 0, 'The towing vehicle and load need enough time and distance to stop together.', 'Kenderaan dan beban yang ditunda memerlukan masa dan jarak yang mencukupi untuk berhenti bersama.', NULL, 'KPP_D_Manual.pdf PDF page 105'),
  ('fd7e9440-bd2d-59c6-b070-df6639a0c68b'::uuid, 'traffic-rules', 'mock-d-1', 28, 'A car ahead is slow near the crest of a hill. When should you pass?', 'Kereta di hadapan bergerak perlahan berhampiran puncak bukit. Bilakah anda patut memotong?', '["Before the crest, when close","After the crest, when clear","At the crest, if well signalled","At the crest, in a lower gear"]'::jsonb, '["Sebelum puncak, apabila sudah rapat","Selepas puncak, apabila laluan jelas","Di puncak, jika sudah memberi isyarat","Di puncak, dengan gear lebih rendah"]'::jsonb, 1, 'Avoid overtaking at a crest because the road beyond it may hide oncoming traffic.', 'Elakkan memotong di puncak bukit kerana kenderaan dari arah bertentangan mungkin terlindung.', NULL, 'KPP_D_Manual.pdf PDF page 107'),
  ('afd41ad7-dd81-54d6-aaa9-caaf93b7e9e3'::uuid, 'traffic-rules', 'mock-d-1', 29, 'The brake pedal drops to the floor on a level road. What can you try first to restore pressure?', 'Pedal brek jatuh ke lantai di jalan rata. Apakah yang boleh dicuba dahulu untuk memulihkan tekanan?', '["Press the clutch pedal","Hold the brake pedal down","Pump the brake pedal","Pull the handbrake fully"]'::jsonb, '["Tekan pedal cekam","Tekan pedal brek tanpa dilepaskan","Pam pedal brek","Tarik brek tangan sepenuhnya"]'::jsonb, 2, 'Pumping may restore hydraulic pressure. If it does not, the book advises a lower gear and gradual handbrake use where safe.', 'Mengepam pedal mungkin memulihkan tekanan hidraulik. Jika gagal, gunakan gear rendah dan tarik brek tangan beransur-ansur apabila selamat.', NULL, 'KPP_D_Manual.pdf PDF page 126'),
  ('d5f085bb-c84b-5fbc-ae90-9e944ab58422'::uuid, 'traffic-rules', 'mock-d-1', 30, 'A tyre bursts while you are driving. What should you do with the controls?', 'Tayar pecah ketika anda memandu. Bagaimanakah anda patut mengawal kenderaan?', '["Hold the wheel and brake hard","Hold the wheel and brake gently","Steer to the edge and brake hard","Accelerate and then steer aside"]'::jsonb, '["Pegang stereng dan brek kuat","Pegang stereng dan brek perlahan","Belok ke tepi dan brek kuat","Pecut dahulu dan kemudian belok ke tepi"]'::jsonb, 1, 'Keep the car stable and slow progressively. Find a flat, safe place to stop.', 'Pastikan kenderaan stabil dan kurangkan kelajuan beransur-ansur. Cari tempat rata dan selamat untuk berhenti.', NULL, 'KPP_D_Manual.pdf PDF page 127'),
  ('ccbcafea-289b-57d5-ad65-4e0291f0999d'::uuid, 'traffic-rules', 'mock-d-1', 31, 'Both headlights fail at night. What should you do next?', 'Kedua-dua lampu hadapan terpadam pada waktu malam. Apakah tindakan seterusnya?', '["Follow another car to your destination","Slow and find a safe place to stop","Hold speed and follow the edge line","Stop immediately in the traffic lane"]'::jsonb, '["Ikut kereta lain hingga ke destinasi","Perlahankan kenderaan dan cari tempat selamat untuk berhenti","Kekalkan kelajuan dan ikut garisan tepi","Berhenti serta-merta di lorong trafik"]'::jsonb, 1, 'Use hazard lights to warn others and get out of moving traffic safely.', 'Gunakan lampu kecemasan untuk memberi amaran dan keluar daripada aliran trafik dengan selamat.', NULL, 'KPP_D_Manual.pdf PDF page 128'),
  ('c529af35-e496-5784-bec5-bbbcdedf8c61'::uuid, 'traffic-rules', 'mock-d-1', 32, 'Your car breaks down on an expressway. Where should passengers wait?', 'Kereta anda rosak di lebuh raya. Di manakah penumpang patut menunggu?', '["Behind the car''s rear lights","Away from moving traffic","Beside the driver''s door","In front of the warning sign"]'::jsonb, '["Di belakang lampu belakang kereta","Jauh daripada aliran trafik","Di sebelah pintu pemandu","Di hadapan tanda amaran"]'::jsonb, 1, 'Move passengers away from traffic. Keep the vehicle''s lights visible to approaching drivers.', 'Bawa penumpang jauh daripada trafik. Pastikan lampu kenderaan dapat dilihat oleh pemandu yang menghampiri.', NULL, 'KPP_D_Manual.pdf PDF page 129'),
  ('5bd55551-f291-5022-bc51-7b154d42c141'::uuid, 'traffic-rules', 'mock-d-1', 33, 'The engine overheats. When may you open the radiator cap?', 'Enjin menjadi terlalu panas. Bilakah penutup radiator boleh dibuka?', '["After the fan stops turning","After the engine stops","After opening the bonnet","After the radiator cools"]'::jsonb, '["Selepas kipas berhenti berpusing","Selepas enjin berhenti","Selepas bonet dibuka","Selepas radiator sejuk"]'::jsonb, 3, 'Stop safely and switch off the engine. Let the radiator cool before opening its cap.', 'Berhenti di tempat selamat dan matikan enjin. Tunggu radiator sejuk sebelum membuka penutupnya.', NULL, 'KPP_D_Manual.pdf PDF page 131'),
  ('0d470150-5a5c-5b7d-a019-3be8f0a4d7e2'::uuid, 'traffic-rules', 'mock-d-1', 34, 'When should you first loosen the wheel nuts during a tyre change?', 'Bilakah nat roda patut dilonggarkan buat kali pertama ketika menukar tayar?', '["After removing the wheel","As the jack starts lifting","Once the wheel is raised","Before lifting the car"]'::jsonb, '["Selepas roda ditanggalkan","Ketika jek mula mengangkat","Sebaik roda terangkat","Sebelum mengangkat kereta"]'::jsonb, 3, 'Break the nuts loose with the wheel on the ground, then lift the vehicle at the correct jacking point.', 'Longgarkan nat ketika roda masih di atas tanah, kemudian angkat kenderaan pada titik jek yang betul.', NULL, 'KPP_D_Manual.pdf PDF page 132'),
  ('e8abaf28-ce1d-5bef-b8ca-c2255db69abf'::uuid, 'traffic-rules', 'mock-d-1', 35, 'When stopping in a queue, what part of the car ahead should still be visible?', 'Apabila berhenti dalam barisan, bahagian manakah pada kereta hadapan yang masih perlu kelihatan?', '["Its rear window","Its rear lamps","Its number plate","Its rear tyres"]'::jsonb, '["Cermin belakangnya","Lampu belakangnya","Plat nombornya","Tayar belakangnya"]'::jsonb, 3, 'Seeing the rear tyres leaves some room to move out if the vehicle ahead cannot move.', 'Jika tayar belakang masih kelihatan, anda mempunyai sedikit ruang untuk keluar jika kenderaan di hadapan tidak dapat bergerak.', NULL, 'KPP_D_Manual.pdf PDF page 134'),
  ('414a3235-50e8-57aa-99fc-3c360e177ee3'::uuid, 'traffic-rules', 'mock-d-1', 36, 'You spot your toll lane late. What should you avoid?', 'Anda lewat menyedari lorong tol yang diperlukan. Apakah yang perlu dielakkan?', '["Switching lanes at the last moment","Slowing on the toll approach","Checking for traffic beside you","Following the lane you are in"]'::jsonb, '["Menukar lorong pada saat akhir","Memperlahankan kenderaan sebelum tol","Memeriksa trafik di sebelah anda","Meneruskan perjalanan di lorong semasa"]'::jsonb, 0, 'Choose the correct lane early. A sudden lane change at the plaza can put you in another driver''s path.', 'Pilih lorong yang betul lebih awal. Pertukaran lorong mengejut di plaza boleh memotong laluan kenderaan lain.', NULL, 'KPP_D_Manual.pdf PDF page 136'),
  ('9236cfee-2560-5e7f-944b-9dff70eb6ddf'::uuid, 'traffic-rules', 'mock-d-1', 37, 'Goats are crossing a village road ahead. What should you do?', 'Kambing sedang melintas di jalan kampung di hadapan. Apakah tindakan anda?', '["Slow and let them cross","Sound the horn and hold speed","Pass behind the nearest animal","Steer around them into the other lane"]'::jsonb, '["Perlahankan kenderaan dan beri laluan","Bunyikan hon dan kekalkan kelajuan","Lalu di belakang haiwan paling hampir","Elak haiwan dengan masuk ke lorong sebelah"]'::jsonb, 0, 'Allow the animals to clear the road. A horn may startle them.', 'Tunggu haiwan selesai melintas. Bunyi hon boleh mengejutkannya.', NULL, 'KPP_D_Manual.pdf PDF page 137'),
  ('e86c4c1a-f1f8-5b1a-97e6-a309f87ec174'::uuid, 'traffic-rules', 'mock-d-1', 38, 'What should you switch on when driving in a tunnel?', 'Apakah yang perlu dihidupkan semasa memandu di dalam terowong?', '["Headlights","Hazard lights","Cabin lights","Rear fog lights"]'::jsonb, '["Lampu hadapan","Lampu kecemasan","Lampu kabin","Lampu kabus belakang"]'::jsonb, 0, 'Visibility is more limited in a tunnel. Use headlights and keep a safe following distance.', 'Penglihatan lebih terhad di dalam terowong. Gunakan lampu hadapan dan kekalkan jarak mengekor yang selamat.', NULL, 'KPP_D_Manual.pdf PDF page 140'),
  ('8998d1f0-497e-5c35-917b-a63bb61ed549'::uuid, 'traffic-rules', 'mock-d-1', 39, 'Rain starts on the expressway. Which lights should you use as you keep driving?', 'Hujan mula turun di lebuh raya. Lampu manakah patut digunakan semasa meneruskan pemanduan?', '["Use the parking lights","Use the hazard lights","Use the headlights","Use the cabin lights"]'::jsonb, '["Gunakan lampu parkir","Gunakan lampu kecemasan","Gunakan lampu hadapan","Gunakan lampu kabin"]'::jsonb, 2, 'Headlights make you more visible. Keep hazard lights for emergencies.', 'Lampu hadapan memudahkan kenderaan dilihat. Gunakan lampu kecemasan apabila berlaku kecemasan.', NULL, 'KPP_D_Manual.pdf PDF page 142'),
  ('c47076ec-ccf1-5efc-b953-37e7ca515603'::uuid, 'traffic-rules', 'mock-d-1', 40, 'You catch up with a car at night. How should you set your headlamps?', 'Anda menghampiri kereta di hadapan pada waktu malam. Bagaimanakah lampu hadapan perlu dilaraskan?', '["Flash full beam continuously","Keep full beam on","Switch to parking lights","Switch to dipped beam"]'::jsonb, '["Kelipkan lampu tinggi berterusan","Kekalkan lampu tinggi","Tukar kepada lampu parkir","Tukar kepada lampu rendah"]'::jsonb, 3, 'Full beam can dazzle the driver ahead through their mirrors.', 'Lampu tinggi boleh menyilaukan pemandu di hadapan melalui cerminnya.', NULL, 'KPP_D_Manual.pdf PDF page 143'),
  ('0f3f3a59-dd8c-5928-bef1-7f5db29b030a'::uuid, 'safety-principles', 'mock-d-1', 41, 'Which licence does the curriculum require for ordinary GDL or PSV applications?', 'Lesen manakah diperlukan untuk permohonan GDL atau PSV biasa mengikut kurikulum ini?', '["A learner driving licence","A competent driving licence","A probationary driving licence","An international driving permit"]'::jsonb, '["Lesen belajar memandu","Lesen memandu kompeten","Lesen memandu percubaan","Permit memandu antarabangsa"]'::jsonb, 1, 'The vocational application requirements list a competent driving licence. The probationary licence exception is for Class C only.', 'Syarat permohonan lesen vokasional menyenaraikan lesen memandu kompeten. Pengecualian untuk lesen percubaan hanya bagi Kelas C.', NULL, 'KPP Kelas DA Automatik, PDF 23'),
  ('dd10c2b6-257e-51f5-b99f-78e13a3ce0a7'::uuid, 'safety-principles', 'mock-d-1', 42, 'A PSV bus applicant has completed the course and wants to book the practical test. Which result is needed first?', 'Pemohon PSV bas telah mengikuti kursus dan ingin menempah ujian amali. Keputusan manakah diperlukan dahulu?', '["A pass in vocational theory","A pass in the motorcar theory test alone","A pass in the ordinary road test","A pass in a driving institute trial run"]'::jsonb, '["Lulus ujian teori vokasional","Lulus ujian teori motokar sahaja","Lulus ujian jalan raya biasa","Lulus percubaan di institut memandu"]'::jsonb, 0, 'Vocational practical tests take place after a theory pass. PSV bus applicants are one of the groups required to take a practical test.', 'Ujian amali lesen vokasional dijalankan selepas lulus ujian teori. Pemohon PSV bas ialah antara kumpulan yang perlu menjalani ujian amali.', NULL, 'KPP Kelas DA Automatik, PDF 24'),
  ('9fa72980-e276-598d-bb03-d2390b005cf0'::uuid, 'safety-principles', 'mock-d-1', 43, 'What does this curriculum say happens to a vocational licence that stays expired for over three years?', 'Apakah yang berlaku kepada lesen vokasional yang tamat tempoh melebihi tiga tahun mengikut kurikulum ini?', '["It is put on probation","It is suspended for a year","It is renewed for a year","It is cancelled"]'::jsonb, '["Lesen diletak dalam percubaan","Lesen digantung setahun","Lesen diperbaharui setahun","Lesen dibatalkan"]'::jsonb, 3, 'The curriculum lists automatic cancellation for a vocational licence that has been expired for more than three years.', 'Kurikulum menyenaraikan pembatalan automatik bagi lesen vokasional yang tamat tempoh melebihi tiga tahun.', NULL, 'KPP Kelas DA Automatik, PDF 25'),
  ('c8334fbe-1055-59ce-a30e-b5445cdcef18'::uuid, 'safety-principles', 'mock-d-1', 44, 'Which part of the driving test assesses practical driving on public roads?', 'Bahagian ujian memandu manakah menilai pemanduan amali di jalan raya?', '["Part III","Part II","Part I","The theory course"]'::jsonb, '["Bahagian III","Bahagian II","Bahagian I","Kursus teori"]'::jsonb, 0, 'Part II tests circuit skills. Part III tests applying safe driving skills on the road.', 'Bahagian II menguji kemahiran di litar. Bahagian III menguji amalan pemanduan selamat di jalan raya.', NULL, 'KPP Kelas DA Automatik, PDF 15'),
  ('61275d89-b960-5e7b-b4aa-6abfa587889a'::uuid, 'safety-principles', 'mock-d-1', 45, 'How long must a candidate wait after failing the circuit and road practical tests before retesting, according to this curriculum?', 'Berapa lamakah calon perlu menunggu selepas gagal ujian amali litar dan jalan raya sebelum mengulang ujian mengikut kurikulum ini?', '["One day","One week","Two weeks","One month"]'::jsonb, '["Satu hari","Satu minggu","Dua minggu","Satu bulan"]'::jsonb, 1, 'The book lists a one-week wait after failing the practical driving test before a candidate can retest.', 'Buku menetapkan tempoh menunggu seminggu selepas gagal ujian amali sebelum calon boleh mengulang ujian.', NULL, 'KPP Kelas DA Automatik, PDF 17'),
  ('ace89bd3-c23a-5828-b8c8-22ce404cec75'::uuid, 'safety-principles', 'mock-d-1', 46, 'Which form records the training the institute confirms for a practical test booking?', 'Borang manakah merekodkan latihan yang disahkan oleh institut untuk tempahan ujian amali?', '["SM4","A copy of the LDL","The theory test result sheet","The practical test booking slip"]'::jsonb, '["SM4","Salinan LDL","Slip keputusan ujian teori","Slip tempahan ujian amali"]'::jsonb, 0, 'The booking requirements include a copy of the learner licence and the SM4 driving training record.', 'Syarat tempahan termasuk salinan lesen belajar memandu dan rekod latihan memandu SM4.', NULL, 'KPP Kelas DA Automatik, PDF 16'),
  ('202c28ad-cd40-5400-b09b-4e3b7ecce501'::uuid, 'safety-principles', 'mock-d-1', 47, 'Where does a licence applicant with a disability obtain the medical verification specified in the handbook?', 'Di manakah pemohon lesen yang mempunyai ketidakupayaan mendapatkan pengesahan kesihatan yang dinyatakan dalam buku panduan?', '["A government clinic","The driving institute","A JPJ testing centre","An optical shop"]'::jsonb, '["Klinik kerajaan","Institut memandu","Pusat ujian JPJ","Kedai optik"]'::jsonb, 0, 'The curriculum requires medical verification by a medical officer at a government health clinic.', 'Kurikulum memerlukan pengesahan oleh pegawai perubatan di klinik kesihatan kerajaan.', NULL, 'KPP Kelas DA Automatik, PDF 11'),
  ('2f695f1f-a6ab-521d-af4f-8dcd70ca4ae6'::uuid, 'safety-principles', 'mock-d-1', 48, 'When are demerit points counted for a scheduled offence?', 'Bilakah mata demerit dikira bagi kesalahan terjadual?', '["When the summons is issued","After payment of the penalty","When the licence is renewed","When a hearing is scheduled"]'::jsonb, '["Apabila saman dikeluarkan","Selepas penalti dibayar","Apabila lesen diperbaharui","Apabila perbicaraan dijadualkan"]'::jsonb, 1, 'The curriculum ties demerit points to a scheduled offence after the compound payment or court fine has been paid.', 'Kurikulum mengaitkan mata demerit bagi kesalahan terjadual dengan pembayaran kompaun atau denda mahkamah.', NULL, 'KPP General, PDF 93'),
  ('20676196-3ae0-58bb-85da-68bc9ee78a60'::uuid, 'safety-principles', 'mock-d-1', 49, 'During the manual hill exercise, what must line up with the yellow marking when you stop?', 'Semasa latihan bukit dengan kereta manual, apakah yang perlu berada pada garisan kuning apabila berhenti?', '["The rear wheels","The front wheels","The front bumper","The driver’s door"]'::jsonb, '["Roda belakang","Roda hadapan","Bampar hadapan","Pintu pemandu"]'::jsonb, 1, 'Stop completely with the front wheels on the yellow line. The textbook then calls for applying the parking brake and signalling.', 'Berhenti sepenuhnya dengan roda hadapan di atas garisan kuning. Kemudian tarik brek tangan dan beri isyarat seperti yang diterangkan.', NULL, 'KPP Kelas D Manual, PDF 278'),
  ('7953a19e-2944-5690-916c-254b49a58142'::uuid, 'safety-principles', 'mock-d-1', 50, 'You are choosing a gear after the traffic ahead slows. What should guide your choice?', 'Anda memilih gear selepas trafik di hadapan memperlahankan kenderaan. Apakah yang patut menentukan pilihan anda?', '["Current speed and power needed","The posted limit and gear last used","The number of lanes and road width","The gear used by the car ahead"]'::jsonb, '["Kelajuan semasa dan kuasa diperlukan","Had tertera dan gear terakhir digunakan","Bilangan lorong dan lebar jalan","Gear yang digunakan oleh kereta di hadapan"]'::jsonb, 0, 'The book says to change gear according to vehicle speed and the power needed.', 'Buku menyatakan gear perlu ditukar mengikut kelajuan dan kuasa yang diperlukan.', NULL, 'KPP Kelas D Manual, PDF 211'),
  ('f052ca3f-a5dd-5a8a-b2ff-1f6cf59b1b59'::uuid, 'road-signs', 'mock-d-2', 3, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Distance to a destination exit","Directions at a junction ahead","Distances to upcoming destinations","Road with no through access"]'::jsonb, '["Jarak ke susur keluar destinasi","Arah di simpang yang akan datang","Jarak ke destinasi seterusnya","Jalan buntu di hadapan"]'::jsonb, 3, 'This sign means road with no through access. The road does not continue through to another route.', 'Papan tanda ini bermaksud jalan buntu di hadapan. Jalan itu tidak bersambung dengan laluan lain.', '/signs/082877f6ec086be6.svg', 'KPP General PDF page 68'),
  ('6b07c05a-06ea-5aef-9232-a77600831110'::uuid, 'road-signs', 'mock-d-2', 4, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Designated U-turn","Designated P-turn","Road with no through access","Directions at a junction ahead"]'::jsonb, '["Tempat pusingan U","Tempat pusingan P","Jalan buntu di hadapan","Arah di simpang yang akan datang"]'::jsonb, 0, 'This sign means designated U-turn. It marks a place to turn around. Give way to oncoming traffic before turning.', 'Papan tanda ini bermaksud tempat pusingan U. Tanda ini menunjukkan tempat untuk berpatah balik. Beri laluan kepada trafik dari arah bertentangan sebelum membelok.', '/signs/8956fe8a103938b3.svg', 'KPP General PDF page 69'),
  ('aa91ea81-df1a-5ae5-a772-f858dedd0001'::uuid, 'road-signs', 'mock-d-2', 8, 'What does this sign prohibit?', 'Apakah larangan pada papan tanda ini?', '["No vehicle entry","No sounding the horn","No left turn","No right turn"]'::jsonb, '["Kenderaan dilarang masuk","Dilarang membunyikan hon","Dilarang membelok ke kiri","Dilarang membelok ke kanan"]'::jsonb, 0, 'This sign means no vehicle entry.', 'Papan tanda ini bermaksud kenderaan dilarang masuk.', '/signs/9a316a4baac9f49a.svg', 'KPP General PDF page 57'),
  ('c64d3043-dc15-57b9-bf64-c5d98af0eae9'::uuid, 'road-signs', 'mock-d-2', 9, 'What does this sign prohibit?', 'Apakah larangan pada papan tanda ini?', '["No parking","No U-turn","No left turn","No right turn"]'::jsonb, '["Dilarang meletak kenderaan","Dilarang membuat pusingan U","Dilarang membelok ke kiri","Dilarang membelok ke kanan"]'::jsonb, 1, 'This sign means no U-turn.', 'Papan tanda ini bermaksud dilarang membuat pusingan U.', '/signs/a299aef5bccc0fca.svg', 'KPP General PDF page 58'),
  ('07c31b1c-8d2a-5931-afd8-7db996e33aa8'::uuid, 'road-signs', 'mock-d-2', 14, 'What does this sign prohibit?', 'Apakah larangan pada papan tanda ini?', '["No vehicle entry","No right turn","No U-turn","No left turn"]'::jsonb, '["Kenderaan dilarang masuk","Dilarang membelok ke kanan","Dilarang membuat pusingan U","Dilarang membelok ke kiri"]'::jsonb, 3, 'You must use a route that does not require turning left here.', 'Gunakan laluan yang tidak memerlukan anda membelok ke kiri di sini.', '/signs/ef495735d6870ce2.svg', 'KPP General PDF page 57'),
  ('7718906d-d7c0-5077-9d43-6988610f1b99'::uuid, 'traffic-rules', 'mock-d-2', 16, 'You pass parked cars in a housing estate. Which situation calls for more room and a lower speed?', 'Anda melalui kereta yang diletakkan di kawasan perumahan. Keadaan manakah memerlukan ruang tambahan dan kelajuan lebih rendah?', '["Children playing near the parked cars","A resident watering a garden behind a fence","A car parked fully inside a driveway","People waiting inside a building"]'::jsonb, '["Kanak-kanak bermain berhampiran kereta","Penduduk menyiram kebun di sebalik pagar","Kereta diletakkan sepenuhnya di laluan masuk","Orang menunggu di dalam bangunan"]'::jsonb, 0, 'Children can appear suddenly between homes and vehicles.', 'Kanak-kanak boleh muncul secara tiba-tiba di celah rumah dan kenderaan.', NULL, 'KPP_D_Manual.pdf PDF page 83'),
  ('f52138df-150b-51f1-8053-64719a1d32dd'::uuid, 'traffic-rules', 'mock-d-2', 17, 'How can bad weather change pedestrian behaviour?', 'Bagaimanakah cuaca buruk boleh mengubah tingkah laku pejalan kaki?', '["They may cross in a hurry","They may wait longer at kerbs","They may walk in larger groups","They may move closer to walls"]'::jsonb, '["Mereka mungkin melintas tergesa-gesa","Mereka mungkin menunggu lebih lama di tepi jalan","Mereka mungkin berjalan dalam kumpulan besar","Mereka mungkin berjalan lebih dekat dengan dinding"]'::jsonb, 0, 'Expect distracted pedestrians while your own visibility is reduced.', 'Jangkakan pejalan kaki kurang memberi perhatian ketika penglihatan anda juga terhad.', NULL, 'KPP_D_Manual.pdf PDF page 84'),
  ('2c49bab8-c0ee-53dc-81a9-18968c1b87d4'::uuid, 'traffic-rules', 'mock-d-2', 18, 'You are about to leave a parking bay. What lets a cyclist see your intention?', 'Anda hendak keluar dari petak parkir. Apakah yang membantu penunggang basikal memahami niat anda?', '["A short flash of the headlights","A clear turn signal","A tap on the brake pedal","A slight movement of the car"]'::jsonb, '["Kelipan singkat lampu hadapan","Isyarat membelok yang jelas","Tekanan ringan pada pedal brek","Pergerakan kecil kereta"]'::jsonb, 1, 'Signal clearly and check that the lane is safe before pulling out.', 'Beri isyarat dengan jelas dan pastikan lorong selamat sebelum keluar.', NULL, 'KPP_D_Manual.pdf PDF page 85'),
  ('06cf2464-dd4f-5348-aa4a-e24ba09a778a'::uuid, 'traffic-rules', 'mock-d-2', 19, 'Why avoid using the horn unnecessarily while passing a motorcyclist?', 'Mengapa perlu elakkan membunyikan hon tanpa perlu ketika memotong motosikal?', '["The rider could swerve","The rider could look ahead","The rider could signal left","The rider could maintain speed"]'::jsonb, '["Penunggang mungkin terpesong","Penunggang mungkin melihat ke hadapan","Penunggang mungkin memberi isyarat kiri","Penunggang mungkin mengekalkan kelajuan"]'::jsonb, 0, 'A horn can startle a rider and cause them to move out of their line.', 'Hon boleh mengejutkan penunggang dan menyebabkan mereka terkeluar daripada laluan.', NULL, 'KPP_D_Manual.pdf PDF page 86'),
  ('1050ef5b-a08d-5e6f-9a8a-1559b029cef0'::uuid, 'traffic-rules', 'mock-d-2', 20, 'A tractor is holding up traffic. What is the best time to pass?', 'Traktor memperlahankan aliran trafik. Bilakah masa terbaik untuk memotong?', '["When the queue draws close","When the tractor is slowest","When a car behind starts passing","When passing is permitted and clear"]'::jsonb, '["Apabila barisan kenderaan semakin rapat","Apabila traktor bergerak paling perlahan","Apabila kereta di belakang mula memotong","Apabila memotong dibenarkan dan laluan jelas"]'::jsonb, 3, 'Follow cautiously until an allowed, safe overtaking opportunity appears.', 'Ikut dengan berhati-hati sehingga terdapat peluang memotong yang dibenarkan dan selamat.', NULL, 'KPP_D_Manual.pdf PDF page 88'),
  ('132bb915-527b-521c-be2d-29a4b8198bd5'::uuid, 'traffic-rules', 'mock-d-2', 21, 'Which blind-spot difference matters when you pass a lorry?', 'Apakah perbezaan titik buta yang penting ketika memotong lori?', '["The lorry has larger blind spots","The lorry has blind spots only behind","The lorry has blind spots only on one side","The lorry has smaller blind spots"]'::jsonb, '["Lori mempunyai titik buta lebih besar","Titik buta lori hanya di belakang","Titik buta lori hanya di sebelah sisi","Lori mempunyai titik buta lebih kecil"]'::jsonb, 0, 'The larger hidden areas make it harder for a lorry driver to see a car alongside.', 'Kawasan terlindung yang lebih besar menyukarkan pemandu lori melihat kereta di sebelahnya.', NULL, 'KPP_D_Manual.pdf PDF page 89'),
  ('f158add8-3c62-5b7f-b878-c99590b74255'::uuid, 'traffic-rules', 'mock-d-2', 22, 'Which information helps decide which hazard needs attention first?', 'Maklumat manakah membantu menentukan bahaya yang perlu ditangani dahulu?', '["How fast you are closing on it","How long you have been driving","How many times you have used the route","How close you are to your destination"]'::jsonb, '["Kelajuan anda menghampirinya","Tempoh anda sudah memandu","Bilangan kali anda menggunakan laluan itu","Jarak anda dari destinasi"]'::jsonb, 0, 'How quickly you approach a hazard affects the time you have to respond.', 'Kelajuan menghampiri bahaya menentukan masa yang ada untuk bertindak.', NULL, 'KPP_D_Manual.pdf PDF page 97'),
  ('1d5217cc-c42b-505a-8d0b-c81221737474'::uuid, 'traffic-rules', 'mock-d-2', 23, 'Which CITO step communicates your intention to nearby road users?', 'Langkah CITO manakah menyampaikan niat anda kepada pengguna jalan raya berhampiran?', '["Isyarat","Cermin","Titik buta","Olah gerak"]'::jsonb, '["Isyarat","Cermin","Titik buta","Olah gerak"]'::jsonb, 0, 'The signal communicates your intention. It does not replace checking the mirrors and blind spot.', 'Isyarat menyampaikan niat anda. Cermin dan titik buta masih perlu diperiksa.', NULL, 'KPP_D_Manual.pdf PDF page 99'),
  ('c7b1435c-dbfd-531a-802a-2f8ca012bda6'::uuid, 'traffic-rules', 'mock-d-2', 24, 'What happens to your stopping distance as your speed rises?', 'Apakah yang berlaku kepada jarak berhenti apabila kelajuan meningkat?', '["It gets shorter","It stays the same","It gets longer","It depends only on the gear"]'::jsonb, '["Jarak menjadi lebih pendek","Jarak kekal sama","Jarak bertambah panjang","Jarak bergantung pada gear sahaja"]'::jsonb, 2, 'At higher speeds you need more distance to stop if traffic ahead brakes suddenly.', 'Pada kelajuan lebih tinggi, anda memerlukan jarak lebih panjang untuk berhenti jika trafik di hadapan membrek mengejut.', NULL, 'KPP_D_Manual.pdf PDF page 100'),
  ('a0150e5b-7e3e-588d-a777-1ae6f5652341'::uuid, 'traffic-rules', 'mock-d-2', 25, 'Which following-gap rule is taught for slippery or sandy roads?', 'Apakah peraturan jarak mengekor yang diajar untuk jalan licin atau berpasir?', '["Two seconds","One second","Four seconds","Three seconds"]'::jsonb, '["Dua saat","Satu saat","Empat saat","Tiga saat"]'::jsonb, 2, 'The longer gap gives more time and room to stop when grip is reduced.', 'Jarak yang lebih panjang memberi lebih banyak masa dan ruang untuk berhenti apabila cengkaman berkurangan.', NULL, 'KPP_D_Manual.pdf PDF page 103'),
  ('5df07229-f419-5e82-b431-9972a0716b34'::uuid, 'traffic-rules', 'mock-d-2', 26, 'How does leaving a gap improve what you can see?', 'Bagaimanakah meninggalkan jarak membantu pandangan anda?', '["It makes signals behind clearer","It eliminates the side blind spots","It removes glare from your mirrors","It opens your view ahead"]'::jsonb, '["Ia menjelaskan isyarat di belakang","Ia menghapuskan titik buta di sisi","Ia menghilangkan silau pada cermin","Ia meluaskan pandangan ke hadapan"]'::jsonb, 3, 'Following too closely lets the vehicle ahead block your view of the surrounding road.', 'Mengekor terlalu rapat membolehkan kenderaan di hadapan menghalang pandangan anda terhadap keadaan jalan sekeliling.', NULL, 'KPP_D_Manual.pdf PDF page 105'),
  ('dbf49443-54aa-5391-9bf3-4fac043cc612'::uuid, 'traffic-rules', 'mock-d-2', 27, 'A pedestrian crossing lies ahead of a slower car. What should you do about passing?', 'Lintasan pejalan kaki terletak di hadapan kereta yang lebih perlahan. Apakah tindakan anda mengenai memotong?', '["Wait until after the crossing","Pass just before the crossing","Pass as the car reaches the crossing","Pass if you signal early"]'::jsonb, '["Tunggu sehingga melepasi lintasan","Potong sebelum tiba di lintasan","Potong ketika kereta tiba di lintasan","Potong jika memberi isyarat awal"]'::jsonb, 0, 'Avoid overtaking on the approach to a pedestrian crossing.', 'Elakkan memotong ketika menghampiri lintasan pejalan kaki.', NULL, 'KPP_D_Manual.pdf PDF page 107'),
  ('30e161b9-794b-5559-b85d-76c8f65796c0'::uuid, 'traffic-rules', 'mock-d-2', 28, 'The rear of the car starts to skid. What should you do first with the accelerator?', 'Bahagian belakang kereta mula terbabas. Apakah tindakan pertama terhadap pedal pemecut?', '["Maintain accelerator pressure","Ease off the accelerator","Increase accelerator pressure","Pump the accelerator pedal"]'::jsonb, '["Kekalkan tekanan pada pemecut","Lepaskan pedal pemecut","Tambahkan tekanan pada pemecut","Pam pedal pemecut"]'::jsonb, 1, 'Release the accelerator rather than continuing to power the skid.', 'Lepaskan pemecut supaya kuasa enjin tidak terus menolak kenderaan yang sedang terbabas.', NULL, 'KPP_D_Manual.pdf PDF page 127'),
  ('1ce528ba-8238-5b37-8367-fa0677e32c9b'::uuid, 'traffic-rules', 'mock-d-2', 29, 'You see smoke from the engine and suspect a fire. What takes priority?', 'Anda melihat asap dari enjin dan mengesyaki kebakaran. Apakah keutamaannya?', '["Stop safely and get people out","Open the bonnet before stopping","Keep driving to the nearest workshop","Wait inside for the smoke to clear"]'::jsonb, '["Berhenti dengan selamat dan keluarkan semua orang","Buka bonet sebelum berhenti","Terus memandu ke bengkel terdekat","Tunggu di dalam sehingga asap hilang"]'::jsonb, 0, 'Stop, turn off the engine and get passengers out before dealing with the fire.', 'Berhenti, matikan enjin dan keluarkan penumpang sebelum menangani kebakaran.', NULL, 'KPP_D_Manual.pdf PDF page 128'),
  ('e2ab1d6f-0cd0-5e58-ae8f-59ca93a847d2'::uuid, 'traffic-rules', 'mock-d-2', 30, 'The bonnet opens and blocks your view. How should you slow down?', 'Bonet terbuka dan menghalang pandangan. Bagaimanakah anda patut memperlahankan kenderaan?', '["Keep your speed constant","Brake hard immediately","Brake progressively","Accelerate briefly first"]'::jsonb, '["Kekalkan kelajuan yang sama","Brek kuat serta-merta","Brek secara beransur-ansur","Pecut sebentar dahulu"]'::jsonb, 2, 'Slow gradually and use the side window for guidance as you move to a safe place.', 'Perlahankan kenderaan beransur-ansur dan gunakan tingkap sisi sebagai panduan untuk bergerak ke tempat selamat.', NULL, 'KPP_D_Manual.pdf PDF page 129'),
  ('415c1ecb-5d24-5210-be86-575dede0d339'::uuid, 'traffic-rules', 'mock-d-2', 31, 'Where is the safest place to stop for a tyre change?', 'Di manakah tempat paling selamat untuk berhenti bagi menukar tayar?', '["A bend with a wider shoulder","A sloped shoulder beside traffic","A level area away from traffic","A level area in the traffic lane"]'::jsonb, '["Selekoh dengan bahu jalan lebih lebar","Bahu jalan bercerun di sebelah trafik","Kawasan rata jauh daripada trafik","Kawasan rata di dalam lorong trafik"]'::jsonb, 2, 'Level ground helps keep the vehicle stable on a jack. Leave enough space from moving traffic.', 'Permukaan rata membantu memastikan kenderaan stabil pada jek. Tinggalkan ruang yang cukup daripada trafik bergerak.', NULL, 'KPP_D_Manual.pdf PDF page 131'),
  ('97eeba90-362a-5777-bb3d-deeeca803c8d'::uuid, 'traffic-rules', 'mock-d-2', 32, 'What should you avoid while the car is supported by a jack?', 'Apakah yang perlu dielakkan ketika kereta disokong oleh jek?', '["Checking the jacking point","Fitting the spare wheel","Going underneath the car","Hand-tightening the wheel nuts"]'::jsonb, '["Memeriksa titik jek","Memasang roda ganti","Masuk ke bawah kereta","Mengetatkan nat roda dengan tangan"]'::jsonb, 2, 'A jack can fail or tip. Keep your body out from underneath the vehicle.', 'Jek boleh gagal atau terbalik. Jangan letakkan badan di bawah kenderaan.', NULL, 'KPP_D_Manual.pdf PDF page 132'),
  ('cb97cefa-8a84-505e-bb7a-b1c6c1885681'::uuid, 'traffic-rules', 'mock-d-2', 33, 'You realise your turn is at the next junction and you are in the wrong lane. What should you avoid?', 'Anda sedar perlu membelok di simpang seterusnya tetapi berada di lorong yang salah. Apakah yang perlu dielakkan?', '["Following the markings in your lane","Checking traffic in the next lane","Cutting across at the last moment","Signalling before a safe lane change"]'::jsonb, '["Mengikut penandaan di lorong anda","Memeriksa trafik di lorong sebelah","Memotong merentas pada saat akhir","Memberi isyarat sebelum menukar lorong dengan selamat"]'::jsonb, 2, 'Plan your route and position early to avoid a sudden lane change near the junction.', 'Rancang laluan dan kedudukan lebih awal supaya tidak menukar lorong secara mengejut berhampiran simpang.', NULL, 'KPP_D_Manual.pdf PDF page 135'),
  ('c9761e96-f435-5bc9-91f3-3438326dbe98'::uuid, 'traffic-rules', 'mock-d-2', 34, 'What extra hazard can a narrow rural bend hide?', 'Apakah bahaya tambahan yang mungkin terlindung di selekoh sempit di luar bandar?', '["Following traffic entering a lay-by","Oncoming traffic entering your lane","Parked traffic facing away from you","Traffic joining behind your car"]'::jsonb, '["Trafik di belakang memasuki ruang rehat","Trafik bertentangan memasuki lorong anda","Kenderaan diparkir menghadap arah lain","Trafik masuk di belakang kereta anda"]'::jsonb, 1, 'A vehicle coming the other way may use part of your lane on a narrow bend.', 'Kenderaan dari arah bertentangan mungkin menggunakan sebahagian lorong anda di selekoh sempit.', NULL, 'KPP_D_Manual.pdf PDF page 136'),
  ('85cd6bb7-a207-59e8-b449-a1ab7707a1c8'::uuid, 'traffic-rules', 'mock-d-2', 35, 'Why avoid driving too fast on a dark rural road?', 'Mengapa perlu elakkan memandu terlalu laju di jalan luar bandar yang gelap?', '["You may spend longer in low gear","You may use your headlights too long","You may meet fewer passing places","You may see a hazard too late"]'::jsonb, '["Anda mungkin lebih lama menggunakan gear rendah","Lampu hadapan mungkin digunakan terlalu lama","Tempat berselisih mungkin semakin kurang","Bahaya mungkin kelihatan terlalu lewat"]'::jsonb, 3, 'Use a speed that lets you stop if an unseen pedestrian or animal appears.', 'Pilih kelajuan yang membolehkan anda berhenti jika pejalan kaki atau haiwan yang tidak kelihatan muncul.', NULL, 'KPP_D_Manual.pdf PDF page 138'),
  ('9edd9a36-0b8f-5d4c-bfbc-0f8e054d9485'::uuid, 'traffic-rules', 'mock-d-2', 36, 'What should you do in a busy market area with pedestrians nearby?', 'Apakah yang patut dilakukan di kawasan pasar sibuk dengan pejalan kaki berhampiran?', '["Move closer to the kerb","Hold speed and sound the horn","Slow down and watch for crossings","Focus on the vehicle ahead"]'::jsonb, '["Gerakkan kenderaan lebih dekat dengan bebendul","Kekalkan kelajuan dan bunyikan hon","Perlahankan kenderaan dan awasi orang melintas","Tumpukan pada kenderaan di hadapan"]'::jsonb, 2, 'People may cross in busy areas. Be ready to give way and obey any crossing signals.', 'Orang mungkin melintas di kawasan sibuk. Bersedia untuk memberi laluan dan patuhi lampu isyarat lintasan.', NULL, 'KPP_D_Manual.pdf PDF page 140'),
  ('b3f04319-8405-5911-ab17-44097b1632c2'::uuid, 'traffic-rules', 'mock-d-2', 37, 'What should you check on the tyres before a long expressway trip?', 'Apakah yang perlu diperiksa pada tayar sebelum perjalanan jauh di lebuh raya?', '["Their pressure and condition","Their pressure after the trip","Their valve caps only","Their surface after the first stop"]'::jsonb, '["Tekanan dan keadaannya","Tekanan selepas perjalanan","Penutup injap sahaja","Permukaan selepas hentian pertama"]'::jsonb, 0, 'Check tyre condition and inflation before setting out.', 'Periksa keadaan dan tekanan angin tayar sebelum memulakan perjalanan.', NULL, 'KPP_D_Manual.pdf PDF page 141'),
  ('cd4fda4b-32d6-50f6-9bc2-d2de47cf21f1'::uuid, 'traffic-rules', 'mock-d-2', 38, 'Where should you go after finishing an expressway overtake?', 'Ke manakah anda perlu bergerak selepas selesai memotong di lebuh raya?', '["Stay between the two lanes","Remain in the overtaking lane","Move into the emergency lane","Back to the driving lane"]'::jsonb, '["Kekal di antara kedua-dua lorong","Kekal di lorong memotong","Masuk ke lorong kecemasan","Kembali ke lorong pemanduan"]'::jsonb, 3, 'Use an overtaking lane to pass. Return to the normal driving lane when safe.', 'Gunakan lorong memotong untuk mendahului. Kembali ke lorong pemanduan apabila selamat.', NULL, 'KPP_D_Manual.pdf PDF page 142'),
  ('cacb5aaa-385e-5cc5-a4a0-2be013ed7344'::uuid, 'traffic-rules', 'mock-d-2', 39, 'Traffic queues on an expressway. Which situation justifies moving into the marked shoulder lane?', 'Trafik beratur di lebuh raya. Keadaan manakah membolehkan anda masuk ke lorong bahu yang bertanda?', '["Your vehicle has broken down","Your exit is just ahead","A passenger is late","You need a short rest"]'::jsonb, '["Kenderaan anda rosak","Susur keluar hampir tiba","Penumpang anda lewat","Anda perlu berehat sebentar"]'::jsonb, 0, 'A slow queue is not an emergency. Stay in the traffic lanes.', 'Barisan trafik perlahan bukan kecemasan. Kekal di lorong trafik.', NULL, 'KPP_D_Manual.pdf PDF page 142'),
  ('05c17ce1-98fd-5333-bbc4-eee57c22162b'::uuid, 'traffic-rules', 'mock-d-2', 40, 'Bright sunlight is scattering across the glass in front of you. What preparation helps reduce it?', 'Cahaya matahari terang berselerak pada kaca di hadapan anda. Persediaan apakah membantu mengurangkannya?', '["Remove dirt from the glass","Raise the rear-view mirror","Move the visor up","Close both side windows"]'::jsonb, '["Bersihkan kotoran pada kaca","Naikkan cermin pandang belakang","Naikkan pengadang matahari","Tutup kedua-dua tingkap sisi"]'::jsonb, 0, 'Clean glass helps reduce glare. Keep enough washer fluid to clean it when needed.', 'Cermin yang bersih membantu mengurangkan silau. Pastikan cecair pencuci mencukupi.', NULL, 'KPP_D_Manual.pdf PDF page 146'),
  ('9ebf0072-5726-57f3-86be-20701441765b'::uuid, 'safety-principles', 'mock-d-2', 41, 'What is one purpose of the KEJARA system?', 'Apakah satu tujuan sistem KEJARA?', '["Track vehicle ownership","Set road speed limits","Reduce repeat offences","Manage driving-test bookings"]'::jsonb, '["Merekod pemilikan kenderaan","Menetapkan had laju jalan","Mengurangkan kesalahan berulang","Mengurus tempahan ujian memandu"]'::jsonb, 2, 'One purpose is to discourage repeat offences by educating and disciplining drivers.', 'Antara tujuannya ialah mengurangkan kesalahan berulang dengan mendidik dan mendisiplinkan pemandu.', NULL, 'KPP General, PDF 94'),
  ('aa18d006-92c8-5966-933c-4365d119d1fd'::uuid, 'safety-principles', 'mock-d-2', 42, 'A driver with a competent licence reaches 20 KEJARA points for the first time. What does the schedule show?', 'Pemegang lesen kompeten mencapai 20 mata KEJARA buat kali pertama. Apakah tindakan dalam jadual?', '["A suspension","A cancellation","A course referral","A warning"]'::jsonb, '["Penggantungan","Pembatalan","Rujukan kursus","Amaran"]'::jsonb, 3, 'The first 20-point threshold shown in the schedule results in a warning.', 'Ambang 20 mata kali pertama dalam jadual ini membawa kepada amaran.', NULL, 'KPP General, PDF 95'),
  ('65d52eb4-6364-5ae8-9e8e-9e7370e20928'::uuid, 'safety-principles', 'mock-d-2', 43, 'What kind of offence can lead to KEJARA points?', 'Apakah jenis kesalahan yang boleh menyebabkan mata KEJARA dikenakan?', '["A scheduled traffic offence","An internal parking charge","An insurance contract breach","A missed service appointment"]'::jsonb, '["Kesalahan trafik terjadual","Caj parkir dalaman","Pelanggaran kontrak insurans","Janji temu servis terlepas"]'::jsonb, 0, 'KEJARA applies to scheduled offences under the road transport rules.', 'KEJARA terpakai kepada kesalahan terjadual di bawah peraturan pengangkutan jalan.', NULL, 'KPP General, PDF 93'),
  ('8621a8b5-ccf6-5ff0-a8af-532c18af66b1'::uuid, 'safety-principles', 'mock-d-2', 44, 'What is the largest percentage deduction listed for KEJARA points?', 'Berapakah peratusan potongan tertinggi yang disenaraikan bagi mata KEJARA?', '["25%","50%","75%","100%"]'::jsonb, '["25%","50%","75%","100%"]'::jsonb, 1, 'The curriculum describes a possible reduction of up to 50% of the demerit points under the listed conditions.', 'Kurikulum menerangkan potongan sehingga 50% daripada mata demerit tertakluk pada syarat yang disenaraikan.', NULL, 'KPP General, PDF 95'),
  ('53eca694-e508-52b1-8e33-f5cfb6f51386'::uuid, 'safety-principles', 'mock-d-2', 45, 'Which plan is allowed while your driving licence is suspended?', 'Rancangan manakah dibenarkan ketika lesen memandu anda digantung?', '["Ask someone else to drive you","Drive a borrowed car to work","Ride a different vehicle class","Take a short drive for essentials"]'::jsonb, '["Minta orang lain memandu anda","Pandu kereta pinjaman ke tempat kerja","Tunggang kenderaan kelas lain","Pandu sekejap untuk urusan penting"]'::jsonb, 0, 'Suspension prevents the person from driving. Changing vehicles does not remove the restriction.', 'Penggantungan melarang orang itu daripada memandu. Menukar kenderaan tidak menamatkan larangan tersebut.', NULL, 'KPP General, PDF 96'),
  ('b3c9cb5a-08ed-51e3-b821-c239d990e478'::uuid, 'safety-principles', 'mock-d-2', 46, 'What must a former probationary driver repeat after a cancellation ban ends?', 'Apakah yang perlu diulang oleh bekas pemegang lesen percubaan selepas larangan pembatalan tamat?', '["The medical form alone","The licence renewal alone","The training and tests","The probation period alone"]'::jsonb, '["Borang kesihatan sahaja","Pembaharuan lesen sahaja","Latihan dan ujian","Tempoh percubaan sahaja"]'::jsonb, 2, 'The curriculum requires the training and tests again, followed by a new probation period.', 'Kurikulum memerlukan latihan dan ujian semula, diikuti tempoh percubaan yang baharu.', NULL, 'KPP Kelas DA Automatik, PDF 21'),
  ('10e29de8-7601-5017-b9b6-2caf1c5fa6a5'::uuid, 'safety-principles', 'mock-d-2', 47, 'What should you look for under the car during a pre-drive walk-around?', 'Apakah yang perlu diperiksa di bawah kereta sebelum memandu?', '["Signs of tread wear","Loose washer nozzles","A blocked air filter","Signs of a leak"]'::jsonb, '["Tanda bunga tayar haus","Muncung pencuci longgar","Penapis udara tersumbat","Tanda kebocoran"]'::jsonb, 3, 'Look underneath to see whether anything is leaking before setting off.', 'Lihat di bawah kereta untuk mengesan sebarang kebocoran sebelum bergerak.', NULL, 'KPP Kelas D Manual, PDF 231'),
  ('0a6405fb-9882-5bfd-b9f6-f702c8ee9d41'::uuid, 'safety-principles', 'mock-d-2', 48, 'What should you check on the number plates during a walk-around?', 'Apakah yang perlu diperiksa pada plat nombor semasa pemeriksaan keliling kereta?', '["Clean and undamaged","Clean with no sharp edges","Straight and freshly painted","Rust-free with new screws"]'::jsonb, '["Bersih dan tidak rosak","Bersih dan tiada bucu tajam","Lurus dan baru dicat","Bebas karat dengan skru baharu"]'::jsonb, 0, 'Check that the plates are clean and undamaged.', 'Pastikan plat nombor bersih dan tidak rosak.', NULL, 'KPP Kelas D Manual, PDF 230'),
  ('45e1a3a7-7ca6-5f3e-9784-e3d90aebdecc'::uuid, 'safety-principles', 'mock-d-2', 49, 'When should you choose a suitable speed for a bend?', 'Bilakah anda perlu memilih kelajuan yang sesuai untuk selekoh?', '["When you reach its middle","While approaching it","After clearing it","When the steering straightens"]'::jsonb, '["Apabila sampai ke tengahnya","Ketika menghampirinya","Selepas melepasinya","Apabila stereng diluruskan"]'::jsonb, 1, 'Choose a suitable speed as you approach, maintain control through the bend, and only increase speed after clearing it.', 'Pilih kelajuan yang sesuai ketika menghampiri selekoh, kekalkan kawalan semasa melaluinya dan tingkatkan kelajuan selepas melepasi selekoh.', NULL, 'KPP Kelas D Manual, PDF 251'),
  ('8af45b8c-c6c4-5116-b897-150b304e2049'::uuid, 'safety-principles', 'mock-d-2', 50, 'Which action does the manual circuit lesson advise against while going through an S-bend?', 'Apakah tindakan yang perlu dielakkan ketika melalui selekoh S dalam latihan litar manual?', '["Steering with both hands","Holding a steady speed","Changing gears","Following the curve"]'::jsonb, '["Memegang stereng dengan dua tangan","Mengekalkan kelajuan","Menukar gear","Mengikut lengkung selekoh"]'::jsonb, 2, 'The lesson says to use the pull-push steering technique, keep speed steady, and avoid gear changes and braking while passing through the bend.', 'Gunakan teknik tarik dan tolak pada stereng, kekalkan kelajuan dan elakkan menukar gear serta membrek semasa melalui selekoh.', NULL, 'KPP Kelas D Manual, PDF 253'),
  ('5bcdb033-14df-503d-977b-02192f80cc63'::uuid, 'road-signs', 'mock-d-3', 4, 'What does this sign prohibit?', 'Apakah larangan pada papan tanda ini?', '["No U-turn","No left turn","No right turn","No parking"]'::jsonb, '["Dilarang membuat pusingan U","Dilarang membelok ke kiri","Dilarang membelok ke kanan","Dilarang meletak kenderaan"]'::jsonb, 3, 'This sign means no parking.', 'Papan tanda ini bermaksud dilarang meletak kenderaan.', '/signs/fbd415b24ab21b44.svg', 'KPP General PDF page 58'),
  ('5e72746c-41d7-5db9-8715-b92b919d1d75'::uuid, 'road-signs', 'mock-d-3', 8, 'What does this sign mean?', 'Apakah maksud papan tanda ini?', '["Traffic shifts lanes ahead","Narrow clearance in work zone","Right bend in work zone","Sharp work-zone diversion"]'::jsonb, '["Lencongan lorong di hadapan","Kelegaan terhad di zon kerja","Selekoh kanan di zon kerja","Lencongan tajam di zon kerja"]'::jsonb, 3, 'This sign means sharp work-zone diversion.', 'Papan tanda ini bermaksud lencongan tajam di zon kerja.', '/signs/263bc825012bcc83.svg', 'KPP General PDF page 76'),
  ('356901c4-b78d-535b-a2bc-4154520ef21b'::uuid, 'road-signs', 'mock-d-3', 13, 'What does this sign prohibit?', 'Apakah larangan pada papan tanda ini?', '["No stopping","No overtaking","No left turn","No parking"]'::jsonb, '["Dilarang berhenti","Dilarang memotong","Dilarang membelok ke kiri","Dilarang meletak kenderaan"]'::jsonb, 0, 'This sign means no stopping.', 'Papan tanda ini bermaksud dilarang berhenti.', '/signs/ecd3d648f3d4a187.svg', 'KPP General PDF page 59'),
  ('79548b75-584a-5529-9325-2a8a569c4551'::uuid, 'road-signs', 'mock-d-3', 14, 'What does this sign prohibit?', 'Apakah larangan pada papan tanda ini?', '["No vehicle entry","No sounding the horn","No left turn","No right turn"]'::jsonb, '["Kenderaan dilarang masuk","Dilarang membunyikan hon","Dilarang membelok ke kiri","Dilarang membelok ke kanan"]'::jsonb, 1, 'This sign means no sounding the horn.', 'Papan tanda ini bermaksud dilarang membunyikan hon.', '/signs/ce55b86645694f5d.svg', 'KPP General PDF page 57'),
  ('57ee00d1-5dfb-553e-9bcf-14e098ef43ad'::uuid, 'traffic-rules', 'mock-d-3', 16, 'You feel too tired to concentrate before leaving. What should you do?', 'Anda terlalu letih untuk memberi tumpuan sebelum bertolak. Apakah tindakan anda?', '["Choose a route with fewer turns","Drive more slowly than usual","Keep a larger gap while driving","Delay the drive until rested"]'::jsonb, '["Pilih laluan yang kurang selekoh","Pandu lebih perlahan daripada biasa","Kekalkan jarak lebih jauh semasa memandu","Tangguhkan perjalanan sehingga segar"]'::jsonb, 3, 'Fatigue undermines concentration. Rest before driving.', 'Keletihan menjejaskan tumpuan. Berehat sebelum memandu.', NULL, 'KPP_D_Manual.pdf PDF page 78'),
  ('09c834f2-5d46-5f0d-971c-c33811d723cc'::uuid, 'traffic-rules', 'mock-d-3', 17, 'Another driver cuts in abruptly. How should you respond?', 'Pemandu lain mencelah secara tiba-tiba. Bagaimanakah anda patut bertindak?', '["Pass them as soon as possible","Move closer to hold your place","Make room and stay calm","Drive beside them to signal displeasure"]'::jsonb, '["Potong mereka secepat mungkin","Rapatkan jarak untuk mengekalkan kedudukan","Beri ruang dan kekal tenang","Pandu di sebelah untuk menunjukkan rasa tidak puas hati"]'::jsonb, 2, 'Retaliating creates a second hazard. Maintain control and let the incident pass.', 'Membalas tindakan itu menambah bahaya. Kekalkan kawalan dan biarkan kejadian itu berlalu.', NULL, 'KPP_D_Manual.pdf PDF page 80'),
  ('417ecd1e-cd3c-5c70-a044-548fc235a6c8'::uuid, 'traffic-rules', 'mock-d-3', 18, 'Before moving right to overtake, you find traffic coming up behind you. What should you do?', 'Sebelum bergerak ke kanan untuk memotong, anda nampak trafik menghampiri dari belakang. Apakah tindakan anda?', '["Wait until it is safe to move","Move right while signalling","Accelerate into the next lane","Move right as the vehicle draws level"]'::jsonb, '["Tunggu sehingga selamat untuk bergerak","Bergerak ke kanan sambil memberi isyarat","Pecut ke lorong sebelah","Bergerak ke kanan ketika kenderaan berada di sisi"]'::jsonb, 0, 'Check behind and beside you before moving right. Change lanes only when it is safe.', 'Periksa belakang dan sisi sebelum bergerak ke kanan. Tukar lorong hanya apabila selamat.', NULL, 'KPP_D_Manual.pdf PDF page 106'),
  ('8ab228c9-87d9-5c4d-8b06-c42e29a66882'::uuid, 'traffic-rules', 'mock-d-3', 19, 'You need more power before passing. What gear change can help?', 'Anda memerlukan lebih kuasa sebelum memotong. Pertukaran gear manakah boleh membantu?', '["Shift briefly to neutral","Select a higher gear","Select a lower gear","Hold the clutch halfway down"]'::jsonb, '["Tukar seketika ke gear bebas","Pilih gear lebih tinggi","Pilih gear lebih rendah","Tekan cekam separuh"]'::jsonb, 2, 'A suitable lower gear can supply more power for the manoeuvre.', 'Gear rendah yang sesuai boleh memberikan lebih kuasa untuk olah gerak itu.', NULL, 'KPP_D_Manual.pdf PDF page 106'),
  ('59cad376-2d56-5087-9abd-5dc293acd692'::uuid, 'traffic-rules', 'mock-d-3', 20, 'Which mirror helps confirm the vehicle you passed is far enough behind before you return left?', 'Cermin manakah membantu mengesahkan kenderaan yang dipotong sudah cukup jauh di belakang sebelum kembali ke kiri?', '["Right side mirror","Left side mirror","Interior rear-view mirror only","Any mirror showing the kerb"]'::jsonb, '["Cermin sisi kanan","Cermin sisi kiri","Cermin pandang belakang sahaja","Mana-mana cermin yang menunjukkan bebendul"]'::jsonb, 1, 'Check the left side mirror for the front of the vehicle you passed. Use CITO before returning.', 'Periksa cermin sisi kiri untuk melihat bahagian hadapan kenderaan yang dipotong. Gunakan CITO sebelum kembali.', NULL, 'KPP_D_Manual.pdf PDF page 106'),
  ('9f3a75b6-3c82-550e-b9ff-d54bb4617818'::uuid, 'traffic-rules', 'mock-d-3', 21, 'You are following a slow car into a blind bend. What should you do?', 'Anda mengekori kereta perlahan memasuki selekoh terlindung. Apakah tindakan anda?', '["Stay back until the road opens up","Pass before entering the bend","Move out briefly to check ahead","Pass when the car slows further"]'::jsonb, '["Kekal di belakang sehingga jalan jelas","Potong sebelum memasuki selekoh","Keluar sebentar untuk melihat ke hadapan","Potong apabila kereta lebih perlahan"]'::jsonb, 0, 'Do not overtake at a bend where you cannot see approaching traffic.', 'Jangan memotong di selekoh apabila trafik dari arah bertentangan tidak dapat dilihat.', NULL, 'KPP_D_Manual.pdf PDF page 107'),
  ('9e47d5f6-c893-5262-9459-1e86eab721f6'::uuid, 'traffic-rules', 'mock-d-3', 22, 'An oncoming car crosses into your lane. What should you do about speed?', 'Kereta dari arah bertentangan masuk ke lorong anda. Apakah tindakan terhadap kelajuan?', '["Ease off and slow down","Hold your present speed","Speed up to pass sooner","Coast with no braking"]'::jsonb, '["Lepaskan pemecut dan perlahankan kenderaan","Kekalkan kelajuan semasa","Pecut untuk berselisih lebih awal","Luncur tanpa membrek"]'::jsonb, 0, 'Reduce speed while keeping control. Check that it is safe before moving left.', 'Kurangkan kelajuan sambil mengekalkan kawalan. Pastikan selamat sebelum bergerak ke kiri.', NULL, 'KPP_D_Manual.pdf PDF page 108'),
  ('9351e1af-01dd-5ff5-ac81-f7ad1263b707'::uuid, 'traffic-rules', 'mock-d-3', 23, 'You have priority at a junction. How should you approach it?', 'Anda mempunyai keutamaan di persimpangan. Bagaimanakah anda patut menghampirinya?', '["Wait until the junction is behind you to slow","Maintain speed until traffic enters","Accelerate to clear it quickly","Slow and watch for other traffic"]'::jsonb, '["Tunggu sehingga melepasi simpang sebelum memperlahankan kenderaan","Kekalkan kelajuan sehingga trafik masuk","Pecut untuk melepasi simpang dengan cepat","Perlahankan kenderaan dan awasi trafik lain"]'::jsonb, 3, 'Priority does not prevent another road user from entering your path.', 'Keutamaan tidak menghalang pengguna jalan lain daripada memasuki laluan anda.', NULL, 'KPP_D_Manual.pdf PDF page 109'),
  ('be71c763-c369-5d86-b5f2-5e1496f3cd26'::uuid, 'traffic-rules', 'mock-d-3', 24, 'At a roundabout entry, which approaching traffic should you give way to?', 'Di pintu masuk bulatan, kepada trafik dari arah mana anda patut beri laluan?', '["Traffic from the right","Traffic from the left","Traffic behind you","Traffic waiting opposite"]'::jsonb, '["Trafik dari arah kanan","Trafik dari arah kiri","Trafik di belakang anda","Trafik yang menunggu bertentangan"]'::jsonb, 0, 'Select the correct lane before entering and give priority to traffic approaching from the right.', 'Pilih lorong yang betul sebelum masuk dan beri keutamaan kepada trafik dari arah kanan.', NULL, 'KPP_D_Manual.pdf PDF page 115'),
  ('89a1970e-b9c1-58bd-bb8c-1371d67bfe75'::uuid, 'traffic-rules', 'mock-d-3', 25, 'What do you use to warn traffic when forced to stop at the roadside in an emergency?', 'Apakah yang digunakan untuk memberi amaran apabila terpaksa berhenti di tepi jalan semasa kecemasan?', '["Right turn signal","Dipped headlights","Interior lights","Hazard lights"]'::jsonb, '["Lampu isyarat kanan","Lampu rendah","Lampu kabin","Lampu kecemasan"]'::jsonb, 3, 'Hazard lights warn others that your vehicle has stopped in an emergency.', 'Lampu kecemasan memberi amaran bahawa kenderaan anda berhenti dalam keadaan kecemasan.', NULL, 'KPP_D_Manual.pdf PDF page 119'),
  ('31f81eaa-3773-5542-ac87-f34beb1829db'::uuid, 'traffic-rules', 'mock-d-3', 26, 'A storm makes it hard to see enough road to continue safely. What should you do?', 'Ribut menyebabkan pandangan terlalu terhad untuk meneruskan perjalanan dengan selamat. Apakah tindakan anda?', '["Keep going with high beam","Follow the next car closely","Continue along the road edge","Stop somewhere safe"]'::jsonb, '["Teruskan dengan lampu tinggi","Ikut kereta di hadapan dengan rapat","Teruskan di sepanjang tepi jalan","Berhenti di tempat yang selamat"]'::jsonb, 3, 'When visibility becomes too poor, pause your journey in a safe place.', 'Apabila penglihatan terlalu terhad, hentikan perjalanan sementara di tempat selamat.', NULL, 'KPP_D_Manual.pdf PDF page 122'),
  ('655d485f-cd01-57e4-830a-17577f76303b'::uuid, 'traffic-rules', 'mock-d-3', 27, 'Bright sun glare makes the road difficult to see. What should you adjust first?', 'Silau matahari menyebabkan jalan sukar dilihat. Apakah yang perlu dilaraskan dahulu?', '["Increase the dashboard brightness","Raise your seating position","Reduce your speed","Move nearer to the road centre"]'::jsonb, '["Tambah kecerahan papan pemuka","Naikkan kedudukan tempat duduk","Kurangkan kelajuan","Bergerak lebih dekat ke tengah jalan"]'::jsonb, 2, 'Match your speed to what you can see so you have time to react.', 'Sesuaikan kelajuan dengan jarak penglihatan supaya anda mempunyai masa untuk bertindak.', NULL, 'KPP_D_Manual.pdf PDF page 123'),
  ('67755d35-6a62-575c-9c56-e72c67bf0311'::uuid, 'traffic-rules', 'mock-d-3', 28, 'When can high beam help on an unlit road?', 'Bilakah lampu tinggi boleh membantu di jalan tanpa lampu jalan?', '["When driving through busy streets","When approaching oncoming traffic","When following a car closely","When it will not dazzle anyone"]'::jsonb, '["Apabila melalui jalan yang sibuk","Apabila trafik bertentangan menghampiri","Apabila mengekori kereta dengan rapat","Apabila tidak menyilaukan orang lain"]'::jsonb, 3, 'High beam extends your view but should not be used where it dazzles others.', 'Lampu tinggi memanjangkan jarak penglihatan tetapi tidak patut digunakan jika menyilaukan orang lain.', NULL, 'KPP_D_Manual.pdf PDF page 145'),
  ('6a9039da-76f4-5bf2-b316-fe100d35e243'::uuid, 'traffic-rules', 'mock-d-3', 29, 'Why allow extra stopping room on a wet road?', 'Mengapa perlu sediakan ruang berhenti tambahan di jalan basah?', '["Tyre pressure rises quickly","Tyres have more rolling resistance","Tyres have less grip","The brake pedal travels farther"]'::jsonb, '["Tekanan tayar meningkat cepat","Rintangan gelinciran tayar bertambah","Cengkaman tayar berkurangan","Pedal brek bergerak lebih jauh"]'::jsonb, 2, 'Reduced grip increases the distance needed to stop.', 'Cengkaman yang berkurangan meningkatkan jarak yang diperlukan untuk berhenti.', NULL, 'KPP_D_Manual.pdf PDF page 147'),
  ('cd876540-13cc-5e92-88ad-de6a303e5929'::uuid, 'traffic-rules', 'mock-d-3', 30, 'What can a strong crosswind do to a small car?', 'Apakah kesan angin lintang kuat terhadap kereta kecil?', '["Make it accelerate downhill","Pull it backwards","Push it sideways","Make it turn into the wind"]'::jsonb, '["Membuatnya memecut menuruni bukit","Menariknya ke belakang","Menolaknya ke sisi","Membuatnya membelok ke arah angin"]'::jsonb, 2, 'A gust can displace the car toward an adjacent lane.', 'Tiupan angin boleh menolak kereta ke arah lorong bersebelahan.', NULL, 'KPP_D_Manual.pdf PDF page 148'),
  ('9ae33f48-da3b-52f0-a188-fb1423a118be'::uuid, 'traffic-rules', 'mock-d-3', 31, 'Floodwater ahead looks too deep for the car. What should you do?', 'Air banjir di hadapan kelihatan terlalu dalam untuk kereta. Apakah tindakan anda?', '["Cross behind a larger vehicle","Turn back and take another route","Try the middle of the road","Build speed before entering"]'::jsonb, '["Lintas di belakang kenderaan lebih besar","Patah balik dan guna laluan lain","Cuba melalui bahagian tengah jalan","Tambah kelajuan sebelum masuk"]'::jsonb, 1, 'Do not risk deep water. Water entering the air intake can damage the engine.', 'Jangan mengambil risiko melalui air dalam. Air yang memasuki salur masuk udara boleh merosakkan enjin.', NULL, 'KPP_D_Manual.pdf PDF page 149'),
  ('df31348e-a419-575e-b76b-102867178704'::uuid, 'traffic-rules', 'mock-d-3', 32, 'A slow car is ahead on a two-way road in fog. What should you do?', 'Kereta perlahan berada di hadapan di jalan dua hala yang berkabus. Apakah tindakan anda?', '["Close in until the fog thins","Pass using the centre line","Follow at a safe gap","Pass with your hazards on"]'::jsonb, '["Rapatkan jarak sehingga kabus menipis","Potong dengan menggunakan garisan tengah","Ikut pada jarak yang selamat","Potong dengan lampu kecemasan dihidupkan"]'::jsonb, 2, 'Fog makes it hard to judge oncoming traffic, so avoid overtaking and leave room to stop.', 'Kabus menyukarkan anda menilai trafik bertentangan. Elakkan memotong dan tinggalkan ruang untuk berhenti.', NULL, 'KPP_D_Manual.pdf PDF page 150'),
  ('dc758881-f847-50de-961c-f263ba63cd77'::uuid, 'traffic-rules', 'mock-d-3', 33, 'Before a trip, how do you check the engine oil level under the bonnet?', 'Sebelum bertolak, bagaimanakah anda memeriksa paras minyak enjin di bawah bonet?', '["Read the marks on the dipstick","Look through the filler opening","Read the level on the coolant tank","Check the colour under the oil cap"]'::jsonb, '["Baca tanda pada batang celup","Lihat melalui lubang pengisi","Baca paras pada tangki penyejuk","Periksa warna di bawah penutup minyak"]'::jsonb, 0, 'Use the dipstick to check the oil level during regular maintenance.', 'Gunakan batang penyukat untuk memeriksa aras minyak semasa penyelenggaraan berkala.', NULL, 'KPP_D_Manual.pdf PDF page 152'),
  ('32d88450-38a6-5530-9886-b64b0d36c6e5'::uuid, 'traffic-rules', 'mock-d-3', 34, 'Which condition is the cooling system, including the radiator, designed to prevent?', 'Keadaan manakah yang direka untuk dicegah oleh sistem penyejukan, termasuk radiator?', '["The engine overheating","The engine oil running low","The fuel supply running low","The battery losing its charge"]'::jsonb, '["Enjin terlalu panas","Minyak enjin berkurang","Bekalan bahan api berkurang","Bateri kehilangan cas"]'::jsonb, 0, 'The radiator is part of the cooling system that regulates engine temperature.', 'Radiator ialah sebahagian daripada sistem penyejuk yang mengawal suhu enjin.', NULL, 'KPP_D_Manual.pdf PDF page 153'),
  ('34f80ea5-4009-524c-8aae-cc440b0b5413'::uuid, 'traffic-rules', 'mock-d-3', 35, 'You find a hose loose during a check under the bonnet. What should happen before the trip?', 'Anda menemui hos longgar semasa memeriksa ruang enjin. Apakah yang perlu dilakukan sebelum perjalanan?', '["Secure or replace the hose","Top up fluid and leave it loose","Drive until the engine warms","Recheck only if a warning appears"]'::jsonb, '["Ketatkan atau gantikan hos","Tambah cecair dan biarkan longgar","Pandu sehingga enjin panas","Periksa semula jika amaran muncul"]'::jsonb, 0, 'Inspect hoses for leaks and loose fittings. Tighten or replace a faulty hose.', 'Periksa hos untuk kebocoran dan sambungan longgar. Ketatkan atau gantikan hos yang rosak.', NULL, 'KPP_D_Manual.pdf PDF page 155'),
  ('c2fe6719-7d41-5321-aa8a-0e00a6896dd5'::uuid, 'traffic-rules', 'mock-d-3', 36, 'You are travelling only a short distance. When should you fasten your seat belt?', 'Anda hanya akan bergerak dalam jarak dekat. Bilakah tali pinggang keledar perlu dipasang?', '["When joining the main road","After leaving the car park","Before moving off","When the speed rises"]'::jsonb, '["Apabila memasuki jalan utama","Selepas keluar dari tempat letak kereta","Sebelum mula bergerak","Apabila kelajuan meningkat"]'::jsonb, 2, 'Wear a seat belt even on a short trip.', 'Pakai tali pinggang keledar walaupun untuk perjalanan singkat.', NULL, 'KPP_D_Manual.pdf PDF page 157'),
  ('e53e2457-81d5-53a4-b2dd-4f65d960ab50'::uuid, 'traffic-rules', 'mock-d-3', 37, 'Why use an appropriate child restraint?', 'Mengapa perlu menggunakan kerusi keselamatan kanak-kanak yang sesuai?', '["To stop the rear door opening","To reduce injuries in a crash","To improve the driver''s rear view","To keep the child from using a window"]'::jsonb, '["Untuk mengelakkan pintu belakang dibuka","Untuk mengurangkan kecederaan dalam kemalangan","Untuk memperbaik pandangan belakang pemandu","Untuk mengelakkan kanak-kanak menggunakan tingkap"]'::jsonb, 1, 'A child restraint helps protect a child passenger if a collision happens.', 'Kerusi keselamatan kanak-kanak membantu melindungi penumpang kanak-kanak jika berlaku perlanggaran.', NULL, 'KPP_D_Manual.pdf PDF page 158'),
  ('3e68cf9b-13eb-50ab-b278-d751e4cac42a'::uuid, 'traffic-rules', 'mock-d-3', 38, 'What does the rear-door child lock do?', 'Apakah fungsi kunci keselamatan kanak-kanak pada pintu belakang?', '["Prevents opening from inside","Prevents opening from outside","Locks the rear window in place","Locks the rear seat belt buckle"]'::jsonb, '["Menghalang pintu dibuka dari dalam","Menghalang pintu dibuka dari luar","Mengunci kedudukan tingkap belakang","Mengunci kepala tali pinggang belakang"]'::jsonb, 0, 'It prevents a child from opening the rear door using the inside handle.', 'Kunci itu menghalang kanak-kanak daripada membuka pintu belakang menggunakan pemegang dalam.', NULL, 'KPP_D_Manual.pdf PDF page 159'),
  ('8daf660e-b757-5e0d-8b01-2a4bf2c92fd2'::uuid, 'traffic-rules', 'mock-d-3', 39, 'What is an airbag designed to do in a collision?', 'Apakah tujuan beg udara apabila berlaku perlanggaran?', '["Keep the doors from unlocking","Stop the tyres from skidding","Hold the steering wheel straight","Reduce the force on occupants"]'::jsonb, '["Menghalang pintu daripada terbuka kunci","Menghalang tayar daripada tergelincir","Memastikan stereng kekal lurus","Mengurangkan daya pada penumpang"]'::jsonb, 3, 'The airbag cushions occupants against the impact of a collision.', 'Beg udara membantu mengurangkan kesan hentaman perlanggaran pada penghuni kenderaan.', NULL, 'KPP_D_Manual.pdf PDF page 160'),
  ('b46d73fb-f845-5a29-b60a-7058f30346da'::uuid, 'traffic-rules', 'mock-d-3', 40, 'Washer fluid sprays normally but the wipers leave streaks. What should you inspect first?', 'Cecair pencuci menyembur seperti biasa tetapi pengelap meninggalkan kesan jalur. Apakah yang patut diperiksa dahulu?', '["The wiper blades","The washer nozzles","The washer pump","The wiper fuse"]'::jsonb, '["Bilah pengelap","Muncung pencuci","Pam pencuci","Fius pengelap"]'::jsonb, 0, 'Wiper blades sweep water from the glass so you can see ahead.', 'Bilah pengelap menyapu air dari cermin supaya anda dapat melihat ke hadapan.', NULL, 'KPP_D_Manual.pdf PDF page 154'),
  ('18e01076-7ba2-543f-bdf7-66082e224244'::uuid, 'safety-principles', 'mock-d-3', 41, 'Which finding means a wiper blade may leave water on the windscreen?', 'Penemuan manakah menunjukkan bilah pengelap mungkin meninggalkan air pada cermin?', '["The rubber bends easily","The edge has small splits","The edge lies flat on the glass","The blade follows the glass curve"]'::jsonb, '["Getah mudah melentur","Tepi bilah ada rekahan kecil","Tepi bilah rata pada cermin","Bilah mengikut lengkung cermin"]'::jsonb, 1, 'Hardened, cracked or torn blade rubber may leave water behind or scratch the glass.', 'Getah bilah yang keras, retak atau koyak mungkin meninggalkan air atau mencalarkan cermin.', NULL, 'KPP Kelas D Manual, PDF 229'),
  ('694e5c35-aefc-5bb3-9438-666a5547118e'::uuid, 'safety-principles', 'mock-d-3', 42, 'Where does the curriculum say to look for the car manufacturer’s recommended tyre inflation?', 'Di manakah kurikulum menyatakan anda boleh melihat cadangan pengeluar tentang angin tayar kereta?', '["On the tyre tread label","On the wheel nut cap","On the driver’s door label","On the windscreen sticker"]'::jsonb, '["Pada label bunga tayar","Pada penutup nat roda","Pada label pintu pemandu","Pada pelekat cermin hadapan"]'::jsonb, 2, 'Look for the manufacturer’s tyre pressure label on the side of the driver’s door.', 'Cari label tekanan angin tayar pengeluar di bahagian tepi pintu pemandu.', NULL, 'KPP Kelas D Manual, PDF 228'),
  ('cb8bd8de-5ba1-53e7-97f1-421021d64562'::uuid, 'safety-principles', 'mock-d-3', 43, 'Which tyre fails the visual condition check even if its tread is deep?', 'Tayar manakah gagal pemeriksaan fizikal walaupun bunganya masih dalam?', '["A tyre with even wear","A tyre with deep grooves","A tyre with mould marks","A tyre with a bulge"]'::jsonb, '["Tayar yang haus sekata","Tayar dengan alur dalam","Tayar dengan kesan acuan","Tayar yang menggelembung"]'::jsonb, 3, 'During the visual inspection, check that tyres are free from bulges, cracks and tears.', 'Pastikan tayar tidak menggelembung, merekah atau koyak semasa pemeriksaan.', NULL, 'KPP Kelas D Manual, PDF 228'),
  ('4baeaa90-9d8b-52b8-bff0-80b4e084cc2e'::uuid, 'safety-principles', 'mock-d-3', 44, 'A workshop finds that the wheel angles are out of specification. Which service addresses that problem?', 'Bengkel mendapati sudut roda tidak mengikut spesifikasi. Servis manakah membetulkan masalah itu?', '["Wheel alignment","Wheel balancing","Brake adjustment","Wheel bearing service"]'::jsonb, '["Penjajaran roda","Pengimbangan roda","Pelarasan brek","Servis galas roda"]'::jsonb, 0, 'Correct wheel alignment helps the tyre tread wear evenly. The book describes wheel balancing separately as a way to reduce vibration.', 'Penjajaran roda yang betul membantu bunga tayar haus secara sekata. Pengimbangan roda pula membantu mengurangkan gegaran.', NULL, 'KPP Kelas D Manual, PDF 228'),
  ('07ca1e4f-6883-58ae-b1e8-3fbb6b1c565b'::uuid, 'safety-principles', 'mock-d-3', 45, 'Where should the engine oil level sit on the dipstick?', 'Di manakah paras minyak enjin sepatutnya berada pada batang penyukat?', '["Below the lower mark","Between the two marks","Above the upper mark","Exactly on the lower mark"]'::jsonb, '["Di bawah tanda bawah","Antara kedua-dua tanda","Di atas tanda atas","Tepat pada tanda bawah"]'::jsonb, 1, 'The book says to check that the level is between the minimum and maximum marks.', 'Buku menyatakan paras minyak perlu berada antara tanda minimum dan maksimum.', NULL, 'KPP Kelas D Manual, PDF 232'),
  ('44dd082e-766e-54df-9470-3acc206c1f6e'::uuid, 'safety-principles', 'mock-d-3', 46, 'The washer reservoir is accessible under the bonnet. Which check can you do there?', 'Takungan pencuci boleh dicapai di bawah bonet. Pemeriksaan manakah boleh dibuat di situ?', '["Check whether fluid needs topping up","Check whether fluid reaches the glass","Check how far the fluid sprays","Check which spray jet is blocked"]'::jsonb, '["Semak sama ada cecair perlu ditambah","Semak sama ada cecair sampai ke kaca","Semak sejauh mana cecair menyembur","Semak muncung semburan yang tersumbat"]'::jsonb, 0, 'Check that the washer reservoir contains enough fluid.', 'Pastikan cecair dalam tangki pencuci cermin mencukupi.', NULL, 'KPP Kelas D Manual, PDF 233'),
  ('41763cad-ccea-5f5c-bf49-4f7d6bf6e88e'::uuid, 'safety-principles', 'mock-d-3', 47, 'Which hose condition should you report during a check under the bonnet?', 'Keadaan hos manakah yang perlu dilaporkan semasa pemeriksaan di bawah bonet?', '["A smooth curved route","An intact hose clamp","A dry outer surface","A crack or a bulge"]'::jsonb, '["Laluan melengkung licin","Pengapit hos masih elok","Permukaan luar kering","Rekah atau bengkak"]'::jsonb, 3, 'Check that hoses have no leaks, cracks or swelling.', 'Pastikan hos tidak bocor, merekah atau mengembang.', NULL, 'KPP Kelas D Manual, PDF 234'),
  ('72bff160-f324-5e6d-9026-f1cecd08b827'::uuid, 'safety-principles', 'mock-d-3', 48, 'When replacing a tyre, which tool loosens the nuts before you remove the wheel?', 'Ketika mengganti tayar, alat manakah melonggarkan nat sebelum roda ditanggalkan?', '["A wheel brace","A tyre lever","A pressure gauge","A tow hook"]'::jsonb, '["Sepana roda","Tuil tayar","Tolok tekanan","Cangkuk tunda"]'::jsonb, 0, 'The book includes a wheel-nut wrench among the emergency tools to check in the boot.', 'Buku menyenaraikan pembuka nat roda antara peralatan kecemasan yang perlu diperiksa dalam but.', NULL, 'KPP Kelas D Manual, PDF 231'),
  ('871b9d49-61ae-503d-bd12-38d0f4eef142'::uuid, 'safety-principles', 'mock-d-3', 49, 'What should you do with the accelerator as you press the clutch to change gear?', 'Apakah yang perlu dibuat dengan pemecut apabila menekan cekam untuk menukar gear?', '["Press the accelerator slightly","Release the accelerator","Keep the pressure unchanged","Press it in short bursts"]'::jsonb, '["Tekan pemecut sedikit","Lepaskan pemecut","Kekalkan tekanan yang sama","Tekan secara berulang"]'::jsonb, 1, 'Release the accelerator when pressing the clutch to change gear.', 'Lepaskan pemecut semasa menekan cekam untuk menukar gear.', NULL, 'KPP Kelas D Manual, PDF 218'),
  ('dcd2782a-942e-5f1a-b4da-7333b48fcb48'::uuid, 'safety-principles', 'mock-d-3', 50, 'After setting off on the downhill part of the manual hill exercise, how does the textbook say to apply the accelerator?', 'Selepas mula bergerak menuruni bukit dalam latihan manual, bagaimanakah pemecut perlu ditekan mengikut buku?', '["Apply it all at once","Apply it in short bursts","Apply it gently","Hold it fully down"]'::jsonb, '["Tekan sekaligus","Tekan secara berulang","Tekan perlahan-lahan","Tekan hingga habis"]'::jsonb, 2, 'The procedure says to apply the accelerator gently to attain a safe speed for leaving the exercise.', 'Prosedur menyatakan pemecut perlu ditekan perlahan-lahan untuk mencapai kelajuan yang selamat.', NULL, 'KPP Kelas D Manual, PDF 279')
ON CONFLICT (set_id, order_index) DO UPDATE SET
  category = EXCLUDED.category,
  question_en = EXCLUDED.question_en,
  question_ms = EXCLUDED.question_ms,
  options_en = EXCLUDED.options_en,
  options_ms = EXCLUDED.options_ms,
  correct_index = EXCLUDED.correct_index,
  explanation_en = EXCLUDED.explanation_en,
  explanation_ms = EXCLUDED.explanation_ms,
  image_url = EXCLUDED.image_url,
  source_url = EXCLUDED.source_url;

-- ─── Update Secure Practice View to Include All Practice Sets (quiz-*) ─────
CREATE OR REPLACE VIEW public.kpp_practice_questions
WITH (security_invoker = false, security_barrier = true)
AS
  SELECT
    id,
    category,
    set_id,
    order_index,
    question_en,
    question_ms,
    options_en,
    options_ms,
    correct_index,
    explanation_en,
    explanation_ms,
    image_url,
    source_url,
    created_at
  FROM public.kpp_questions
  WHERE set_id = 'quiz-pool' OR set_id LIKE 'quiz-%';

GRANT SELECT ON public.kpp_practice_questions TO authenticated, anon;

-- ─── Update Authoritative Score Recompute Trigger for New Set IDs ─────────
CREATE OR REPLACE FUNCTION public.recompute_exam_score()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_score integer := 0;
  v_total integer;
  v_q_id_text text;
  v_sel_idx_text text;
  v_q_uuid uuid;
  v_sel_idx integer;
  v_correct integer;
  v_set text;
  v_seen uuid[] := ARRAY[]::uuid[];
BEGIN
  IF NEW.answers IS NULL OR jsonb_typeof(NEW.answers) <> 'object' THEN
    RAISE EXCEPTION 'Answers must be a JSON object' USING ERRCODE = '22023';
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.user_id IS DISTINCT FROM OLD.user_id THEN
    RAISE EXCEPTION 'Cannot modify result owner' USING ERRCODE = '42501';
  END IF;

  IF TG_TABLE_NAME = 'mock_test_results' THEN
    IF NEW.set_id IS NULL OR NEW.set_id NOT IN (
      'mock-1', 'mock-2', 'mock-3',
      'mock-da-1', 'mock-da-2', 'mock-da-3', 'mock-da-4', 'mock-da-5', 'mock-da-6',
      'mock-d-1', 'mock-d-2', 'mock-d-3', 'mock-d-4', 'mock-d-5', 'mock-d-6'
    ) THEN
      RAISE EXCEPTION 'Invalid mock set_id' USING ERRCODE = '22023';
    END IF;
    SELECT count(*) INTO v_total FROM public.kpp_questions WHERE set_id = NEW.set_id;
    IF v_total = 0 THEN
      RAISE EXCEPTION 'Empty mock set' USING ERRCODE = '22023';
    END IF;
  ELSIF TG_TABLE_NAME = 'quiz_results' THEN
    v_total := cardinality(NEW.question_ids);
    IF v_total IS NULL OR v_total = 0 OR v_total <> (
      SELECT count(DISTINCT id) FROM unnest(NEW.question_ids) AS selection(id)
    ) THEN
      RAISE EXCEPTION 'Quiz selection must be nonempty and distinct' USING ERRCODE = '22023';
    END IF;
    IF v_total <> (
      SELECT count(*) FROM public.kpp_questions
      WHERE id = ANY(NEW.question_ids) AND (set_id = 'quiz-pool' OR set_id LIKE 'quiz-%')
    ) THEN
      RAISE EXCEPTION 'Quiz selection must belong to the practice pool' USING ERRCODE = '22023';
    END IF;
  ELSE
    RAISE EXCEPTION 'Unsupported grading table' USING ERRCODE = '22023';
  END IF;

  FOR v_q_id_text, v_sel_idx_text IN SELECT key, value FROM jsonb_each_text(NEW.answers) LOOP
    BEGIN
      v_q_uuid := v_q_id_text::uuid;
      v_sel_idx := v_sel_idx_text::integer;
    EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
      RAISE EXCEPTION 'Malformed question UUID or answer index' USING ERRCODE = '22023';
    END;
    IF v_q_uuid = ANY(v_seen) THEN
      RAISE EXCEPTION 'Duplicate parsed question UUID' USING ERRCODE = '22023';
    END IF;
    v_seen := array_append(v_seen, v_q_uuid);
    IF v_sel_idx IS NULL OR v_sel_idx < 0 OR v_sel_idx > 3 THEN
      RAISE EXCEPTION 'Impossible answer option index' USING ERRCODE = '22023';
    END IF;
    SELECT correct_index, set_id INTO v_correct, v_set
    FROM public.kpp_questions WHERE id = v_q_uuid;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Unknown question ID' USING ERRCODE = '22023';
    END IF;
    IF TG_TABLE_NAME = 'mock_test_results' THEN
      IF v_set <> NEW.set_id THEN
        RAISE EXCEPTION 'Foreign-set answer' USING ERRCODE = '22023';
      END IF;
    ELSIF NOT (v_q_uuid = ANY(NEW.question_ids)) THEN
      RAISE EXCEPTION 'Undeclared quiz answer' USING ERRCODE = '22023';
    END IF;
    IF v_sel_idx = v_correct THEN
      v_score := v_score + 1;
    END IF;
  END LOOP;

  NEW.total_questions := v_total;
  NEW.score := v_score;
  NEW.percentage := round(100 * v_score::numeric / v_total, 2);
  IF TG_TABLE_NAME = 'mock_test_results' THEN
    NEW.passed := NEW.percentage >= 84;
  END IF;
  RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION public.recompute_exam_score() FROM PUBLIC, anon, authenticated;
